import type { BankQuestion } from "@/lib/bank";

/** Business Economics & Strategy (Management & Commerce): 643 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-business-economics-1","question":"Other things remaining the same, a fall in the price of tea leads to:","options":["A rightward shift of the demand curve for tea","A leftward shift of the supply curve of tea","A movement up along the demand curve for tea","A movement down along the demand curve for tea"],"answer":3,"explanation":"A change in the good's own price changes quantity demanded, shown as a movement along the existing demand curve. Shifts come from income, prices of related goods, tastes and similar factors.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-2","question":"If consumers' incomes rise, the demand curve for a normal good:","options":["Shifts to the right","Shifts to the left","Does not move; quantity demanded rises along the curve","Becomes vertical"],"answer":0,"explanation":"For a normal good, higher income raises demand at every price, so the whole curve shifts right. For an inferior good it would shift left.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-3","question":"Demand is Qd = 100 − 2P and supply is Qs = 20 + 3P. What are the equilibrium price and quantity?","options":["P = ₹20, Q = 60","P = ₹16, Q = 68","P = ₹24, Q = 52","P = ₹16, Q = 84"],"answer":1,"explanation":"100 − 2P = 20 + 3P → 5P = 80 → P = 16; Q = 100 − 32 = 68 (check: 20 + 48 = 68). P = 20 comes from dropping the supply intercept.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-4","question":"When the price of a snack rises from ₹10 to ₹12, weekly sales fall from 100 to 80 packets. Using the midpoint (arc) method, what is the price elasticity of demand (absolute value)?","options":["1.00","1.50","1.22","0.82"],"answer":2,"explanation":"%ΔQ = 20/90 = 22.22%; %ΔP = 2/11 = 18.18%; elasticity = 22.22/18.18 = 1.22. Using the initial values gives 20%/20% = 1.00, and using the final values gives 25%/16.67% = 1.50, which is why the midpoint method is used.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-5","question":"A firm's price elasticity of demand is −0.4. If it raises its price by 10%, total revenue will change by approximately:","options":["+5.6%","+6.0%","−4.0%","+14.0%"],"answer":0,"explanation":"Quantity falls by 0.4 × 10% = 4%. New revenue = 1.10 × 0.96 = 1.056 of the old, i.e. +5.6%. +6% is the rough additive approximation (10 − 4) that ignores the cross term. With inelastic demand a price rise raises revenue.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-6","question":"Demand is Q = 200 − 4P. What is the point price elasticity of demand at P = 30?","options":["−0.67","−4.0","−1.5","−1.2"],"answer":2,"explanation":"At P = 30, Q = 80. Elasticity = (dQ/dP) × P/Q = −4 × 30/80 = −1.5. −0.67 inverts P/Q; −4 is just the slope.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-7","question":"With demand Q = 200 − 4P, at what price is total revenue maximised, and what is the elasticity there?","options":["₹50, elasticity −1","₹25, elasticity −1","₹25, elasticity −2","₹30, elasticity −1.5"],"answer":1,"explanation":"TR = P(200 − 4P) = 200P − 4P²; dTR/dP = 200 − 8P = 0 → P = 25, Q = 100. Elasticity = −4 × 25/100 = −1: revenue peaks where demand is unit-elastic. ₹50 is the choke price.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-8","question":"When household incomes rise by 8%, demand for air travel rises by 12%. The good is:","options":["A necessity, with income elasticity 0.67","An inferior good, with income elasticity −1.5","A luxury, with income elasticity 0.67","A luxury, with income elasticity 1.5"],"answer":3,"explanation":"Income elasticity = 12%/8% = 1.5. Greater than 1 means demand grows faster than income: a luxury (a normal good). A necessity has 0 < e < 1; an inferior good has e < 0.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-9","question":"A 10% rise in the price of coffee raises the quantity of tea demanded by 5%. The cross-price elasticity and the relationship are:","options":["−0.5; complements","+2.0; substitutes","+0.5; substitutes","+0.5; complements"],"answer":2,"explanation":"Cross elasticity = %ΔQ(tea)/%ΔP(coffee) = 5/10 = +0.5. A positive value means the goods are substitutes; complements have negative cross elasticity.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-10","question":"Demand for a product is Q = 1,000/P² (constant elasticity). If price rises from ₹10 to ₹11, by how much does total revenue change?","options":["+10.00%","−10.00%","0.00%","−9.09%"],"answer":3,"explanation":"Constant elasticity −2. TR = P × 1,000/P² = 1,000/P, so TR falls from 100 to 1,000/11 = 90.91, a change of −9.09%. Revenue falls because demand is elastic; it would be unchanged only with unit elasticity.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-11","question":"Demand is Qd = 120 − 2P and supply is Qs = 3P − 30. The government levies a tax of ₹5 per unit on sellers. How much of the tax is borne by consumers per unit?","options":["₹3","₹2","₹5","₹2.50"],"answer":0,"explanation":"Pre-tax: 120 − 2P = 3P − 30 → P = 30, Q = 60. With the tax, sellers receive P − 5: 120 − 2P = 3(P − 5) − 30 → P = 33, Q = 54. Buyers pay ₹3 more and sellers receive ₹28 (₹2 less). The less elastic side (here demand, slope 2 vs 3) bears more.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-12","question":"With demand Qd = 120 − 2P, supply Qs = 3P − 30 and a ₹5 per-unit tax that cuts the traded quantity from 60 to 54, what are the government's tax revenue and the deadweight loss?","options":["Revenue ₹300; deadweight loss ₹15","Revenue ₹270; deadweight loss ₹15","Revenue ₹270; deadweight loss ₹30","Revenue ₹300; deadweight loss ₹0"],"answer":1,"explanation":"Revenue = tax × new quantity = 5 × 54 = ₹270. Deadweight loss = ½ × tax × fall in quantity = ½ × 5 × 6 = ₹15. ₹300 uses the pre-tax quantity; ₹30 forgets the ½.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-13","question":"Demand is Qd = 120 − 2P and supply is Qs = 3P − 30. If the government fixes a maximum price of ₹25, what results?","options":["A surplus of 25 units","A shortage of 10 units","A shortage of 25 units","No effect, because ₹25 is above equilibrium"],"answer":2,"explanation":"Equilibrium is P = 30. At ₹25, Qd = 70 and Qs = 45, so there is excess demand (shortage) of 25. A binding ceiling must be below equilibrium.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-14","question":"Demand is Qd = 200 − 5P and supply is Qs = 5P − 20. A minimum support price of ₹26 is announced. What is the resulting surplus?","options":["40 units","20 units","0 units, because the floor is below equilibrium","110 units"],"answer":0,"explanation":"Equilibrium: 200 − 5P = 5P − 20 → P = 22. At ₹26, Qd = 70 and Qs = 110, a surplus of 40. 110 is quantity supplied, not the surplus.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-15","question":"A Giffen good is one for which:","options":["Demand rises when income rises","Demand is perfectly elastic","Consumers buy more because a high price signals status","Quantity demanded rises when its price rises, because it is strongly inferior and a large part of the budget"],"answer":3,"explanation":"Giffen goods are inferior staples on which poor households spend much of their income; the income effect of a price rise outweighs the substitution effect. Status-driven demand (option four) describes Veblen goods.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-16","question":"Which factors make the demand for a product MORE price elastic? I. Many close substitutes. II. A large share of the consumer's budget. III. The product is habit-forming. IV. A longer time to adjust.","options":["I, II, III and IV","I, II and IV","I and III only","II, III and IV"],"answer":1,"explanation":"Substitutes, budget share and time all increase elasticity. Habit-forming goods (and necessities) have inelastic demand, so III works the other way.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-17","question":"Assertion (A): When demand is much less elastic than supply, most of a per-unit tax is borne by buyers. Reason (R): The side of the market that is less able to change quantity in response to price bears the larger share of a tax.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A: tax incidence falls on the less elastic side. Share borne by buyers = Es/(Es + |Ed|).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-18","question":"When a firm raised its price from ₹50 to ₹55, its revenue rose from ₹10,000 to ₹10,450. What is the arc (midpoint) price elasticity of demand?","options":["−1.00 (unit elastic)","−0.54 (inelastic)","−1.86 (elastic)","+0.45 (Giffen good)"],"answer":1,"explanation":"Quantities: 10,000/50 = 200 and 10,450/55 = 190. %ΔQ = −10/195 = −5.13%; %ΔP = 5/52.5 = 9.52%. Elasticity = −0.54. Revenue rose with price, which already signals inelastic demand.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-19","question":"When the price of cotton yarn rises by 20%, quantity supplied rises by 30%. Supply is:","options":["Inelastic, with elasticity 0.67","Unit elastic","Elastic, with elasticity 0.67","Elastic, with elasticity 1.5"],"answer":3,"explanation":"Price elasticity of supply = 30%/20% = 1.5 > 1, so supply is elastic.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-20","question":"A market has 100 buyers each with demand q = 20 − 2P and 50 buyers each with demand q = 30 − 3P. What is the total quantity demanded at P = ₹4?","options":["1,200","3,500","2,100","30"],"answer":2,"explanation":"Market demand = 100(20 − 2P) + 50(30 − 3P) = 3,500 − 350P. At P = 4: 3,500 − 1,400 = 2,100. Individual demands are added horizontally (quantities at each price). 30 adds one buyer of each type.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-21","question":"A brand's price elasticity is −2 and its advertising elasticity is 0.25. If it cuts price by 5% and raises advertising spend by 20%, by roughly how much will unit sales change?","options":["+10%","+5%","+15%","−5%"],"answer":2,"explanation":"Price effect = −2 × (−5%) = +10%; advertising effect = 0.25 × 20% = +5%. Total ≈ +15%. Taking only one of the two effects gives +10% or +5%.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-22","question":"The income elasticity of demand for coarse grain is −0.3. If incomes rise by 10%, demand for coarse grain will:","options":["Fall by 3%","Rise by 3%","Fall by 30%","Rise by 0.3%"],"answer":0,"explanation":"%ΔQ = income elasticity × %ΔY = −0.3 × 10% = −3%. A negative income elasticity marks an inferior good.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-23","question":"Supply is Qs = 4P − 20. Which statement about its price elasticity is correct?","options":["Elasticity is 4 at every price because the slope is constant","Elasticity is 0.5 at P = 10 and rises with price","Elasticity is 1 at every price because the curve is a straight line","Elasticity is 2 at P = 10 and falls towards 1 as price rises"],"answer":3,"explanation":"Es = (dQ/dP) × P/Q = 4P/(4P − 20). At P = 10: 40/20 = 2. As P rises, the ratio approaches 1. A linear supply curve has constant elasticity of 1 only if it passes through the origin; one that cuts the price axis (as here) is elastic everywhere.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-24","question":"Which statements are correct for a per-unit tax on a good with perfectly inelastic demand? I. Buyers bear the entire tax. II. The quantity traded does not change. III. There is no deadweight loss.","options":["I and II only","I, II and III","I only","II and III only"],"answer":1,"explanation":"With vertical demand, quantity cannot fall, so the price rises by the full tax (I), quantity is unchanged (II) and no trades are lost, so there is no deadweight loss (III).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-25","question":"A retailer's price elasticity of demand is −2. If it cuts prices by 10%, what happens to total revenue?","options":["It rises by about 10%","It falls by about 8%","It rises by about 8%","It rises by about 20%"],"answer":2,"explanation":"Quantity rises 2 × 10% = 20%. Revenue = 0.90 × 1.20 = 1.08 → +8%. Demand is elastic, so a price cut raises revenue. +20% is the quantity change, not revenue.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-26","question":"Demand is Qd = 120 − 2P and supply is Qs = 3P − 30. The government gives producers a subsidy of ₹5 per unit. What does the subsidy cost the government?","options":["₹300","₹330","₹270","₹160"],"answer":1,"explanation":"Sellers receive P + 5: 120 − 2P = 3(P + 5) − 30 → 5P = 135 → P = 27, Q = 66. Cost = 5 × 66 = ₹330. ₹300 uses the pre-subsidy quantity of 60.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-27","question":"The cross-price elasticity between cars and petrol is −0.6. This indicates that the two goods are:","options":["Substitutes","Unrelated goods","Inferior goods","Complements"],"answer":3,"explanation":"Negative cross elasticity: a rise in petrol prices reduces car demand, so they are consumed together (complements).","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-28","question":"Along a straight-line demand curve, which statement is correct?","options":["Demand is elastic above the midpoint and inelastic below it","Elasticity is the same at every point because the slope is constant","Demand is inelastic above the midpoint and elastic below it","Demand is unit-elastic at the price-axis intercept"],"answer":0,"explanation":"Elasticity = slope × P/Q. Near the price intercept P/Q is large (elastic); near the quantity intercept it is small (inelastic); at the midpoint it equals −1.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-29","question":"Why is the demand for petrol typically more price elastic in the long run than in the short run?","options":["Consumers have time to switch vehicles, relocate or use other transport","Petrol becomes a luxury good over time","Producers raise output in the long run","The income effect disappears in the long run"],"answer":0,"explanation":"In the short run people are locked into vehicles and habits; given time they can buy efficient or electric vehicles and change travel patterns, so quantity responds more.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-30","question":"A firm sells 1,000 units at ₹100 with a constant marginal cost of ₹40 and no fixed costs. Its demand has a constant price elasticity of −1.5. If it raises its price by 10%, what happens to profit?","options":["It falls from ₹60,000 to about ₹51,000","It rises from ₹60,000 to about ₹60,675","It falls because revenue falls","It is unchanged because the price rise and the quantity fall cancel out"],"answer":1,"explanation":"New quantity = 1,000 × 1.1^(−1.5) = 866.8. Profit = (110 − 40) × 866.8 = ₹60,675 versus (100 − 40) × 1,000 = ₹60,000. Revenue does fall, but the saving in costs on the lost units outweighs it, so profit rises — the price was below the profit-maximising level (P = MC × e/(e − 1) = ₹120).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-31","question":"A buyer was willing to pay up to ₹500 for a concert ticket but bought it for ₹350. What is her consumer surplus?","options":["₹350","₹500","₹150","₹850"],"answer":2,"explanation":"Consumer surplus = willingness to pay − price paid = 500 − 350 = ₹150.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-32","question":"Market demand is P = 100 − 2Q. If the market price is ₹40, what is total consumer surplus?","options":["₹1,800","₹1,200","₹600","₹900"],"answer":3,"explanation":"At P = 40, Q = 30. Consumer surplus = ½ × 30 × (100 − 40) = ₹900. ₹1,800 forgets the ½; ₹1,200 is total spending.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-33","question":"Market demand is P = 100 − 2Q. If the price falls from ₹40 to ₹30, by how much does consumer surplus increase?","options":["₹300","₹350","₹1,225","₹325"],"answer":3,"explanation":"At ₹40: Q = 30, CS = ½ × 30 × 60 = 900. At ₹30: Q = 35, CS = ½ × 35 × 70 = 1,225. Increase = ₹325 = 10 × 30 (old buyers) + ½ × 10 × 5 (new buyers). ₹300 counts only existing buyers.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-34","question":"Demand is Qd = 120 − 2P and supply is Qs = 3P − 30. At the market equilibrium, what are producer surplus and total surplus?","options":["Producer surplus ₹900; total surplus ₹1,500","Producer surplus ₹600; total surplus ₹1,800","Producer surplus ₹600; total surplus ₹1,500","Producer surplus ₹1,200; total surplus ₹3,000"],"answer":2,"explanation":"Equilibrium P = 30, Q = 60. Demand reaches zero at P = 60 and supply at P = 10. CS = ½ × 60 × (60 − 30) = 900; PS = ½ × 60 × (30 − 10) = 600; total = ₹1,500.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-35","question":"The law of diminishing marginal returns states that, as more units of a variable input are added to a fixed input:","options":["The extra output from each additional unit eventually falls","Total output eventually falls immediately","Average cost falls continuously","Output rises in the same proportion as all inputs"],"answer":0,"explanation":"With at least one input fixed, marginal product eventually declines. Total output can still be rising. Proportional changes in ALL inputs concern returns to scale, a long-run idea.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-36","question":"Total output with 1 to 5 workers on a fixed plot is 10, 24, 36, 44 and 48 units. What are the marginal product of the 4th worker and the average product with 4 workers?","options":["MP = 11; AP = 8","MP = 8; AP = 11","MP = 12; AP = 11","MP = 8; AP = 9.6"],"answer":1,"explanation":"MP of the 4th worker = 44 − 36 = 8. AP with 4 workers = 44/4 = 11. MPs are 10, 14, 12, 8, 4, so diminishing returns set in after the 2nd worker.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-37","question":"A firm's total cost is TC = 500 + 20Q + Q². At Q = 10, what are average total cost and marginal cost?","options":["ATC = ₹80; MC = ₹30","ATC = ₹30; MC = ₹40","ATC = ₹80; MC = ₹40","ATC = ₹62; MC = ₹40"],"answer":2,"explanation":"TC(10) = 500 + 200 + 100 = 800 → ATC = 80. MC = dTC/dQ = 20 + 2Q = 40. AVC would be 20 + Q = 30.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-38","question":"A firm's total cost is TC = 500 + 20Q + 5Q². At what output is average total cost minimised, and what is the minimum ATC?","options":["Q = 10; ATC = ₹120","Q = 2; ATC = ₹280","Q = 10; ATC = ₹70","Q = 50; ATC = ₹280"],"answer":0,"explanation":"ATC = 500/Q + 20 + 5Q. Setting the derivative to zero: −500/Q² + 5 = 0 → Q = 10. ATC = 50 + 20 + 50 = ₹120. Check: MC = 20 + 10Q = 120 = ATC at that point, as it must be.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-39","question":"A firm's fixed costs are ₹5,000. What happens to average fixed cost when output rises from 100 to 200 units?","options":["It stays at ₹5,000","It rises from ₹25 to ₹50","It falls from ₹50 to ₹0","It falls from ₹50 to ₹25"],"answer":3,"explanation":"AFC = FC/Q: 5,000/100 = 50 and 5,000/200 = 25. AFC keeps falling as output rises but never reaches zero.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-40","question":"A shop earns revenue of ₹20 lakh with explicit costs of ₹14 lakh. The owner gave up a ₹4 lakh salary and has ₹10 lakh of her own capital invested that could earn 8% elsewhere. What are accounting profit and economic profit?","options":["Accounting ₹6 lakh; economic ₹2 lakh","Accounting ₹6 lakh; economic ₹1.2 lakh","Accounting ₹1.2 lakh; economic ₹6 lakh","Accounting ₹6 lakh; economic −₹4.8 lakh"],"answer":1,"explanation":"Accounting profit = 20 − 14 = ₹6 lakh. Implicit costs = 4 + 0.08 × 10 = ₹4.8 lakh. Economic profit = 6 − 4.8 = ₹1.2 lakh. ₹2 lakh forgets the return on capital.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-41","question":"A product sells for ₹500 with a variable cost of ₹300 a unit; fixed costs are ₹3 lakh. How many units must be sold to earn a profit of ₹1 lakh?","options":["1,500 units","1,333 units","800 units","2,000 units"],"answer":3,"explanation":"Required units = (fixed cost + target profit)/contribution per unit = (3,00,000 + 1,00,000)/200 = 2,000. The break-even point alone is 1,500 units.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-42","question":"A perfectly competitive firm faces a price of ₹40. Its minimum average variable cost is ₹45 and its minimum average total cost is ₹55. In the short run it should:","options":["Shut down, because price is below minimum AVC","Keep producing, because it covers part of fixed costs","Raise its price to ₹55","Keep producing until fixed costs are recovered"],"answer":0,"explanation":"If P < min AVC, every unit adds more to cost than to revenue, so producing makes losses larger than the fixed cost; it should shut down. A price-taker cannot raise its price.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-43","question":"A competitive firm faces a price of ₹60. At the output where P = MC (1,000 units), its ATC is ₹70 and AVC is ₹50. What should it do in the short run and what is its loss?","options":["Shut down; loss ₹10,000","Continue producing; profit ₹10,000","Continue producing; loss ₹10,000 (versus ₹20,000 if it shut down)","Shut down; loss ₹20,000 is smaller"],"answer":2,"explanation":"Loss if it produces = (70 − 60) × 1,000 = ₹10,000. Fixed cost = (70 − 50) × 1,000 = ₹20,000, which it would lose anyway by shutting down. As P > AVC, producing covers all variable costs and ₹10,000 of fixed costs.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-44","question":"A firm's production function is Q = 4L^0.6 K^0.5. If it doubles both labour and capital, output will:","options":["Exactly double (constant returns to scale)","More than double (increasing returns to scale)","Less than double (decreasing returns to scale)","Rise by a factor of 4"],"answer":1,"explanation":"Doubling inputs multiplies output by 2^(0.6 + 0.5) = 2^1.1 ≈ 2.14. Since the exponents sum to more than 1, returns to scale are increasing. The constant 4 does not affect returns to scale.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-45","question":"A firm's production function is Q = L^0.5 K^0.5. The wage is ₹16 and the rental rate of capital is ₹4. What is the minimum cost of producing 100 units?","options":["₹2,000","₹1,000","₹1,600","₹3,200"],"answer":2,"explanation":"Cost minimisation: MPL/MPK = K/L = w/r = 4 → K = 4L. Then Q = √(L × 4L) = 2L = 100 → L = 50, K = 200. Cost = 16 × 50 + 4 × 200 = 800 + 800 = ₹1,600. Using equal inputs (L = K = 100) costs ₹2,000.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-46","question":"A graduate's best job offer pays ₹10 lakh a year. Instead she joins a 2-year MBA with total fees of ₹20 lakh (ignore discounting and living costs). What is the economic cost of the MBA?","options":["₹20 lakh","₹40 lakh","₹30 lakh","₹10 lakh"],"answer":1,"explanation":"Economic cost = explicit fees + forgone earnings = 20 + 2 × 10 = ₹40 lakh. ₹20 lakh ignores the opportunity cost of time.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-47","question":"A studio has already spent ₹50 crore on a film. Finishing it will cost another ₹20 crore, and it is now expected to earn ₹30 crore in total. What should the studio do?","options":["Abandon it, because total cost (₹70 crore) exceeds revenue (₹30 crore)","Abandon it, because it will lose ₹40 crore","Finish it only if revenue exceeds ₹70 crore","Finish it, because the extra ₹30 crore of revenue exceeds the extra ₹20 crore of cost"],"answer":3,"explanation":"The ₹50 crore is sunk and cannot be recovered either way. Going forward, finishing adds ₹30 crore of revenue for ₹20 crore of cost, a ₹10 crore gain, so finishing reduces the overall loss from ₹50 crore to ₹40 crore.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-48","question":"A bank finds that selling insurance and mutual funds through its existing branches costs less than having separate firms provide each service. This is an example of:","options":["Economies of scope","Economies of scale","Diminishing returns","Diseconomies of scale"],"answer":0,"explanation":"Economies of scope arise when producing several products together is cheaper than producing them separately, usually by sharing inputs such as branches or customer data. Economies of scale concern larger output of the same product.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-49","question":"Assembly follows an 80% learning curve: each time cumulative output doubles, the time for the last unit of the doubled batch falls to 80% of the earlier figure. If the 1st unit takes 100 hours, how long does the 8th unit take?","options":["40.0 hours","64.0 hours","60.0 hours","51.2 hours"],"answer":3,"explanation":"Unit 2 = 80 hours, unit 4 = 64 hours, unit 8 = 51.2 hours (100 × 0.8³). 40 hours subtracts 20% per doubling linearly from the first unit (100 − 3 × 20).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-50","question":"A firm maximises profit at the output where:","options":["Average cost is at its minimum","Marginal revenue equals marginal cost, with MC rising","Total revenue is at its maximum","Price equals average variable cost"],"answer":1,"explanation":"Producing one more unit is worthwhile while MR > MC; profit peaks where MR = MC with MC cutting MR from below. Minimum average cost or maximum revenue are not, in general, the profit-maximising points.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-51","question":"A product's price is ₹250 and its variable cost ₹150 a unit; fixed costs are ₹8 lakh. What are the contribution margin ratio and the break-even sales value?","options":["40%; ₹20 lakh","60%; ₹13.33 lakh","40%; ₹8,000","40%; ₹32 lakh"],"answer":0,"explanation":"CM ratio = (250 − 150)/250 = 40%. Break-even sales = fixed costs/CM ratio = 8 lakh/0.40 = ₹20 lakh (8,000 units × ₹250). ₹8,000 is the break-even volume in units, not value.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-52","question":"Technology A has fixed costs of ₹10 lakh and variable cost ₹60 a unit; technology B has fixed costs of ₹4 lakh and variable cost ₹90 a unit. Which statement is correct?","options":["Total costs are equal at 20,000 units; above that B is cheaper","Total costs are equal at 4,667 units; above that A is cheaper","Total costs are equal at 20,000 units; above that A is cheaper","B is cheaper at every volume because its fixed cost is lower"],"answer":2,"explanation":"10,00,000 + 60Q = 4,00,000 + 90Q → 30Q = 6,00,000 → Q = 20,000. Beyond this volume A's lower variable cost outweighs its higher fixed cost, so the capital-intensive option suits high volumes.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-53","question":"In a competitive industry each firm's long-run total cost is TC = 100 + q². Market demand is Q = 1,000 − 10P. In long-run equilibrium, how many firms will operate?","options":["100","80","60","50"],"answer":1,"explanation":"Long-run price = minimum ATC. ATC = 100/q + q is minimised at q = 10, where ATC = 20. At P = 20, Q = 1,000 − 200 = 800. Number of firms = 800/10 = 80.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-54","question":"When a firm earns 'normal profit', its economic profit is:","options":["Zero","Positive and equal to accounting profit","Negative","Equal to total revenue"],"answer":0,"explanation":"Normal profit is the minimum return needed to keep resources in their current use; it is counted as an implicit cost, so economic profit is zero.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-55","question":"At a firm's current input mix, the marginal product of labour is 20 and that of capital is 40; both a worker and a unit of capital cost ₹10. To minimise the cost of its current output, the firm should:","options":["Use more labour and less capital","Keep the same mix, because the prices are equal","Use more of both","Use more capital and less labour"],"answer":3,"explanation":"Output per rupee: labour 20/10 = 2, capital 40/10 = 4. Shifting spending from labour to capital raises output for the same cost until MPL/w = MPK/r.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-56","question":"Demand is Qd = 120 − 2P and supply is Qs = 3P − 30. A ₹5 per-unit tax raises the buyers' price from ₹30 to ₹33 and cuts quantity from 60 to 54. By how much does consumer surplus fall?","options":["₹180","₹162","₹171","₹729"],"answer":2,"explanation":"Demand reaches zero at P = 60. CS before = ½ × 60 × 30 = 900; after = ½ × 54 × 27 = 729. Fall = ₹171 = 3 × 54 (higher price on units still bought) + ½ × 3 × 6 (lost units). ₹162 omits the triangle; ₹729 is the new CS.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-57","question":"In the law of variable proportions, a rational producer operates in the stage where:","options":["Average product is rising","Marginal product is negative","Average product is falling but marginal product is still positive","Total product is falling"],"answer":2,"explanation":"Stage I (rising AP) means the fixed input is under-used; Stage III (negative MP) means too much variable input. Stage II, with falling AP and positive MP, is the rational zone.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-58","question":"Which statements about short-run cost curves are correct? I. MC cuts ATC at the minimum point of ATC. II. AFC rises at high output levels. III. The vertical gap between ATC and AVC narrows as output rises.","options":["I and III only","I, II and III","I and II only","II and III only"],"answer":0,"explanation":"MC passes through the minimum of both AVC and ATC (I). AFC always falls as output rises (II is false). The ATC–AVC gap equals AFC, so it narrows (III).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-59","question":"A firm makes 2,000 components a year at a variable cost of ₹60 each, plus a fixed-overhead allocation of ₹25 each that would remain if production stopped. A supplier offers them at ₹75 each. If the freed capacity could earn ₹40,000 of contribution elsewhere, what should the firm do?","options":["Make: full cost of buying (₹1,50,000) exceeds the variable cost of making (₹1,20,000)","Buy: full cost of making (₹85 each) exceeds ₹75","Make: relevant cost of making is ₹1,20,000 versus ₹1,50,000 to buy","Buy: relevant cost of making is ₹1,60,000 versus ₹1,50,000 to buy"],"answer":3,"explanation":"Unavoidable overhead is irrelevant. Relevant cost of making = 2,000 × 60 + 40,000 opportunity cost = ₹1,60,000; buying costs 2,000 × 75 = ₹1,50,000. Buying saves ₹10,000. The 'full cost' reasoning reaches the right answer for the wrong reason.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-60","question":"If a firm's marginal cost is below its average total cost at the current output, then as output rises slightly:","options":["Average total cost rises","Average total cost falls","Average total cost stays constant","Marginal cost must also fall"],"answer":1,"explanation":"When the marginal unit costs less than the average, it pulls the average down. MC itself may be rising while still below ATC.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-61","question":"Which feature is characteristic of perfect competition?","options":["Each firm faces a downward-sloping demand curve","Firms are price takers selling an identical product","Entry is blocked by patents","A few firms react to each other's prices"],"answer":1,"explanation":"Under perfect competition many small firms sell a homogeneous product with free entry, so each firm takes the market price as given and faces a horizontal demand curve.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-62","question":"A monopolist faces demand P = 100 − 2Q and has a constant marginal cost of ₹20 (no fixed cost). What are its profit-maximising output and price?","options":["Q = 40, P = ₹20","Q = 25, P = ₹50","Q = 20, P = ₹40","Q = 20, P = ₹60"],"answer":3,"explanation":"MR = 100 − 4Q (twice the slope of demand). MR = MC → 100 − 4Q = 20 → Q = 20; P = 100 − 40 = ₹60. Q = 40, P = 20 is the competitive outcome (P = MC).","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-63","question":"A monopolist faces demand P = 100 − 2Q with constant MC = ₹20 and charges ₹60 for 20 units. What deadweight loss does it create compared with perfect competition?","options":["₹400","₹800","₹200","₹1,600"],"answer":0,"explanation":"Competitive output: 100 − 2Q = 20 → Q = 40. DWL = ½ × (40 − 20) × (60 − 20) = ₹400. ₹800 forgets the ½ (and equals monopoly profit).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-64","question":"A firm with market power has a marginal cost of ₹60 and faces a price elasticity of demand of −4 at its chosen output. What profit-maximising price does the markup rule imply?","options":["₹75","₹240","₹80","₹64"],"answer":2,"explanation":"P = MC/(1 − 1/|e|) = 60/(1 − 0.25) = 60/0.75 = ₹80. ₹75 adds 25% to MC instead of dividing by 0.75.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-65","question":"A firm sells at ₹80 with a marginal cost of ₹60. If it is maximising profit, what is its Lerner index, and what elasticity of demand does that imply?","options":["0.25; elasticity −4","0.33; elasticity −3","0.25; elasticity −0.25","0.75; elasticity −1.33"],"answer":0,"explanation":"Lerner index = (P − MC)/P = 20/80 = 0.25. At the profit maximum it equals 1/|e|, so |e| = 4. 0.33 divides the markup by MC instead of price.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-66","question":"A monopolist with constant MC = ₹20 sells in two separate markets: A with demand P = 100 − Q and B with demand P = 60 − Q. If it price-discriminates, what prices does it charge?","options":["₹50 in both markets","₹60 in A and ₹40 in B","₹40 in A and ₹60 in B","₹60 in A and ₹20 in B"],"answer":1,"explanation":"Set MR = MC in each market. A: 100 − 2Q = 20 → Q = 40, P = 60. B: 60 − 2Q = 20 → Q = 20, P = 40. The higher price goes to the market with less elastic demand at the optimum.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-67","question":"The same monopolist (MC = ₹20; market A: P = 100 − Q; market B: P = 60 − Q) is banned from discriminating and must charge one price. How much profit does the ban cost it?","options":["₹400 (profit falls from ₹2,000 to ₹1,600)","Nothing; uniform pricing gives the same ₹2,000","₹200 (profit falls from ₹1,800 to ₹1,600)","₹200 (profit falls from ₹2,000 to ₹1,800)"],"answer":3,"explanation":"Discrimination profit = 40 × 40 + 20 × 20 = ₹2,000. Uniform price: combined demand Q = 160 − 2P (for P ≤ 60) → P = 80 − Q/2, MR = 80 − Q = 20 → Q = 60, P = ₹50 (A buys 50, B buys 10). Profit = 30 × 60 = ₹1,800. Loss = ₹200.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-68","question":"Two identical firms compete by choosing quantities (Cournot). Market demand is P = 120 − Q and each has a constant MC of ₹30. What is the equilibrium market price?","options":["₹75","₹30","₹60","₹52.50"],"answer":2,"explanation":"Firm 1's best response: q₁ = (90 − q₂)/2. With symmetry q = (120 − 30)/3 = 30 each, so Q = 60 and P = ₹60. A monopoly would charge ₹75; Bertrand competition would drive price to ₹30; ₹52.50 is the Stackelberg price.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-69","question":"With market demand P = 120 − Q and MC = ₹30 for both firms, firm 1 chooses its quantity first and firm 2 then responds (Stackelberg). What are the outputs of the leader and the follower?","options":["Leader 30, follower 30","Leader 45, follower 45","Leader 22.5, follower 45","Leader 45, follower 22.5"],"answer":3,"explanation":"Follower's best response: q₂ = (90 − q₁)/2. Leader maximises (120 − q₁ − q₂ − 30)q₁ = (45 − q₁/2)q₁ → q₁ = 45, so q₂ = 22.5 and P = 120 − 67.5 = ₹52.50. The leader produces more than under Cournot (30).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-70","question":"The kinked demand curve model of oligopoly is used to explain:","options":["Why oligopolists always form cartels","Why prices tend to stay rigid even when costs change","Why oligopoly prices equal marginal cost","Why entry is free in oligopoly"],"answer":1,"explanation":"Rivals match price cuts but not price rises, so demand is elastic above the current price and inelastic below it. MR has a gap at the kink, so moderate cost changes leave the profit-maximising price unchanged.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-71","question":"Assertion (A): Cartels tend to be unstable. Reason (R): Each member can raise its own profit by secretly producing more than its quota at the cartel price.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. The incentive to cheat is the prisoner's dilemma inside every cartel; detection and punishment problems make it break down.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-72","question":"Four firms in an industry have market shares of 40%, 30%, 20% and 10%. What is the Herfindahl–Hirschman Index?","options":["100","2,500","3,000","1,000"],"answer":2,"explanation":"HHI = 40² + 30² + 20² + 10² = 1,600 + 900 + 400 + 100 = 3,000. 100 just adds the shares.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-73","question":"In an industry with shares of 40%, 30%, 20% and 10%, the two smallest firms merge (and keep their combined share). By how much does the HHI rise?","options":["400 points, from 3,000 to 3,400","300 points, from 3,000 to 3,300","200 points, from 3,000 to 3,200","500 points, from 3,000 to 3,500"],"answer":0,"explanation":"New shares: 40, 30, 30 → HHI = 1,600 + 900 + 900 = 3,400. The increase always equals 2 × s₁ × s₂ = 2 × 20 × 10 = 400.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-74","question":"Restaurants in a city — many sellers, each offering a slightly different menu, with easy entry — best illustrate:","options":["Perfect competition","Oligopoly","Monopolistic competition","Monopoly"],"answer":2,"explanation":"Many firms, differentiated products and free entry are the defining features of monopolistic competition.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-75","question":"In long-run equilibrium under monopolistic competition, which statement is correct?","options":["Firms earn positive economic profit protected by entry barriers","Firms earn zero economic profit and price exceeds marginal cost, leaving excess capacity","Price equals marginal cost and minimum average cost","Firms produce at the minimum of their long-run average cost"],"answer":1,"explanation":"Entry pushes each firm's demand curve until it is tangent to ATC: P = ATC (zero profit) but on the falling part of ATC, so P > MC and output is below the minimum-cost scale.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-76","question":"Two firms each choose a High or Low price. Payoffs (firm A, firm B) in ₹ crore: both High (50, 50); A High, B Low (10, 70); A Low, B High (70, 10); both Low (30, 30). What is the Nash equilibrium?","options":["Both choose High, earning ₹50 crore each","A High and B Low","There is no Nash equilibrium","Both choose Low, earning ₹30 crore each"],"answer":3,"explanation":"Low is dominant for each firm: if the rival is High, Low gives 70 > 50; if the rival is Low, Low gives 30 > 10. So both choose Low — a prisoner's dilemma, since both would prefer (50, 50).","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-77","question":"Firms A and B decide whether to advertise. Payoffs (A, B): both advertise (40, 30); only A advertises (60, 20); only B advertises (30, 40); neither (50, 35). Which statement is correct?","options":["Both advertise, although both would earn more if neither did","Neither advertises, because (50, 35) is better for both","Only A advertises, because A gets its highest payoff","There are two Nash equilibria: both advertise and neither advertises"],"answer":0,"explanation":"A: advertising gives 40 > 30 (if B advertises) and 60 > 50 (if B does not) — dominant. B: 30 > 20 and 40 > 35 — dominant. Equilibrium (40, 30), yet (50, 35) would be better for both: a prisoner's dilemma.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-78","question":"Two firms choose a technology standard. Payoffs (A, B): both X (60, 40); both Y (40, 60); A X and B Y (0, 0); A Y and B X (0, 0). How many pure-strategy Nash equilibria are there?","options":["One: both X","One: both Y","Two: both X and both Y","None"],"answer":2,"explanation":"At (X, X) neither gains by switching (0 < 60, 0 < 40); the same holds at (Y, Y). Mismatched choices give zero, so each firm wants to switch. This coordination game has two equilibria, each favouring a different firm.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-79","question":"Player A chooses Up or Down; player B chooses Left, Middle or Right. Payoffs (A, B): Up–Left (4, 3), Up–Middle (5, 1), Up–Right (6, 2), Down–Left (2, 1), Down–Middle (8, 4), Down–Right (3, 6). What is the outcome after iterated elimination of strictly dominated strategies?","options":["Down–Middle, with payoffs (8, 4)","Down–Right, with payoffs (3, 6)","Up–Right, with payoffs (6, 2)","Up–Left, with payoffs (4, 3)"],"answer":3,"explanation":"For B, Right beats Middle in both rows (2 > 1, 6 > 4), so delete Middle. Then for A, Up beats Down against Left (4 > 2) and Right (6 > 3), so delete Down. Facing Up, B prefers Left (3 > 2). The unique equilibrium is Up–Left. Down–Middle has the largest total payoff but is not stable.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-80","question":"A potential entrant decides whether to Enter. If it stays out, payoffs are (entrant 0, incumbent 100). If it enters, the incumbent chooses Fight (−10, 20) or Accommodate (30, 50). Using backward induction, what happens?","options":["The entrant stays out because it fears a fight","The entrant enters and the incumbent accommodates","The entrant enters and the incumbent fights","The entrant stays out and the incumbent earns 100"],"answer":1,"explanation":"Once entry has happened, the incumbent prefers Accommodate (50 > 20), so a threat to fight is not credible. Anticipating this, the entrant compares 30 with 0 and enters.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-81","question":"In an infinitely repeated pricing game, each period's payoffs are: both cooperate 50 each, both cheat 30 each, and a lone cheater gets 70 (the other 10). With grim-trigger strategies, what is the minimum discount factor that sustains cooperation?","options":["0.40","0.50","0.67","0.29"],"answer":1,"explanation":"Cooperation is stable if 50/(1 − δ) ≥ 70 + 30δ/(1 − δ) → 50 ≥ 70(1 − δ) + 30δ → δ ≥ (70 − 50)/(70 − 30) = 0.5. Players must value the future at least half as much as today.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-82","question":"Which conditions are needed for a firm to practise third-degree price discrimination profitably? I. It has some market power. II. It can separate buyers into groups. III. The groups have different price elasticities. IV. Buyers cannot resell easily.","options":["I, II, III and IV","I, II and III only","II, III and IV only","I and IV only"],"answer":0,"explanation":"All four are needed: a price-taker cannot discriminate, groups must be identifiable, differing elasticities make different prices profitable, and resale would undo the price differences.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-83","question":"In long-run equilibrium in a perfectly competitive industry, which set of conditions holds?","options":["P = MC > minimum ATC, with positive economic profit","P > MC = minimum ATC","P = MC = minimum ATC, with zero economic profit","P = AVC, with firms just covering variable costs"],"answer":2,"explanation":"Free entry and exit eliminate economic profit, so price falls to minimum ATC, where MC = ATC. Firms produce at efficient scale and allocative efficiency (P = MC) holds.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-84","question":"A water utility's long-run average cost falls over the whole range of market demand. If a regulator forces it to price at marginal cost, what happens?","options":["It earns a normal profit","It earns supernormal profit","Output falls below the monopoly level","It makes a loss, because MC lies below average cost when AC is falling"],"answer":3,"explanation":"With falling AC, MC < AC, so P = MC does not cover average cost. This is the natural-monopoly pricing dilemma: regulators often use average-cost pricing or subsidies instead.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-85","question":"A gym has identical members, each with demand for visits q = 10 − P, and a marginal cost of ₹2 per visit. With a two-part tariff (membership fee plus per-visit price), what fee maximises profit?","options":["₹50 per member, with a per-visit price of ₹0","₹32 per member, with a per-visit price of ₹2","₹18 per member, with a per-visit price of ₹4","₹32 per member, with a per-visit price of ₹6"],"answer":1,"explanation":"Set the per-visit price at MC = ₹2, so each member makes 8 visits; then capture all consumer surplus with the fee: ½ × 8 × (10 − 2) = ₹32. Profit per member = ₹32. A ₹4 price with an ₹18 fee yields only 18 + 2 × 6 = ₹30.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-86","question":"Two firms sell identical products with the same constant marginal cost of ₹30 and compete by setting prices simultaneously (Bertrand). What is the equilibrium price?","options":["The monopoly price","Halfway between ₹30 and the monopoly price","Any price above ₹30","₹30"],"answer":3,"explanation":"Each firm can capture the whole market by undercutting slightly, so any price above MC is undercut. The only equilibrium is P = MC = ₹30 — the Bertrand paradox: two firms are enough for the competitive outcome.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-87","question":"A firm launching an innovative gadget sets a high initial price for early adopters and cuts it over time. This strategy is called:","options":["Penetration pricing","Predatory pricing","Price skimming","Cost-plus pricing"],"answer":2,"explanation":"Skimming captures surplus from buyers with high willingness to pay before targeting more price-sensitive segments. Penetration pricing starts low to build share quickly.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-88","question":"A software firm has two customers. A values Writer at ₹120 and Sheets at ₹100; B values Writer at ₹100 and Sheets at ₹150. Marginal cost is zero. How much more revenue does pure bundling earn than the best separate prices?","options":["₹40 (₹440 versus ₹400)","₹70 (₹470 versus ₹400)","₹0 (both give ₹400)","₹20 (₹440 versus ₹420)"],"answer":0,"explanation":"Separate: Writer at ₹100 sells to both (₹200 > ₹120); Sheets at ₹100 sells to both (₹200 > ₹150): total ₹400. Bundle: A values it at ₹220, B at ₹250, so a ₹220 bundle sells to both: ₹440. Bundling works because the valuations are negatively correlated. ₹470 is total willingness to pay.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-89","question":"A monopolist with demand P = 100 − 2Q and constant MC = ₹20 must pay a new tax of ₹10 per unit. By how much does its price rise?","options":["₹10 (from ₹60 to ₹70)","₹2.50 (from ₹60 to ₹62.50)","₹5 (from ₹60 to ₹65)","₹0, because a monopolist absorbs the tax"],"answer":2,"explanation":"New MC = 30: 100 − 4Q = 30 → Q = 17.5, P = 100 − 35 = ₹65. With linear demand and constant MC, a monopolist passes on half of a per-unit tax.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-90","question":"Which feature most distinguishes oligopoly from other market structures?","options":["Strategic interdependence: each firm's best decision depends on rivals' reactions","Many sellers of a homogeneous product","A single seller with no close substitutes","Zero economic profit in the long run"],"answer":0,"explanation":"With a few large firms, each must anticipate rivals' responses to its price, output or advertising — the reason game theory is used to study oligopoly.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-91","question":"Under the expenditure method, GDP equals:","options":["C + S + T","C + I + G + (X − M)","C + I + G + X + M","Wages + rent + interest + profit − depreciation"],"answer":1,"explanation":"GDP = consumption + investment + government purchases + net exports. Imports are subtracted because they are produced abroad.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-92","question":"An economy has consumption ₹600 crore, investment ₹200 crore, government purchases ₹150 crore, exports ₹100 crore and imports ₹120 crore. What is GDP?","options":["₹1,170 crore","₹950 crore","₹1,050 crore","₹930 crore"],"answer":3,"explanation":"GDP = 600 + 200 + 150 + (100 − 120) = ₹930 crore. ₹1,170 crore adds imports instead of subtracting them.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-93","question":"GDP at market prices is ₹930 crore, net factor income from abroad is −₹20 crore, depreciation ₹60 crore, indirect taxes ₹90 crore and subsidies ₹30 crore. What is national income (NNP at factor cost)?","options":["₹850 crore","₹830 crore","₹910 crore","₹790 crore"],"answer":3,"explanation":"GNP_MP = 930 − 20 = 910; NNP_MP = 910 − 60 = 850; NNP_FC = 850 − 90 + 30 = ₹790 crore. ₹850 crore stops at market prices; ₹830 crore adds NFIA instead of subtracting it.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-94","question":"A farmer sells wheat worth ₹100 to a miller, the miller sells flour worth ₹160 to a baker, and the baker sells bread worth ₹250 to consumers. How much do these transactions add to GDP?","options":["₹510","₹250","₹160","₹90"],"answer":1,"explanation":"Only the final good counts (₹250); equivalently, the values added are 100 + 60 + 90 = 250. Adding all sales (₹510) double-counts intermediate goods. ₹90 is the baker's value added alone.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-95","question":"Which of these is NOT included in GDP?","options":["Old-age pension paid by the government","Salary paid to a government teacher","A new factory built by a company","Services exported by an IT firm"],"answer":0,"explanation":"Pensions are transfer payments: no current good or service is produced in return. Government salaries, new investment and exports are all part of GDP.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-96","question":"Nominal GDP this year is ₹220 lakh crore and the GDP deflator is 110 (base year = 100). Real GDP last year was ₹190 lakh crore. What was real GDP growth this year?","options":["15.79%","10.00%","5.26%","5.79%"],"answer":2,"explanation":"Real GDP = 220/1.10 = ₹200 lakh crore. Growth = 200/190 − 1 = 5.26%. 15.79% compares nominal with real values, and 5.79% subtracts the 10% price rise from that, a rough approximation on the wrong base.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-97","question":"Nominal GDP is ₹1,200 crore and real GDP (at base-year prices) is ₹1,000 crore. What is the GDP deflator?","options":["83.3","20","120","220"],"answer":2,"explanation":"GDP deflator = nominal/real × 100 = 1,200/1,000 × 100 = 120, meaning the price level is 20% above the base year.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-98","question":"In a simple closed economy without taxes, the marginal propensity to consume is 0.8. By how much does income rise if investment increases by ₹100 crore?","options":["₹80 crore","₹125 crore","₹180 crore","₹500 crore"],"answer":3,"explanation":"Multiplier = 1/(1 − MPC) = 1/0.2 = 5, so ΔY = 5 × 100 = ₹500 crore. ₹125 crore uses 1/MPC.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-99","question":"The MPC out of disposable income is 0.8 and the proportional income tax rate is 25%. In a closed economy, by how much does income rise when investment increases by ₹40 crore?","options":["₹100 crore","₹200 crore","₹160 crore","₹53.3 crore"],"answer":0,"explanation":"Multiplier = 1/[1 − MPC(1 − t)] = 1/(1 − 0.8 × 0.75) = 1/0.4 = 2.5 → ΔY = 2.5 × 40 = ₹100 crore. ₹200 crore ignores the tax leakage.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-100","question":"The MPC out of disposable income is 0.8, the tax rate is 25% and the marginal propensity to import is 0.1. By how much does income rise if government spending increases by ₹50 crore?","options":["₹125 crore","₹100 crore","₹250 crore","₹83.3 crore"],"answer":1,"explanation":"Multiplier = 1/[1 − MPC(1 − t) + MPM] = 1/(1 − 0.6 + 0.1) = 1/0.5 = 2. ΔY = 2 × 50 = ₹100 crore. ₹125 crore ignores imports; ₹250 crore ignores both taxes and imports.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-101","question":"With an MPC of 0.8 and lump-sum taxes, by how much does equilibrium income change if the government cuts taxes by ₹25 crore?","options":["Rises by ₹100 crore","Rises by ₹125 crore","Rises by ₹20 crore","Falls by ₹100 crore"],"answer":0,"explanation":"Tax multiplier = −MPC/(1 − MPC) = −0.8/0.2 = −4. A tax cut of 25 raises income by 4 × 25 = ₹100 crore. It is smaller than the spending multiplier (5) because part of the tax cut is saved.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-102","question":"Assertion (A): If the government raises spending and lump-sum taxes by the same ₹100 crore, equilibrium income rises by ₹100 crore. Reason (R): The tax multiplier is smaller in absolute value than the spending multiplier by exactly 1.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Spending multiplier 1/(1 − c) minus tax multiplier c/(1 − c) equals 1, so the balanced-budget multiplier is 1 and income rises by exactly ₹100 crore. R gives the reason, so it explains A.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-103","question":"In a closed economy, C = 100 + 0.75(Y − T), lump-sum taxes T = 40, investment I = 150 and government spending G = 100 (₹ crore). What is equilibrium income?","options":["₹1,400 crore","₹1,360 crore","₹1,280 crore","₹1,240 crore"],"answer":2,"explanation":"Y = 100 + 0.75(Y − 40) + 150 + 100 → Y − 0.75Y = 350 − 30 → 0.25Y = 320 → Y = ₹1,280 crore. Ignoring taxes gives ₹1,400 crore.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-104","question":"Equilibrium income is ₹1,280 crore but full-employment income is ₹1,500 crore. With an MPC of 0.75 and lump-sum taxes, by how much must government spending rise to close the gap?","options":["₹220 crore","₹55 crore","₹73.3 crore","₹165 crore"],"answer":1,"explanation":"Spending multiplier = 1/(1 − 0.75) = 4. Required ΔG = 220/4 = ₹55 crore. A tax cut would need to be larger: 220/3 = ₹73.3 crore.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-105","question":"Assertion (A): If all households try to save more during a recession, total saving in the economy may not rise. Reason (R): Lower consumption reduces income through the multiplier, and saving depends on income.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"This is the paradox of thrift. Higher planned saving cuts demand and income, so actual saving may not rise (it can even fall if investment responds to income). R explains A.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-106","question":"If the marginal propensity to save is 0.25, what are the MPC and the simple investment multiplier?","options":["MPC 0.25; multiplier 4","MPC 0.75; multiplier 1.33","MPC 0.75; multiplier 0.25","MPC 0.75; multiplier 4"],"answer":3,"explanation":"MPC + MPS = 1, so MPC = 0.75. Multiplier = 1/MPS = 4. 1.33 is 1/MPC.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-107","question":"A consumption function is C = 200 + 0.6Y. At income Y = 1,000, what are the average and marginal propensities to consume?","options":["APC 0.6; MPC 0.8","APC 0.6; MPC 0.6","APC 0.8; MPC 0.6","APC 0.8; MPC 0.8"],"answer":2,"explanation":"C = 200 + 600 = 800, so APC = 800/1,000 = 0.8. MPC = slope = 0.6. With positive autonomous consumption, APC exceeds MPC.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-108","question":"Firms keep a capital–output ratio of 3. If annual output rises from ₹400 crore to ₹450 crore, how much net investment does the accelerator principle predict?","options":["₹50 crore","₹1,350 crore","₹16.7 crore","₹150 crore"],"answer":3,"explanation":"Net investment = capital–output ratio × change in output = 3 × 50 = ₹150 crore. ₹1,350 crore is the total capital needed for the new output, not the addition.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-109","question":"Real GDP grows by 7% and population by 1.5% in a year. By how much does real GDP per capita grow?","options":["5.50%","5.42%","8.50%","8.60%"],"answer":1,"explanation":"(1 + per-capita growth) = 1.07/1.015 → growth = 5.42%. 5.50% is the quick approximation (7 − 1.5).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-110","question":"Nominal GDP rises from ₹500 crore to ₹572 crore while the GDP deflator rises from 100 to 104. What is real GDP growth?","options":["14.40%","10.40%","4.00%","10.00%"],"answer":3,"explanation":"Real GDP in year 2 = 572/1.04 = ₹550 crore. Growth = 550/500 − 1 = 10%. 14.4% is nominal growth; 10.4% subtracts inflation from nominal growth, an approximation.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-111","question":"An economy has compensation of employees ₹500 crore, operating surplus ₹300 crore, mixed income of the self-employed ₹100 crore, depreciation ₹50 crore and net indirect taxes ₹70 crore (net factor income from abroad is zero). What is GDP at market prices?","options":["₹900 crore","₹970 crore","₹1,020 crore","₹950 crore"],"answer":2,"explanation":"Income method: NDP at factor cost = 500 + 300 + 100 = 900. GDP_MP = NDP_FC + depreciation + net indirect taxes = 900 + 50 + 70 = ₹1,020 crore. ₹900 crore is domestic income; ₹970 crore omits depreciation.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-112","question":"Which transaction is counted in this year's GDP?","options":["The sale of a second-hand car","A new house built and sold this year","The purchase of shares in a listed company","A gift of money from a relative abroad"],"answer":1,"explanation":"A newly built house is investment in current output. Second-hand sales were counted when first produced; shares are financial transfers; gifts are transfers.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-113","question":"In an open economy at equilibrium, planned saving is ₹120 crore, taxes ₹100 crore, imports ₹80 crore, investment ₹110 crore and government spending ₹120 crore. What must exports be?","options":["₹90 crore","₹300 crore","₹70 crore","₹50 crore"],"answer":2,"explanation":"At equilibrium, leakages equal injections: S + T + M = I + G + X → 120 + 100 + 80 = 110 + 120 + X → X = ₹70 crore.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-114","question":"A government's revenue receipts are ₹20 lakh crore, non-debt capital receipts ₹1 lakh crore, revenue expenditure ₹25 lakh crore, capital expenditure ₹5 lakh crore and interest payments ₹8 lakh crore. What are the primary deficit and the revenue deficit?","options":["Primary deficit ₹9 lakh crore; revenue deficit ₹5 lakh crore","Primary deficit ₹1 lakh crore; revenue deficit ₹10 lakh crore","Primary deficit ₹2 lakh crore; revenue deficit ₹4 lakh crore","Primary deficit ₹1 lakh crore; revenue deficit ₹5 lakh crore"],"answer":3,"explanation":"Fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts) = 30 − 21 = 9. Primary deficit = 9 − 8 = ₹1 lakh crore. Revenue deficit = 25 − 20 = ₹5 lakh crore. ₹9 lakh crore is the fiscal deficit.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-115","question":"When higher government borrowing pushes up interest rates and reduces private investment, the effect is called:","options":["Crowding out","The accelerator effect","The paradox of thrift","Demand-pull inflation"],"answer":0,"explanation":"Government competes with private borrowers for loanable funds; higher rates crowd out interest-sensitive private investment, reducing the net effect of fiscal expansion.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-116","question":"Reserve money (high-powered money) is ₹100 lakh crore. Banks hold reserves equal to 10% of deposits and the public holds currency equal to 20% of deposits. What is broad money supply in this simple model?","options":["₹1,000 lakh crore","₹400 lakh crore","₹333 lakh crore","₹600 lakh crore"],"answer":1,"explanation":"Money multiplier = (1 + c)/(c + r) = 1.2/0.3 = 4. Money supply = 4 × 100 = ₹400 lakh crore. ₹1,000 lakh crore ignores currency drain (1/r).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-117","question":"Which index measures changes in the prices of a basket of goods and services bought by households?","options":["Index of Industrial Production","Wholesale Price Index","Consumer Price Index","Sensex"],"answer":2,"explanation":"The CPI tracks retail prices paid by consumers. The WPI tracks wholesale prices of goods; the IIP measures industrial output; the Sensex is a share price index.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-118","question":"GDP at market prices is ₹1,000 crore, indirect taxes are ₹120 crore and subsidies ₹20 crore. What is GDP at factor cost?","options":["₹900 crore","₹860 crore","₹1,100 crore","₹880 crore"],"answer":0,"explanation":"GDP_FC = GDP_MP − indirect taxes + subsidies = 1,000 − 120 + 20 = ₹900 crore. ₹860 crore subtracts subsidies too.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-119","question":"The MPC is 0.6. The government spends an extra ₹100 crore. How much has total income risen after the first three rounds of spending, and what is the eventual total increase?","options":["₹160 crore after three rounds; ₹250 crore eventually","₹196 crore after three rounds; ₹250 crore eventually","₹196 crore after three rounds; ₹166.7 crore eventually","₹216 crore after three rounds; ₹250 crore eventually"],"answer":1,"explanation":"Rounds: 100 + 60 + 36 = ₹196 crore. The full multiplier is 1/(1 − 0.6) = 2.5, so the eventual rise is ₹250 crore. ₹166.7 crore uses 1/MPC.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-120","question":"A car maker produces 1,000 cars this year but sells only 900; the rest stay in its warehouse. How do the unsold cars enter this year's GDP?","options":["They are excluded until they are sold","They are counted as consumption","They are subtracted as a loss","As investment in inventories, so all 1,000 cars count"],"answer":3,"explanation":"GDP measures production. Unsold output is recorded as inventory investment, so all 1,000 cars count this year; next year's sale of these cars will not add to GDP again.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-121","question":"Inflation caused by aggregate demand growing faster than the economy's productive capacity is called:","options":["Cost-push inflation","Demand-pull inflation","Deflation","Stagflation"],"answer":1,"explanation":"Too much spending chasing too few goods pulls prices up. Cost-push inflation comes from rising input costs such as wages or oil.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-122","question":"A consumer basket cost ₹2,400 in the base year and costs ₹2,580 now. What are the price index and the inflation rate since the base year?","options":["Index 107.5; inflation 7.5%","Index 93.0; inflation −7.0%","Index 107.5; inflation 180%","Index 180; inflation 7.5%"],"answer":0,"explanation":"Index = 2,580/2,400 × 100 = 107.5, so prices are 7.5% higher than in the base year.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-123","question":"Base-year quantities are 10 units of A and 4 units of B. Prices of A rose from ₹5 to ₹6 and of B from ₹20 to ₹22. What is the Laspeyres price index?","options":["115.00","87.84","112.86","113.85"],"answer":3,"explanation":"Laspeyres uses base-year quantities: (10 × 6 + 4 × 22)/(10 × 5 + 4 × 20) × 100 = 148/130 × 100 = 113.85. 115.00 is an unweighted average of price relatives.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-124","question":"Prices of A rose from ₹5 to ₹6 and of B from ₹20 to ₹22. Base-year quantities were 10 of A and 4 of B; current-year quantities are 8 of A and 5 of B. What is the Paasche price index?","options":["113.85","113.35","112.86","121.54"],"answer":2,"explanation":"Paasche uses current quantities: (8 × 6 + 5 × 22)/(8 × 5 + 5 × 20) × 100 = 158/140 × 100 = 112.86. 113.85 is the Laspeyres index and 113.35 is Fisher's ideal index (their geometric mean); 121.54 mixes current and base quantities.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-125","question":"A fixed deposit pays 9% a year while inflation is 5%. What is the exact real interest rate?","options":["4.00%","3.81%","14.45%","1.80%"],"answer":1,"explanation":"Real rate = 1.09/1.05 − 1 = 3.81%. 4% is the approximation (9 − 5).","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-126","question":"If inflation runs at 6% a year for 5 years, what will ₹1,00,000 then be worth in today's purchasing power?","options":["₹74,726","₹70,000","₹73,390","₹76,923"],"answer":0,"explanation":"Real value = 1,00,000/1.06⁵ = 1,00,000/1.33823 = ₹74,726. ₹70,000 subtracts 6% a year in simple terms; ₹73,390 applies a 6% fall each year, which is not the same as dividing by 1.06.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-127","question":"When the central bank buys government securities in the open market, what happens to bank reserves and money supply?","options":["Both decrease","Reserves increase but money supply falls","Both increase","Neither changes, because only ownership of bonds changes"],"answer":2,"explanation":"The central bank pays for the securities by crediting banks' reserve accounts, so reserves rise and banks can lend more, expanding money supply.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-128","question":"Match each monetary tool with its type. (p) Changing the cash reserve ratio, (q) Margin requirements on loans against specific commodities, (r) Open market operations, (s) Moral suasion. Types: (1) Quantitative, (2) Qualitative/selective.","options":["p-2, q-1, r-1, s-2","p-1, q-1, r-2, s-2","p-1, q-2, r-2, s-1","p-1, q-2, r-1, s-2"],"answer":3,"explanation":"Reserve ratios and open market operations change the overall volume of credit (quantitative). Margin requirements and moral suasion direct credit to or away from particular uses (qualitative).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-129","question":"Which combination of measures is contractionary (anti-inflationary) monetary policy?","options":["Cut the policy rate, buy government securities and cut the reserve ratio","Raise the policy rate, buy government securities and cut the reserve ratio","Cut taxes, raise spending and raise the policy rate","Raise the policy rate, sell government securities and raise the reserve ratio"],"answer":3,"explanation":"All three tighten liquidity and raise the cost of credit. Buying securities or cutting reserve ratios injects liquidity; tax and spending changes are fiscal, not monetary, tools.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-130","question":"Under the quantity theory (MV = PY), money supply grows by 10%, velocity is constant and real output grows by 6%. What is the inflation rate?","options":["4.00%","16.00%","3.77%","10.00%"],"answer":2,"explanation":"(1 + π) = (1 + ΔM)(1 + ΔV)/(1 + ΔY) = 1.10 × 1/1.06 → π = 3.77%. 4% is the approximation 10 − 6.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-131","question":"A central bank follows the rule i = r* + π + 0.5(π − π*) + 0.5 × (output gap). The neutral real rate r* is 2%, inflation 6%, the target 4% and output is 1% below potential. What policy rate does the rule suggest?","options":["9.5%","8.5%","7.5%","8.0%"],"answer":1,"explanation":"i = 2 + 6 + 0.5 × (6 − 4) + 0.5 × (−1) = 2 + 6 + 1 − 0.5 = 8.5%. 9.5% treats the negative output gap as positive.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-132","question":"Assertion (A): In the short run, policies that lower unemployment may raise inflation. Reason (R): The short-run Phillips curve shows an inverse relationship between inflation and unemployment.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. In the long run, as expectations adjust, the Phillips curve becomes vertical at the natural rate of unemployment.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-133","question":"Stagflation refers to a situation of:","options":["Falling prices and rising output","High growth with low inflation","Rising prices caused only by excess demand","High inflation together with stagnant output and high unemployment"],"answer":3,"explanation":"Stagflation combines inflation with weak growth and unemployment, usually from a supply shock, which makes demand management difficult.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-134","question":"Fiscal policy works mainly through:","options":["Government spending and taxation","The policy repo rate","Reserve requirements on banks","Open market operations"],"answer":0,"explanation":"Fiscal policy is run by the government through its budget. Interest rates, reserve ratios and open market operations are monetary policy tools.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-135","question":"Which of these act as automatic stabilisers? I. A progressive income tax. II. Unemployment benefits. III. A one-time stimulus package voted by parliament.","options":["I, II and III","I and II only","III only","II and III only"],"answer":1,"explanation":"Automatic stabilisers change without new decisions: tax collections fall and benefit payments rise in a downturn. A specially approved stimulus is discretionary fiscal policy.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-136","question":"In a year, a country's merchandise exports are ₹300 crore and imports ₹420 crore; net services exports are +₹80 crore, net transfers (remittances) +₹60 crore and net primary income −₹30 crore. What is its current account balance?","options":["Deficit of ₹120 crore","Surplus of ₹20 crore","Deficit of ₹10 crore","Deficit of ₹40 crore"],"answer":2,"explanation":"Current account = trade balance (−120) + services (+80) + transfers (+60) + primary income (−30) = −₹10 crore. −₹120 crore is only the merchandise trade deficit.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-137","question":"A country has a current account deficit of ₹10 crore, net FDI inflows of ₹25 crore, net portfolio outflows of ₹5 crore and other net capital inflows of ₹10 crore. Ignoring errors and omissions, what happens to its foreign exchange reserves?","options":["They fall by ₹20 crore","They rise by ₹20 crore","They rise by ₹30 crore","They fall by ₹10 crore"],"answer":1,"explanation":"Capital/financial account = 25 − 5 + 10 = +30. Overall balance = −10 + 30 = +20, which shows up as a ₹20 crore addition to reserves. ₹30 crore ignores the current account deficit.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-138","question":"A country's merchandise trade deficit is large, yet its current account is close to balance. The most likely reason is:","options":["Large foreign direct investment inflows","A rise in foreign exchange reserves","A large fiscal deficit","Large surpluses on services and remittances"],"answer":3,"explanation":"The current account adds services, primary income and transfers to the goods balance. FDI and reserves belong to the capital/financial account side, not the current account.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-139","question":"The rupee moves from ₹80 to ₹84 per US dollar. By what percentage has the rupee depreciated against the dollar, and the dollar appreciated against the rupee?","options":["Rupee −4.76%; dollar +5.00%","Rupee −5.00%; dollar +5.00%","Rupee −5.00%; dollar +4.76%","Rupee −4.00%; dollar +4.00%"],"answer":0,"explanation":"Dollar value in rupees: 84/80 − 1 = +5%. Rupee value in dollars: (1/84)/(1/80) − 1 = 80/84 − 1 = −4.76%. The two percentages differ because the bases differ.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-140","question":"A standard basket costs ₹4,000 in India and $60 in the US, while the market exchange rate is ₹80 per dollar. Which statement is correct?","options":["The PPP rate is ₹66.67 per dollar, so the rupee is overvalued at the market rate","The PPP rate is ₹120 per dollar, so the rupee is overvalued","The PPP rate is ₹66.67 per dollar, so the rupee is undervalued at the market rate","The PPP rate equals the market rate"],"answer":2,"explanation":"PPP rate = 4,000/60 = ₹66.67 per $. At the market rate ₹80, a dollar buys more in India than PPP implies, so the rupee is weaker (undervalued) than PPP suggests.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-141","question":"Inflation is expected to be 6% in India and 2% in the US. The spot rate is ₹80 per dollar. According to relative purchasing power parity, what is the expected exchange rate one year later?","options":["₹83.14 per $","₹83.20 per $","₹76.98 per $","₹84.80 per $"],"answer":0,"explanation":"Expected rate = 80 × 1.06/1.02 = ₹83.14. The higher-inflation currency depreciates by about the inflation difference. ₹83.20 is the approximation 80 × 1.04.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-142","question":"A country's trade is initially balanced. The price elasticity of demand for its exports is 0.4 and for its imports 0.5. If its currency depreciates, what happens to the trade balance, other things equal?","options":["It improves, because exports become cheaper","It worsens, because the elasticities sum to less than 1","It improves, because each elasticity is positive","It is unaffected, because trade was balanced"],"answer":1,"explanation":"The Marshall–Lerner condition says depreciation improves the trade balance only if export + import elasticities exceed 1. Here 0.4 + 0.5 = 0.9 < 1, so higher import prices outweigh the volume gains.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-143","question":"A government finances its fiscal deficit by borrowing directly from the central bank (monetisation). The main macroeconomic risk is:","options":["Crowding out through higher interest rates","A fall in the money supply","An automatic current account surplus","Inflation from the increase in money supply"],"answer":3,"explanation":"Monetisation creates new reserve money, which expands money supply and can feed inflation. Market borrowing, by contrast, tends to raise interest rates.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-144","question":"The nominal exchange rate is ₹80 per dollar. A representative basket costs $100 in the US and ₹7,200 in India. What is the real exchange rate (US basket in terms of Indian baskets) and what does it imply?","options":["0.90; Indian goods are relatively expensive","1.11; Indian goods are relatively expensive","1.11; Indian goods are relatively cheap","72.00; the rupee is overvalued"],"answer":2,"explanation":"Real exchange rate = e × P* / P = 80 × 100/7,200 = 1.11. One US basket buys 1.11 Indian baskets, so Indian goods are relatively cheap, which favours Indian exports.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-145","question":"A sharp rise in global crude oil prices that raises transport and production costs across the economy is an example of:","options":["Cost-push inflation","Demand-pull inflation","Deflation","Disinflation"],"answer":0,"explanation":"Higher input costs shift aggregate supply to the left, raising prices even without extra demand — cost-push inflation.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-146","question":"Which of the following is NOT one of Porter's five competitive forces?","options":["Threat of substitute products","Bargaining power of suppliers","Government regulation","Threat of new entrants"],"answer":2,"explanation":"The five forces are rivalry among existing firms, threat of new entrants, threat of substitutes, bargaining power of buyers and bargaining power of suppliers. Regulation affects these forces but is not itself one of the five.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-147","question":"In the BCG growth–share matrix, a business with a high relative market share in a slow-growing market is a:","options":["Star","Question mark","Dog","Cash cow"],"answer":3,"explanation":"Cash cows lead mature markets, generate more cash than they need and fund other units. Stars have high share in fast-growing markets.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-148","question":"In a SWOT analysis, which elements are internal to the organisation?","options":["Opportunities and threats","Strengths and weaknesses","Strengths and opportunities","Weaknesses and threats"],"answer":1,"explanation":"Strengths and weaknesses are internal attributes the firm controls; opportunities and threats arise in the external environment.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-149","question":"A packaged-snacks company starts selling its existing product range in Middle-East markets for the first time. In the Ansoff matrix this is:","options":["Market penetration","Market development","Product development","Diversification"],"answer":1,"explanation":"Existing products in new markets (here, new geographies) = market development. New products for existing markets would be product development; new products in new markets, diversification.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-150","question":"An airline offers no free meals, a single aircraft type, online-only booking and quick turnarounds to offer the lowest fares on busy routes. Which generic strategy is it following?","options":["Cost leadership","Differentiation","Differentiation focus","Stuck in the middle"],"answer":0,"explanation":"Its activities are designed to minimise cost per seat across a broad market, the hallmark of cost leadership.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-151","question":"In Porter's value chain, which of these is a SUPPORT activity rather than a primary activity?","options":["Outbound logistics","Marketing and sales","After-sales service","Procurement"],"answer":3,"explanation":"Primary activities: inbound logistics, operations, outbound logistics, marketing and sales, service. Support activities: firm infrastructure, human resource management, technology development and procurement.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-152","question":"In the McKinsey 7S framework, which three elements are the 'hard' elements?","options":["Shared values, style and staff","Skills, staff and systems","Strategy, structure and systems","Strategy, skills and shared values"],"answer":2,"explanation":"Hard elements (strategy, structure, systems) are easier to define and change. Soft elements are shared values, style, staff and skills.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-153","question":"Laptop assemblers depend on two global suppliers of a patented chip, and redesigning around a different chip takes two years. Which force does this most strengthen, and what is the effect on assemblers' profitability?","options":["Buyer power; it raises assemblers' profitability","Threat of substitutes; it lowers suppliers' profitability","Supplier power; it lowers assemblers' profitability","Threat of entry; it raises assemblers' profitability"],"answer":2,"explanation":"Concentrated suppliers of a unique input with high switching costs for buyers have strong bargaining power and can capture much of the industry's value.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-154","question":"Which factors RAISE barriers to entry in an industry? I. Large economies of scale. II. Heavy capital requirements. III. Low customer switching costs. IV. Incumbents' control of distribution channels.","options":["I, II, III and IV","I and III only","II, III and IV","I, II and IV"],"answer":3,"explanation":"Scale economies, capital needs and controlled distribution all deter entrants. Low switching costs make it EASIER for entrants to win customers, so III lowers barriers.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-155","question":"A business unit has sales of ₹120 crore; its largest competitor has ₹300 crore. Its market is growing at 18% a year. Using the BCG matrix (relative share cut-off 1.0), how should it be classified?","options":["Question mark (relative share 0.4)","Star (relative share 2.5)","Dog (relative share 0.4)","Cash cow (relative share 2.5)"],"answer":0,"explanation":"Relative market share = own sales/largest rival's sales = 120/300 = 0.4 (< 1, low). With high market growth, the unit is a question mark. Dividing the rival's sales by the unit's gives 2.5, the common inversion error.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-156","question":"A business unit has sales of ₹400 crore against ₹250 crore for its largest rival, in a market growing at 3% a year. What does the BCG approach recommend for it?","options":["Invest heavily to build share, as it is a star","Hold share and use its surplus cash to fund stars and promising question marks","Divest it, as it is a dog","Invest selectively, as it is a question mark"],"answer":1,"explanation":"Relative share = 400/250 = 1.6 (high) and growth is low, so it is a cash cow. The standard prescription is to defend its position with minimal investment and redeploy its cash to growth businesses.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-157","question":"Rank the four Ansoff growth strategies from LOWEST to HIGHEST risk, as the framework usually presents them.","options":["Diversification, product development, market development, market penetration","Product development, market penetration, diversification, market development","Market penetration, market development or product development, diversification","Market development, diversification, market penetration, product development"],"answer":2,"explanation":"Penetration stays with known products and customers (lowest risk). Market development and product development each add one unknown. Diversification adds both, so it is the riskiest.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-158","question":"For a domestic cement company, which SWOT classification is correct?","options":["Its well-known brand — opportunity","A government push for affordable housing — strength","Its ageing kilns — threat","Rising global coal prices — threat"],"answer":3,"explanation":"Coal prices are an external, unfavourable factor (threat). A brand is an internal strength; a housing push is an external opportunity; ageing kilns are an internal weakness.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-159","question":"Assertion (A): Porter warns that a firm trying to be both the lowest-cost producer and highly differentiated across a broad market risks being 'stuck in the middle'. Reason (R): Such a firm may end up with neither the lowest costs nor a strong enough differentiation premium, leaving it below-average returns.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. Porter argued that the two strategies require different investments and cultures; trying for both usually means doing neither well (though some firms have managed both through innovation).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-160","question":"Blue Ocean Strategy's 'four actions framework' asks managers to decide which factors to:","options":["Plan, do, check and act","Eliminate, reduce, raise and create","Analyse, design, develop and evaluate","Penetrate, develop, extend and diversify"],"answer":1,"explanation":"To achieve value innovation, firms eliminate and reduce factors the industry over-serves, and raise and create factors that open uncontested market space.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-161","question":"According to Prahalad and Hamel, a core competence should satisfy which criteria?","options":["It is the firm's most profitable product line","It gives access to a wide variety of markets, contributes significantly to customer benefits and is difficult to imitate","It is protected by a patent and is owned by one division","It is based on the lowest-cost location of production"],"answer":1,"explanation":"Core competences are collective learning (for example miniaturisation) that can be leveraged across many products, matter to customers and are hard for rivals to copy.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-162","question":"Under the VRIO framework, a resource is valuable, rare and costly to imitate, but the firm is not organised to exploit it. What is the competitive implication?","options":["Sustained competitive advantage","Competitive parity","An unused (unexploited) competitive advantage","Temporary competitive advantage"],"answer":2,"explanation":"Sustained advantage requires all four: valuable, rare, inimitable and organised. Without the organisation to use it, the potential advantage remains unexploited.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-163","question":"Which combination of conditions is most likely to make rivalry among existing firms intense?","options":["High fixed costs, slow industry growth, undifferentiated products and high exit barriers","Low fixed costs, fast growth, strong brands and low exit barriers","Few competitors of very different sizes, fast growth and high switching costs","High fixed costs, fast growth, strong differentiation and low exit barriers"],"answer":0,"explanation":"High fixed costs push firms to cut price to fill capacity; slow growth makes it a fight for share; commodity products make price the main weapon; exit barriers keep weak firms in the market.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-164","question":"A car manufacturer acquires a tyre manufacturer that supplies it. This is an example of:","options":["Forward vertical integration","Horizontal integration","Conglomerate diversification","Backward vertical integration"],"answer":3,"explanation":"Moving upstream into the supply of inputs is backward integration. Buying a dealer network would be forward integration; buying another carmaker, horizontal.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-165","question":"An acquirer worth ₹500 crore buys a target worth ₹200 crore on a standalone basis by paying ₹260 crore in cash. The combined firm is valued at ₹800 crore. What is the gain to the acquirer's shareholders?","options":["₹100 crore","₹60 crore","₹40 crore","₹300 crore"],"answer":2,"explanation":"Synergy = 800 − (500 + 200) = ₹100 crore. Premium paid = 260 − 200 = ₹60 crore, which goes to the target's shareholders. Acquirer's gain = synergy − premium = ₹40 crore (check: 800 − 260 = 540, versus 500 before).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-166","question":"Why did BCG's original logic link high relative market share with higher profitability?","options":["High share always allows a firm to charge the highest prices","Regulators protect market leaders from competition","High-share firms need no investment in marketing","Higher cumulative volume moves a firm down the experience curve, lowering its unit costs"],"answer":3,"explanation":"The experience curve suggests unit costs fall by a roughly constant percentage each time cumulative output doubles, so the share leader should have the lowest costs and the highest margins.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-167","question":"Match each factor with its PESTEL category for an electric-scooter maker. (p) A new subsidy for electric vehicles, (q) Rising household disposable incomes, (r) Breakthroughs in battery chemistry, (s) Stricter battery recycling norms. Categories: (1) Political, (2) Economic, (3) Technological, (4) Environmental.","options":["p-2, q-1, r-3, s-4","p-1, q-2, r-3, s-4","p-1, q-2, r-4, s-3","p-4, q-2, r-3, s-1"],"answer":1,"explanation":"Government subsidies are political choices; incomes are economic; battery advances are technological; recycling norms address environmental impact (they could also be argued as legal, but environmental is the listed fit).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-168","question":"In Kaplan and Norton's balanced scorecard, under which perspective does 'average time taken to process a customer order' usually fall?","options":["Internal business process","Financial","Customer","Learning and growth"],"answer":0,"explanation":"Order-processing time measures how efficiently internal operations run. Customer measures look at satisfaction and retention; learning and growth covers people, skills and systems.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-169","question":"A chocolatier sells only high-priced, hand-crafted gift boxes to corporate clients in a few metro cities. Which generic strategy is this?","options":["Differentiation focus","Cost focus","Broad differentiation","Cost leadership"],"answer":0,"explanation":"It serves a narrow segment (corporate gifting in metros) with a premium, distinctive product: differentiation focus.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-170","question":"Why do digital platforms with strong network effects often see 'winner-take-most' outcomes?","options":["Their marginal cost rises sharply with each user","Regulators usually grant them exclusive licences","Users can join several rival platforms at no cost, so there is no lock-in","Each additional user makes the platform more valuable to others, so the leader's advantage feeds on itself"],"answer":3,"explanation":"With network effects, value grows with the number of users (and, for two-sided platforms, with users on the other side). This positive feedback makes it hard for smaller rivals to catch up. Easy multi-homing works against winner-take-all.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-171","question":"A group has two cash cows, one star, and three question marks, and its funds are limited. Which allocation follows BCG logic?","options":["Spread investment equally across all six units","Invest heavily in the cash cows to raise their growth rate","Use cash-cow surpluses to support the star and the most promising question mark, and divest or harvest the weaker question marks","Divest the star to fund all three question marks"],"answer":2,"explanation":"Cash cows fund growth. With limited funds, back the star to keep its leadership and pick question marks that can become stars; the rest should be harvested or sold rather than starved slowly.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-172","question":"A foreign insurer with product expertise forms a joint venture with a domestic bank that has a large branch network. The main strategic logic is:","options":["Achieving economies of scale in the same activity","Combining complementary resources: product know-how with distribution access","Reducing the number of competitors through a merger","Backward integration into raw materials"],"answer":1,"explanation":"Joint ventures often pair partners with complementary assets; here one brings products and underwriting skills, the other customers and distribution.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-173","question":"A firm's cost per unit is: inbound logistics ₹10, operations ₹30, outbound logistics ₹8, marketing ₹12 and service ₹5; it sells at ₹100. If it cuts operations cost to a rival's ₹22 and also cuts its price by 5%, what will its margin be as a percentage of the new price?","options":["43.00%","38.00%","40.00%","36.84%"],"answer":2,"explanation":"Current cost = 10 + 30 + 8 + 12 + 5 = ₹65. New cost = 65 − 8 = ₹57. New price = ₹95. Margin = 95 − 57 = ₹38 = 40.00% of the new price. 43% ignores the price cut; 38% divides by the old price.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-174","question":"A consultant is asked why a client's profits fell this year. Using a profitability framework, what is the most logical first step?","options":["Check whether revenue fell, costs rose, or both","Recommend an immediate price increase","Survey employees about morale","Benchmark the client's share price against peers"],"answer":0,"explanation":"Profit = revenue − costs. Splitting the problem into these two branches first keeps the analysis structured before drilling into price, volume, fixed and variable costs.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-175","question":"Estimating a product's market by starting from a country's population and narrowing it down through segments and usage rates is called:","options":["Bottom-up market sizing","Value-chain analysis","Benchmarking","Top-down market sizing"],"answer":3,"explanation":"Top-down sizing starts from a large total (population, households) and applies filters. Bottom-up builds from units such as stores, outlets or customers and their sales.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-176","question":"A café sells a coffee for ₹150; milk, beans, cup and card fees cost ₹60 per cup. What is the contribution per cup?","options":["₹150","₹90","₹60","₹210"],"answer":1,"explanation":"Contribution = price − variable cost = 150 − 60 = ₹90, which goes towards rent, salaries and profit.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-177","question":"A city has 1 crore people living in households of 4 on average. If 40% of households take one printed newspaper daily, roughly how many newspapers are sold each day?","options":["40 lakh","4 lakh","25 lakh","10 lakh"],"answer":3,"explanation":"Households = 1 crore/4 = 25 lakh. Subscribing households = 40% × 25 lakh = 10 lakh, each taking one paper. 40 lakh applies 40% to people instead of households.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-178","question":"A city of 50 lakh people has 2% births a year. Assume children use diapers for their first 2 years, half of them use disposable diapers, and each uses 5 a day. Roughly how many diapers are used per month (30 days)?","options":["3 crore","75 lakh","1.5 crore","15 lakh"],"answer":2,"explanation":"Births = 1 lakh a year, so about 2 lakh children are under 2. Users = 50% × 2 lakh = 1 lakh. Daily use = 5 lakh; monthly ≈ 1.5 crore. 75 lakh counts only one year of children.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-179","question":"A fuel station serves 30 vehicles an hour for 12 hours a day. Each vehicle buys 20 litres on average and the station earns ₹4 per litre. What is its daily gross margin?","options":["₹28,800","₹2,400","₹7,200","₹1,44,000"],"answer":0,"explanation":"Vehicles = 30 × 12 = 360; litres = 360 × 20 = 7,200; margin = 7,200 × 4 = ₹28,800. ₹7,200 is litres sold, not rupees.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-180","question":"A café costs ₹30 lakh to set up. Monthly fixed costs are ₹3 lakh, it sells 200 cups a day for 30 days a month, and each cup contributes ₹90. Ignoring taxes and discounting, how many months will it take to recover the set-up cost?","options":["5.6 months","12.5 months","10 months","16.7 months"],"answer":1,"explanation":"Monthly contribution = 200 × 30 × 90 = ₹5.4 lakh; operating profit = 5.4 − 3 = ₹2.4 lakh. Payback = 30/2.4 = 12.5 months. 5.6 months ignores fixed costs.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-181","question":"A subscription app charges ₹500 a month with a 60% contribution margin. Each month 5% of subscribers cancel. Ignoring discounting, what is the lifetime value of a subscriber, and how does it compare with a customer acquisition cost of ₹2,000?","options":["₹10,000; LTV/CAC = 5","₹6,000; LTV/CAC = 0.33","₹300; LTV/CAC = 0.15","₹6,000; LTV/CAC = 3"],"answer":3,"explanation":"Expected life = 1/churn = 1/0.05 = 20 months. LTV = 500 × 60% × 20 = ₹6,000. LTV/CAC = 6,000/2,000 = 3. ₹10,000 uses revenue instead of contribution.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-182","question":"A product has a 40% contribution margin. If the firm cuts price by 10%, by how much must unit sales rise to keep total contribution unchanged?","options":["10.0%","33.3%","25.0%","11.1%"],"answer":1,"explanation":"On a ₹100 price: contribution falls from ₹40 to ₹30 per unit. Required volume = 40/30 = 1.333 times, i.e. +33.3%. Price cuts need large volume gains when margins are thin.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-183","question":"A ₹2,000 crore market grows 10% next year. A firm with ₹300 crore of sales grows its revenue by 8%. What happens to its market share?","options":["It rises from 15.00% to 16.20%","It stays at 15.00%","It falls from 15.00% to 14.73%","It falls from 15.00% to 13.00%"],"answer":2,"explanation":"Next year: firm 300 × 1.08 = ₹324 crore; market ₹2,200 crore. Share = 324/2,200 = 14.73%, down from 15%. A firm growing slower than its market loses share.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-184","question":"An online store gets 1,00,000 visitors a month; 4% add items to the cart, 50% of those check out and the average order is ₹1,200. If the add-to-cart rate rises to 5%, by how much does monthly revenue rise?","options":["₹6 lakh (from ₹24 lakh to ₹30 lakh)","₹1.2 lakh (from ₹24 lakh to ₹25.2 lakh)","₹12 lakh (from ₹24 lakh to ₹36 lakh)","₹6 lakh (from ₹48 lakh to ₹54 lakh)"],"answer":0,"explanation":"Orders = 1,00,000 × 4% × 50% = 2,000 → revenue ₹24 lakh. At 5%: 2,500 orders → ₹30 lakh. A one-point rise in the conversion step lifts revenue by 25%.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-185","question":"A company's revenue fell from ₹100 crore to ₹90 crore even though it sold 5% more units. By how much did its average selling price change?","options":["−10.00%","−15.00%","−14.29%","−5.00%"],"answer":2,"explanation":"Revenue = price × volume → 90 = 100 × (1 + Δp) × 1.05 → 1 + Δp = 90/105 → Δp = −14.29%. −15% simply adds the two percentages.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-186","question":"A new product will sell 10,000 units with a contribution of ₹50 each. Market research shows 40% of its buyers would otherwise have bought the firm's existing product, which earns ₹70 a unit. What is the net incremental contribution from the launch?","options":["₹2,20,000","₹5,00,000","₹3,00,000","−₹2,00,000"],"answer":0,"explanation":"Gross contribution = 10,000 × 50 = ₹5,00,000. Cannibalised units = 4,000 × 70 = ₹2,80,000 lost. Net = ₹2,20,000. ₹3,00,000 values the lost units at the new product's ₹50.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-187","question":"A country has 60 crore smartphone users, and users replace their phones every 3 years on average. Ignoring new users, roughly how many smartphones are sold per year?","options":["60 crore","20 crore","180 crore","3 crore"],"answer":1,"explanation":"Annual replacement = installed base/replacement cycle = 60/3 = 20 crore. 180 crore multiplies instead of dividing.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-188","question":"A client asks whether it should enter a new market. Which question is LEAST central to a standard market-entry framework?","options":["How large is the market and how fast is it growing?","Who are the competitors and how will they react?","Can the client make money there, and what entry mode suits it?","What was the client's share price five years ago?"],"answer":3,"explanation":"Market-entry analysis covers market attractiveness, competition, the client's capabilities, economics/break-even, entry mode and risks. Historical share price is not relevant to the decision.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-189","question":"A new machine will save a customer ₹5 lakh a year for 4 years compared with its current process. If the customer's cost of capital is 10% and it has no other alternatives, what is the most it should rationally pay for the machine?","options":["₹20,00,000","₹15,84,933","₹17,43,426","₹50,00,000"],"answer":1,"explanation":"Maximum price = PV of savings = 5,00,000 × 3.1699 = ₹15,84,933. ₹20 lakh ignores the time value of money; ₹50 lakh treats the saving as a perpetuity. Value-based pricing sets price below this ceiling.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-190","question":"An assembly line has three sequential stations with capacities of 120, 90 and 150 units an hour. What is the line's maximum output, and where should the manager focus?","options":["120 units an hour; on the first station","150 units an hour; on the third station","360 units an hour; on all stations equally","90 units an hour; on the second station (the bottleneck)"],"answer":3,"explanation":"A sequential process can produce no faster than its slowest step. Extra capacity elsewhere adds nothing until the bottleneck is relieved.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-191","question":"A plant with capacity 10,000 units currently makes 7,000 units, selling at ₹600 with variable cost ₹300 and fixed costs ₹14 lakh. A buyer offers to take 2,000 extra units at ₹400 each without affecting regular sales. What is the effect on profit?","options":["Rises by ₹2 lakh","Falls by ₹0.8 lakh because ₹400 is below average cost","Rises by ₹8 lakh","Unchanged"],"answer":0,"explanation":"Spare capacity exists and fixed costs do not change, so incremental profit = 2,000 × (400 − 300) = ₹2 lakh. Average full cost at 7,000 units (₹500) is irrelevant to the decision.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-192","question":"A plant with capacity 10,000 units currently makes and sells 9,000 units at ₹600 (variable cost ₹300). A buyer wants 2,000 units at ₹400 and will take all or none. Accepting means giving up regular sales to stay within capacity. What is the effect on profit?","options":["Rises by ₹2 lakh","Rises by ₹1 lakh","Falls by ₹1 lakh","Falls by ₹3 lakh"],"answer":2,"explanation":"Only 1,000 units are spare, so 1,000 regular units must be dropped. Gain = 2,000 × (400 − 300) = ₹2 lakh; lost contribution = 1,000 × (600 − 300) = ₹3 lakh. Net = −₹1 lakh, so reject.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-193","question":"A retail chain notices that stores with more staff have higher sales and proposes hiring more staff everywhere. What is the main flaw in this reasoning?","options":["Staff costs are always fixed","Sales data cannot be compared across stores","Busier stores may have been given more staff, so the correlation may not show that staff cause sales","Hiring more staff always reduces customer satisfaction"],"answer":2,"explanation":"Correlation does not prove causation; reverse causality (high sales lead to more staff) or a third factor (location) may explain it. A controlled test in a few stores would settle it.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-194","question":"A product launch has a 60% chance of earning ₹50 crore and a 40% chance of losing ₹30 crore; not launching earns zero. A test market costing ₹4 crore would reveal the outcome perfectly in advance. What is the expected value of perfect information, and should the firm run the test?","options":["₹18 crore; yes, run the test","₹12 crore; no, launch directly","₹26 crore; yes, run the test","₹12 crore; yes, run the test"],"answer":3,"explanation":"Without the test: EV = 0.6 × 50 − 0.4 × 30 = ₹18 crore. With perfect information the firm launches only on success: 0.6 × 50 = ₹30 crore. EVPI = 30 − 18 = ₹12 crore > ₹4 crore cost, so testing adds ₹8 crore.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-195","question":"A multiplex has 4 screens of 200 seats each, runs 5 shows a day per screen at 50% average occupancy and an average ticket price of ₹250. What is its daily ticket revenue?","options":["₹10 lakh","₹5 lakh","₹2.5 lakh","₹1 lakh"],"answer":1,"explanation":"Seats sold = 4 × 200 × 5 × 50% = 2,000; revenue = 2,000 × 250 = ₹5,00,000. ₹10 lakh assumes full occupancy.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-196","question":"A firm sells product A (40% margin) and product B (20% margin). Total revenue stays at ₹100 crore, but the mix shifts from 50:50 to 30:70 (A:B). What happens to profit?","options":["It falls by ₹4 crore, from ₹30 crore to ₹26 crore","It is unchanged because revenue is unchanged","It falls by ₹6 crore, from ₹30 crore to ₹24 crore","It rises by ₹4 crore, from ₹26 crore to ₹30 crore"],"answer":0,"explanation":"Before: 50 × 40% + 50 × 20% = 20 + 10 = ₹30 crore. After: 30 × 40% + 70 × 20% = 12 + 14 = ₹26 crore. A shift towards the low-margin product cuts profit even with flat revenue.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-197","question":"A railway station has 1 lakh passengers a day. If 10% buy tea and each buyer has 1.5 cups on average, roughly how many cups are sold in a week?","options":["About 1.05 lakh","About 15,000","About 70,000","About 10.5 lakh"],"answer":0,"explanation":"Daily cups = 1,00,000 × 10% × 1.5 = 15,000; weekly = 15,000 × 7 = 1,05,000. 15,000 is the daily figure.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-198","question":"A product sells at ₹100 with variable cost ₹70. Its price elasticity of demand is −1.5. If the firm raises its price by 5%, what happens to total contribution (use the elasticity to estimate the volume change)?","options":["It falls by about 2.5%","It rises by about 5.0%","It falls by about 7.5%","It rises by about 7.9%"],"answer":3,"explanation":"Volume falls 1.5 × 5% = 7.5%. Contribution per unit rises from ₹30 to ₹35. New contribution = 35 × 0.925 = 32.375 versus 30, a rise of 7.9%. Revenue falls (elastic demand) but contribution rises because margin per unit jumps by 16.7%.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-199","question":"In structuring a case, an issue tree is said to be 'MECE'. This means its branches are:","options":["Measurable, economical, clear and exact","Mutually exclusive and collectively exhaustive","Mostly equal in cost and effort","Mapped to each client executive"],"answer":1,"explanation":"MECE branches do not overlap (mutually exclusive) and together cover every possibility (collectively exhaustive), so nothing is double-counted or missed.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-200","question":"A company considering entry estimates fixed costs of ₹12 crore a year and a contribution of ₹400 per unit. The total market is 10 lakh units a year. What market share does it need just to break even?","options":["3%","12%","30%","40%"],"answer":2,"explanation":"Break-even volume = 12,00,00,000/400 = 3,00,000 units, which is 3 lakh/10 lakh = 30% of the market — a demanding share for a new entrant.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-201","question":"A consumer has ₹1,200 to spend on goods X (₹30 each) and Y (₹20 each). With X on the horizontal axis, what are the slope of her budget line and the maximum X she can buy?","options":["Slope −0.67; 40 units of X","Slope −1.5; 40 units of X","Slope −1.5; 60 units of X","Slope −0.67; 60 units of X"],"answer":1,"explanation":"Budget line: 30X + 20Y = 1,200 → Y = 60 − 1.5X. Slope = −Px/Py = −30/20 = −1.5; X-intercept = 1,200/30 = 40. 60 is the maximum Y.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-202","question":"A consumer's utility is U = X^0.5 · Y^0.5. Her income is ₹1,200, Px = ₹30 and Py = ₹20. What bundle maximises her utility?","options":["X = 24, Y = 24","X = 30, Y = 20","X = 20, Y = 30","X = 40, Y = 0"],"answer":2,"explanation":"With equal exponents she spends half her income on each good: X = 600/30 = 20 and Y = 600/20 = 30. Check: MRS = Y/X = 1.5 = Px/Py. (24, 24) buys equal quantities and costs 1,200 too, but MRS = 1 ≠ 1.5.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-203","question":"Utility is U = X^0.3 · Y^0.7. Income is ₹2,000, Px = ₹10 and Py = ₹35. What is the utility-maximising bundle?","options":["X = 140, Y = 17.14","X = 100, Y = 28.57","X = 30, Y = 48.57","X = 60, Y = 40"],"answer":3,"explanation":"Cobb–Douglas: spend 30% on X and 70% on Y. X = 0.3 × 2,000/10 = 60; Y = 0.7 × 2,000/35 = 40. Check MRS = (0.3/0.7)(Y/X) = 0.2857 = 10/35. (140, 17.14) swaps the shares; (100, 28.57) splits income equally.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-204","question":"A consumer with U = X · Y has income ₹1,200; Py = ₹20. The price of X rises from ₹30 to ₹40. Using the Slutsky method (compensate her so she can just afford her original bundle), split the fall in X into substitution and income effects.","options":["Total −5 units: substitution −2.5, income −2.5","Total −5 units: substitution −5, income 0","Total −5 units: substitution −1.5, income −3.5","Total −2.5 units: substitution −2.5, income 0"],"answer":0,"explanation":"Demand X = M/(2Px). Initially X = 1,200/60 = 20 (Y = 30); after the rise X = 1,200/80 = 15, a total fall of 5. Slutsky income to buy (20, 30) at new prices = 20 × 40 + 30 × 20 = ₹1,400 → X = 1,400/80 = 17.5. Substitution effect = 17.5 − 20 = −2.5; income effect = 15 − 17.5 = −2.5.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-205","question":"A consumer's utility is U = X² · Y. At the bundle X = 4, Y = 10, what is her marginal rate of substitution of X for Y (units of Y she would give up for one more X)?","options":["0.2","5","2.5","1.25"],"answer":1,"explanation":"MRS = MUx/MUy = (2XY)/(X²) = 2Y/X = 2 × 10/4 = 5. 2.5 forgets the exponent (Y/X); 0.2 inverts the ratio.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-206","question":"A consumer always takes exactly 2 spoons of sugar (Y) with each cup of tea (X), so her utility is U = min(X, Y/2). Tea costs ₹6 a cup, sugar ₹2 a spoon, and she spends ₹100. How much does she buy?","options":["12.5 cups and 12.5 spoons","8.33 cups and 25 spoons","10 cups and 20 spoons","16.67 cups and 0 spoons"],"answer":2,"explanation":"Perfect complements are bought in fixed proportion Y = 2X. Spending: 6X + 2(2X) = 100 → 10X = 100 → X = 10, Y = 20. Any other split wastes money on unmatched units.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-207","question":"A consumer's utility is U = 2X + Y (perfect substitutes). Px = ₹5, Py = ₹3 and income is ₹150. What does she buy?","options":["No X and 50 units of Y","15 units of X and 25 units of Y","18.75 units of X and 18.75 units of Y","30 units of X and no Y"],"answer":3,"explanation":"Compare utility per rupee: X gives 2/5 = 0.40, Y gives 1/3 = 0.33. With perfect substitutes she spends everything on the better-value good: X = 150/5 = 30 — a corner solution, since MRS (2) never equals the price ratio (5/3).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-208","question":"For a consumer with well-behaved preferences, which statements about indifference curves are correct? I. They slope downward. II. They are convex to the origin because the marginal rate of substitution diminishes. III. Two indifference curves can cross if tastes are strong enough. IV. A higher curve represents a higher level of satisfaction.","options":["I, II and IV only","I and II only","I, II, III and IV","II, III and IV only"],"answer":0,"explanation":"Monotonic, convex preferences give downward-sloping, convex curves (I, II), and higher curves mean more utility (IV). Crossing curves would make one bundle both equal to and better than another, violating transitivity, so III is false.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-209","question":"A consumer's money income doubles and, at the same time, the prices of both goods she buys double. What happens to her budget line?","options":["It shifts outward parallel to itself","It does not change","It shifts inward parallel to itself","It becomes steeper"],"answer":1,"explanation":"Both intercepts are M/Px and M/Py; doubling M, Px and Py leaves them unchanged, and the slope −Px/Py is unchanged too. Real purchasing power is the same.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-210","question":"A household has U = X · Y, income ₹1,200, Px = ₹30 and Py = ₹20. The government considers (a) subsidising X by 50% (so Px = ₹15), or (b) a cash grant giving the same utility as the subsidy. Which is cheaper for the government, and by roughly how much?","options":["The subsidy: ₹600 against about ₹750 for the cash grant","They cost the same, ₹600 each","The cash grant: about ₹497 against ₹600 for the subsidy","The cash grant: about ₹497 against ₹300 for the subsidy"],"answer":2,"explanation":"With the subsidy she buys X = 1,200/(2 × 15) = 40 and Y = 30, so U = 1,200; the government pays 40 × ₹15 = ₹600. A cash grant G at original prices gives U = (1,200 + G)²/(4 × 30 × 20); setting this to 1,200 gives 1,200 + G = ₹1,697.06, so G ≈ ₹497. The grant is cheaper because it does not distort relative prices.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-211","question":"A firm's production function is Q = 2L + 3K. If it doubles both labour and capital, output:","options":["More than doubles, so it has increasing returns to scale","Less than doubles, so it has decreasing returns to scale","Rises by 2.5 times, the average of the coefficients","Doubles, so it has constant returns to scale"],"answer":3,"explanation":"2(2L) + 3(2K) = 2(2L + 3K) = 2Q. A linear production function is homogeneous of degree 1: constant returns to scale.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-212","question":"A firm's production function is Q = 10 · L^0.5 · K^0.5. At L = 16 and K = 4, what is the marginal rate of technical substitution of labour for capital (MRTS = MPL/MPK)?","options":["0.25","4","0.5","1"],"answer":0,"explanation":"MPL = 5K^0.5/L^0.5 and MPK = 5L^0.5/K^0.5, so MRTS = MPL/MPK = K/L = 4/16 = 0.25: one more worker can replace a quarter unit of capital. 4 inverts the ratio.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-213","question":"A firm's production function is Q = L^0.25 · K^0.75. The wage is ₹10 and the rental rate of capital ₹30. What is the minimum cost of producing 100 units?","options":["₹3,464","₹4,000","₹2,000","₹5,196"],"answer":1,"explanation":"Cost minimisation: MPL/MPK = w/r → (0.25/0.75)(K/L) = 10/30 → K = L. Then Q = L = 100, so L = K = 100 and cost = 100 × 10 + 100 × 30 = ₹4,000. Using equal input spending (as for equal exponents) gives a higher cost.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-214","question":"A firm has Q = L^0.5 · K^0.5, a wage of ₹4 and a rental rate of ₹16. In the short run capital is fixed at K = 25. What is the extra cost of producing 20 units in the short run compared with the long run, when K can be chosen freely?","options":["₹0","₹80","₹144","₹304"],"answer":2,"explanation":"Short run: 20 = √(25L) → L = 16; cost = 16 × 4 + 25 × 16 = ₹464. Long run: MPL/MPK = K/L = w/r = 1/4 → L = 4K, Q = 2K → K = 10, L = 40; cost = 160 + 160 = ₹320. Extra cost = ₹144, because the fixed capital stock is too large for this output.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-215","question":"An industry's output follows Q = A · L^0.7 · K^0.3 and factors are paid their marginal products. Which statements are correct? I. Labour receives 70% of the value of output. II. If L rises 10% and K rises 5%, output rises by about 8.5%. III. The function has increasing returns to scale.","options":["I only","II and III only","I, II and III","I and II only"],"answer":3,"explanation":"With Cobb–Douglas and marginal-product pricing, wL/PQ = 0.7 (I). Output growth ≈ 0.7 × 10% + 0.3 × 5% = 8.5% (II). The exponents sum to 1, so returns to scale are constant, not increasing (III false).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-216","question":"Assertion (A): A production function can show diminishing marginal returns to each input and still have increasing returns to scale. Reason (R): Returns to scale concern a proportional change in all inputs together, whereas marginal returns concern changing one input with others held fixed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. Example: Q = L^0.6 K^0.6 has diminishing marginal product of each input (exponent < 1) but increasing returns to scale (0.6 + 0.6 > 1).","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-217","question":"In the short run, as more workers are added to a fixed plant, which relationship between the average product (AP) and marginal product (MP) of labour always holds?","options":["MP cuts AP at AP's maximum; AP rises while MP is above it","AP cuts MP at MP's maximum","AP and MP reach their maxima at the same employment level","MP is always below AP"],"answer":0,"explanation":"If the next worker adds more than the current average, the average rises; if less, it falls. So AP rises when MP > AP, falls when MP < AP, and MP = AP exactly where AP peaks.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-218","question":"A firm's call centre is deciding how many agents to add. Each agent costs ₹30,000 a month. The extra monthly profit (before the agent's cost) from the 1st, 2nd, 3rd, 4th and 5th additional agent is ₹80,000, ₹60,000, ₹45,000, ₹32,000 and ₹25,000. How many should it add?","options":["3","4","5","2"],"answer":1,"explanation":"Add agents while marginal benefit ≥ marginal cost: the 4th adds ₹32,000 > ₹30,000, the 5th only ₹25,000. Net gain with 4 = (80 + 60 + 45 + 32) − 4 × 30 = ₹97,000, the maximum.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-219","question":"A toll-free bridge costs ₹200 crore now and gives commuters time and fuel savings worth ₹25 crore a year for 20 years; maintenance costs ₹3 crore a year. At a social discount rate of 8%, what are its NPV and benefit–cost ratio (PV of benefits ÷ PV of costs)?","options":["NPV ≈ ₹45.5 crore; BCR ≈ 1.23","NPV ≈ ₹240.0 crore; BCR ≈ 1.92","NPV ≈ ₹16.0 crore; BCR ≈ 1.07","NPV ≈ ₹16.0 crore; BCR ≈ 0.93"],"answer":2,"explanation":"Annuity factor (8%, 20 years) = 9.8181. PV of benefits = 25 × 9.8181 = ₹245.5 crore; PV of costs = 200 + 3 × 9.8181 = ₹229.5 crore. NPV ≈ ₹16.0 crore, BCR ≈ 1.07: just worthwhile. Ignoring discounting (₹240 crore NPV) hugely overstates it.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-220","question":"A city's total benefit from Q kilometres of new cycle lanes is B = 100Q − Q² and the total cost is C = 20Q + Q² (₹ lakh). What length maximises net benefit, and what is that net benefit?","options":["50 km; ₹500 lakh","40 km; ₹0 lakh","20 km; ₹1,600 lakh","20 km; ₹800 lakh"],"answer":3,"explanation":"Set MB = MC: 100 − 2Q = 20 + 2Q → Q = 20. B = 2,000 − 400 = 1,600; C = 400 + 400 = 800; net benefit = ₹800 lakh. 50 km maximises total benefit, ignoring cost (net = 2,500 − 3,500 = −₹1,000 lakh); at 40 km benefits just equal costs.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-221","question":"An hour before departure, a flight has empty seats. The airline's average cost per seat (including aircraft, crew and fuel) is ₹4,000, but an extra passenger adds only ₹600 in catering, fees and fuel. A walk-in traveller offers ₹1,500 for a seat. Assuming no effect on other fares, should the airline accept?","options":["Yes, because the fare exceeds the marginal cost and adds ₹900 to profit","No, because the fare is below the average cost of ₹4,000","No, because it loses ₹2,500 on the seat","Yes, but only if the fare covers at least half the average cost"],"answer":0,"explanation":"Short-run decisions depend on marginal, not average, cost. The flight's other costs are incurred anyway, so the extra passenger raises profit by ₹1,500 − ₹600 = ₹900. The caveat is fence-building, so regular customers do not wait for last-minute deals.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-222","question":"A firm makes 10,000 units a year of a component at a variable cost of ₹40 each. A supplier offers it at ₹46. If the firm buys, the freed capacity can make another product earning a contribution of ₹80,000 a year; fixed costs are unchanged either way. What should it do?","options":["Make; it saves ₹60,000 a year","Buy; it saves ₹20,000 a year","Make; it saves ₹20,000 a year","Buy; it saves ₹80,000 a year"],"answer":1,"explanation":"Making costs 10,000 × 40 = ₹4,00,000 plus the ₹80,000 contribution forgone = ₹4,80,000. Buying costs 10,000 × 46 = ₹4,60,000. Buying is better by ₹20,000. Ignoring the opportunity cost wrongly favours making by ₹60,000.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-223","question":"A firm's production function is Q = (L^0.5 + K^0.5)². What returns to scale does it show, and what is the MRTS (MPL/MPK) at L = 9, K = 4?","options":["Increasing returns; MRTS = 2/3","Constant returns; MRTS = 3/2","Constant returns; MRTS = 2/3","Decreasing returns; MRTS = 4/9"],"answer":2,"explanation":"Scaling inputs by t: ((tL)^0.5 + (tK)^0.5)² = (t^0.5)²(L^0.5 + K^0.5)² = tQ, so constant returns. MPL = (L^0.5 + K^0.5)·L^−0.5 and MPK = (L^0.5 + K^0.5)·K^−0.5, so MRTS = (K/L)^0.5 = (4/9)^0.5 = 2/3.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-224","question":"A consumer has Cobb–Douglas utility U = X^a · Y^(1−a). Which statements about her demand for X are correct? I. Its income elasticity is 1. II. Its own-price elasticity is −1, so her spending on X does not change when Px changes. III. Its cross-price elasticity with respect to Py is zero. IV. X is a Giffen good if a < 0.5.","options":["I and II only","II and III only","I, II, III and IV","I, II and III only"],"answer":3,"explanation":"Demand is X = aM/Px. So X is proportional to M (income elasticity 1), inversely proportional to Px (elasticity −1; spending aM is constant) and independent of Py (cross elasticity 0). Demand always slopes down, so X is never a Giffen good.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-225","question":"A factory upstream dumps waste into a river, raising treatment costs for a town downstream, and nobody compensates the town. Compared with the socially efficient level, the factory's output is:","options":["Too low, because the town pays part of its costs","Too high, because the external cost is not part of its private cost","Efficient, because the market price reflects all costs","Too high, because the factory receives a subsidy"],"answer":1,"explanation":"A negative production externality makes marginal social cost exceed marginal private cost. The firm produces where price = private MC, so output exceeds the level where price = social MC.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-226","question":"In a competitive market, demand is P = 100 − Q and the industry's marginal private cost is MPC = 20 + Q. Each unit also causes ₹10 of pollution damage. What are the market output, the socially optimal output and the Pigouvian tax that achieves it?","options":["Market 40; optimum 30; tax ₹20 per unit","Market 35; optimum 40; subsidy ₹10 per unit","Market 40; optimum 35; tax ₹10 per unit","Market 40; optimum 35; tax ₹5 per unit"],"answer":2,"explanation":"Market: 100 − Q = 20 + Q → Q = 40 (P = 60). Social MC = 30 + Q: 100 − Q = 30 + Q → Q = 35 (P = 65). A tax equal to the marginal external damage, ₹10 a unit, makes firms face social cost.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-227","question":"In the same market (demand P = 100 − Q, MPC = 20 + Q, constant external damage ₹10 per unit), what is the deadweight loss caused by the unregulated market?","options":["₹25","₹50","₹100","₹400"],"answer":0,"explanation":"The market produces 5 units too many (40 instead of 35). On each of them social MC exceeds marginal benefit; the gap rises from 0 at Q = 35 to 10 at Q = 40. DWL = ½ × 5 × 10 = ₹25.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-228","question":"Demand for a chemical is P = 120 − Q and the marginal private cost of producing it is MPC = Q. The marginal external damage rises with output: MD = 0.5Q. What Pigouvian tax per unit achieves the efficient outcome?","options":["₹30","₹24","₹12","₹60"],"answer":1,"explanation":"Social MC = Q + 0.5Q = 1.5Q. Efficient output: 120 − Q = 1.5Q → Q = 48. The tax must equal marginal damage at the efficient output: 0.5 × 48 = ₹24. ₹30 is marginal damage at the unregulated output (Q = 60).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-229","question":"For a vaccine, private marginal benefit is P = 50 − Q and marginal cost is MC = 10 + Q (Q in lakh doses, ₹). Each dose gives others an external benefit of ₹10 by reducing infection. What per-dose subsidy achieves efficiency, and what does it cost the government?","options":["₹10 a dose; ₹200 lakh in total","₹5 a dose; ₹125 lakh in total","₹10 a dose; ₹250 lakh in total","₹20 a dose; ₹500 lakh in total"],"answer":2,"explanation":"Market: 50 − Q = 10 + Q → Q = 20. Social MB = 60 − Q: 60 − Q = 10 + Q → Q = 25. A subsidy equal to the external benefit (₹10) raises output to 25 lakh doses, costing 25 × 10 = ₹250 lakh. ₹200 lakh uses the pre-subsidy quantity.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-230","question":"According to the Coase theorem, an externality can be resolved efficiently through private bargaining when:","options":["The government imposes a Pigouvian tax","The polluter always holds the property rights","Many parties are affected, so bargaining is competitive","Property rights are clearly defined and transaction costs are low, whichever party holds the rights"],"answer":3,"explanation":"With well-defined rights and cheap bargaining, the parties trade until the efficient outcome is reached; who holds the rights affects only who pays whom. With many parties, bargaining costs and free-riding usually defeat it.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-231","question":"Which statements about pure public goods are correct? I. The market demand curve is found by adding individual marginal benefits vertically. II. Provision is efficient where the sum of marginal benefits equals marginal cost. III. Private markets tend to over-provide them. IV. One person's use does not reduce the amount available to others.","options":["I, II and IV only","I and II only","II, III and IV only","I, II, III and IV"],"answer":0,"explanation":"Everyone consumes the same quantity, so willingness to pay is summed vertically (I) and set equal to MC (II); consumption is non-rival (IV). Because people can free-ride, markets under-provide public goods, so III is false.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-232","question":"Three residents share a park. Their marginal benefits (₹ lakh per hectare) are MB₁ = 50 − Q, MB₂ = 40 − Q and MB₃ = 30 − Q, and a hectare costs ₹60 lakh. What is the efficient park size, and how much would be provided if each resident decided alone?","options":["40 hectares efficiently; 10 if each decides alone","20 hectares efficiently; none if each decides alone","20 hectares efficiently; 10 if each decides alone","30 hectares efficiently; none if each decides alone"],"answer":1,"explanation":"For a public good add MBs vertically: ΣMB = 120 − 3Q = 60 → Q = 20 (each MB is still positive: 30, 20, 10). Alone, even the keenest resident values the first hectare at only ₹50 lakh < ₹60 lakh, so nobody buys any: the free-rider problem in extreme form.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-233","question":"A town relies on voluntary contributions to fund street lighting. Which outcome is most likely, and why?","options":["Over-provision, because everyone benefits","The efficient amount, because residents' contributions reveal their true valuations","Under-provision, because each resident can enjoy the lighting without paying and hopes others will contribute","No effect, because street lighting is a private good"],"answer":2,"explanation":"Street lighting is non-excludable and non-rival. Each resident's best response is to contribute little and free-ride, so total contributions understate the sum of marginal benefits and lighting is under-supplied. Tax-financed provision is the usual remedy.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-234","question":"Match each good with its category. (p) A subscription music service, (q) Fish in the open sea, (r) National defence, (s) A sandwich. Categories: (1) Private good (rival, excludable); (2) Club good (non-rival, excludable); (3) Common resource (rival, non-excludable); (4) Public good (non-rival, non-excludable).","options":["p-1, q-3, r-4, s-2","p-2, q-4, r-3, s-1","p-3, q-2, r-4, s-1","p-2, q-3, r-4, s-1"],"answer":3,"explanation":"A streaming service can exclude non-payers but one more listener costs others nothing (club good). Open-sea fish are rival but hard to exclude (common resource, prone to over-use). Defence is non-rival and non-excludable. A sandwich is rival and excludable.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-235","question":"A monopolist faces demand P = 120 − Q and has constant marginal cost ₹30. Compare its profit under a single price with its profit under perfect (first-degree) price discrimination.","options":["Single price: ₹2,025; perfect discrimination: ₹2,025","Single price: ₹4,050; perfect discrimination: ₹8,100","Single price: ₹2,700; perfect discrimination: ₹4,050","Single price: ₹2,025; perfect discrimination: ₹4,050"],"answer":3,"explanation":"Single price: MR = 120 − 2Q = 30 → Q = 45, P = 75, profit = 45 × 45 = ₹2,025. Perfect discrimination: sell to everyone with WTP ≥ MC, so Q = 90 and profit equals the whole surplus triangle ½ × 90 × 90 = ₹4,050. Output becomes efficient but consumers keep no surplus.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-236","question":"An airline has 100 business and 100 leisure travellers per flight. Business travellers value a flexible ticket at ₹12,000 and a restricted (non-refundable) ticket at ₹7,000; leisure travellers value them at ₹6,000 and ₹5,000. Marginal cost is ₹2,000 a seat and the airline cannot tell the types apart. With a restricted fare of ₹5,000, what is the highest flexible fare that business travellers will still choose, and what is the profit?","options":["₹10,000; profit ₹11,00,000","₹12,000; profit ₹13,00,000","₹10,000; profit ₹8,00,000","₹7,000; profit ₹8,00,000"],"answer":0,"explanation":"Business travellers get 7,000 − 5,000 = ₹2,000 of surplus from the restricted ticket, so the flexible fare must leave them at least that: P ≤ 12,000 − 2,000 = ₹10,000. Profit = 100 × 8,000 + 100 × 3,000 = ₹11,00,000. At ₹12,000 they would switch to the restricted ticket. Selling only flexible at ₹12,000 earns ₹10,00,000; one fare of ₹6,000 earns ₹8,00,000.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-237","question":"A firm sells the same product to students and to professionals and can prevent resale. Marginal cost is ₹40. Demand elasticity is −4 for students and −2 for professionals. What profit-maximising prices follow from the inverse-elasticity (markup) rule?","options":["Students ₹80; professionals ₹53.33","Students ₹53.33; professionals ₹80","Students ₹50; professionals ₹60","Both ₹60"],"answer":1,"explanation":"P = MC/(1 − 1/|e|). Students: 40/(1 − 1/4) = 40/0.75 = ₹53.33. Professionals: 40/(1 − 1/2) = ₹80. The less elastic group pays the higher price.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-238","question":"A cinema charges lower ticket prices to students who show an ID card. This is an example of:","options":["First-degree price discrimination","Perfect competition","Third-degree price discrimination","Predatory pricing"],"answer":2,"explanation":"The cinema splits customers into identifiable groups with different demand elasticities and charges each group a different price: third-degree discrimination. First-degree would charge every individual their maximum willingness to pay.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-239","question":"An oligopolist sells 40 units at ₹50. If it raises its price, rivals do not follow and its demand is P = 70 − 0.5Q; if it cuts its price, rivals follow and demand is P = 90 − Q. Within what range can its marginal cost at 40 units move without changing its profit-maximising price?","options":["Between ₹30 and ₹50","Between ₹20 and ₹50","Between ₹10 and ₹50","Between ₹10 and ₹30"],"answer":3,"explanation":"MR on the upper (elastic) segment = 70 − Q = 30 at Q = 40; MR on the lower segment = 90 − 2Q = 10 at Q = 40. MR jumps down from ₹30 to ₹10 at the kink, so any MC in that gap keeps the profit-maximising output at 40 and the price at ₹50: price rigidity.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-240","question":"Assertion (A): In the kinked demand model of oligopoly, prices tend to remain stable even when costs change moderately. Reason (R): Rivals are assumed to match price cuts but not price increases, which creates a gap in the firm's marginal revenue curve.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. The asymmetric reactions make demand elastic above the current price and inelastic below it; the resulting break in MR means modest shifts in MC leave the best price unchanged.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-241","question":"Three identical firms compete by choosing quantities (Cournot). Market demand is P = 100 − Q and each firm's marginal cost is ₹10. What are each firm's output and the market price?","options":["22.5 units each; price ₹32.50","30 units each; price ₹10","15 units each; price ₹55","30 units each; price ₹40"],"answer":0,"explanation":"With n identical Cournot firms, each produces (a − c)/[b(n + 1)] = 90/4 = 22.5. Total = 67.5, so P = 100 − 67.5 = ₹32.50. As n grows, price falls towards MC. 30 each is the duopoly answer.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-242","question":"Two firms face demand P = 100 − Q and each has MC = ₹10. If they collude and split the monopoly output equally, each earns ₹1,012.50. If firm 1 secretly cheats while firm 2 keeps to its quota, what is firm 1's best output and profit?","options":["30 units; ₹900","33.75 units; about ₹1,139","45 units; ₹1,012.50","33.75 units; about ₹1,477"],"answer":1,"explanation":"Monopoly output is 45 (22.5 each, P = 55). Firm 1's best reply to q₂ = 22.5: maximise (100 − q₁ − 22.5 − 10)q₁ → q₁ = 67.5/2 = 33.75. Price = 100 − 56.25 = ₹43.75, profit = 33.75 × 33.75 ≈ ₹1,139 > ₹1,012.50. This gain from cheating is why cartels are unstable; Cournot gives 30 units and ₹900 each.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-243","question":"Why do electricity suppliers often charge higher tariffs during evening peak hours than at night?","options":["Electricity costs nothing to produce at night","Night users have more elastic demand, so it is predatory pricing","Peak demand determines how much generating capacity must be built, so peak users should bear the capacity cost","Regulators forbid uniform tariffs"],"answer":2,"explanation":"Peak-load pricing charges peak users the capacity cost plus operating cost, while off-peak users pay mainly operating cost. It shifts some demand away from the peak and reduces the capacity needed.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-244","question":"Two plants each emit 100 tonnes and total emissions must fall by 80 tonnes. Plant 1's marginal abatement cost is MAC₁ = 2a₁ and plant 2's is MAC₂ = 6a₂ (₹ thousand per tonne abated). If the cut is achieved by tradable permits rather than an equal 40-tonne cut each, what is the permit price and the saving in total abatement cost?","options":["Permit price ₹80 thousand; saving ₹1,600 thousand","Permit price ₹120 thousand; saving ₹6,400 thousand","Permit price ₹160 thousand; no saving","Permit price ₹120 thousand; saving ₹1,600 thousand"],"answer":3,"explanation":"Efficient abatement equalises MACs: 2a₁ = 6a₂ and a₁ + a₂ = 80 → a₁ = 60, a₂ = 20; permit price = 2 × 60 = 120. Total cost = a₁² + 3a₂² = 3,600 + 1,200 = 4,800. Equal cuts cost 40² + 3 × 40² = 1,600 + 4,800 = 6,400. Saving = 1,600: the low-cost plant does more of the abating.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-245","question":"On a city road, demand for trips is P = 200 − 2Q, each driver's own cost is MPC = 20 + Q, and each extra car imposes a congestion cost of Q on other drivers (₹, Q in hundreds of trips). What toll per trip achieves the efficient traffic level?","options":["₹45","₹60","₹30","₹90"],"answer":0,"explanation":"Unpriced: 200 − 2Q = 20 + Q → Q = 60. Social MC = 20 + 2Q: 200 − 2Q = 20 + 2Q → Q = 45. The toll equals the external cost at the efficient level, Q = ₹45. ₹60 is the external cost at the unpriced traffic level.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-246","question":"A beekeeper's bees pollinate a neighbouring apple orchard, raising its yield, but the orchard owner pays nothing for this. This is an example of:","options":["A negative externality","A positive externality","A public bad","Price discrimination"],"answer":1,"explanation":"The beekeeper's activity benefits a third party who does not pay, so the beekeeper keeps fewer hives than is socially efficient.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-247","question":"A firm is the only seller at home, where demand is P = 200 − 2Q, but can export any amount at a world price of ₹80. Its marginal cost depends on total output: MC = 20 + Q. What are its home price and export quantity?","options":["Home price ₹80; exports 30 units","Home price ₹110; exports 0 units","Home price ₹140; exports 30 units","Home price ₹140; exports 60 units"],"answer":2,"explanation":"Each extra unit can earn ₹80 abroad, so it produces until MC = 80 → total Q = 60, and sells at home until home MR = 80: 200 − 4Q_h = 80 → Q_h = 30, home price = 200 − 60 = ₹140. Exports = 60 − 30 = 30. It charges more at home, where its demand is less elastic, than in the competitive world market.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-248","question":"According to the 'impossible trinity' (trilemma) of international economics, a country cannot simultaneously have all three of:","options":["Low inflation, low unemployment and a budget surplus","Free trade, a floating exchange rate and capital controls","A current account surplus, a fiscal deficit and a floating rate","A fixed exchange rate, free capital movement and an independent monetary policy"],"answer":3,"explanation":"With a fixed rate and open capital flows, interest rates must track the anchor country's or capital will flow in or out and break the peg. A country can pick any two of the three.","difficulty":"easy","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-249","question":"Why does the IS curve slope downward in the IS–LM model?","options":["A higher income raises money demand and pushes up the interest rate","A lower interest rate raises investment spending, which raises equilibrium income through the multiplier","A lower interest rate reduces saving, so income falls","Higher prices reduce real money balances"],"answer":1,"explanation":"The IS curve shows goods-market equilibrium. Lower interest rates stimulate interest-sensitive spending, especially investment, so equilibrium output is higher. The upward-sloping LM curve reflects money-market equilibrium instead.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-250","question":"In a closed-economy IS–LM model with an upward-sloping LM curve, the government raises spending. Which statements are correct? I. Equilibrium income rises. II. The interest rate rises. III. Private investment is partly crowded out. IV. Income rises by the full simple Keynesian multiplier.","options":["I and IV only","I, II, III and IV","I, II and III only","II and III only"],"answer":2,"explanation":"The IS curve shifts right; higher income raises money demand and, with money supply fixed, the interest rate. Higher rates reduce investment, so income rises by less than the simple multiplier. IV holds only if LM is horizontal.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-251","question":"An economy has C = 100 + 0.8(Y − T), T = 100, I = 300 − 20r and G = 200. Real money supply is 1,000 and money demand is L = 0.5Y − 50r (r in per cent). What are the equilibrium income and interest rate?","options":["Y = 2,600; r = 0%","Y = 2,500; r = 5%","Y = 2,000; r = 0%","Y = 2,300; r = 3%"],"answer":3,"explanation":"IS: Y = 100 + 0.8Y − 80 + 300 − 20r + 200 → 0.2Y = 520 − 20r → Y = 2,600 − 100r. LM: 1,000 = 0.5Y − 50r → Y = 2,000 + 100r. Solving: 200r = 600 → r = 3, Y = 2,300.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-252","question":"In the same IS–LM economy (IS: Y = 2,600 − 100r; LM: Y = 2,000 + 100r; MPC 0.8), government spending rises by 40. By how much does income rise, and how much of the simple-multiplier effect is crowded out?","options":["Income rises by 100; 100 is crowded out","Income rises by 200; nothing is crowded out","Income rises by 40; 160 is crowded out","Income rises by 100; 60 is crowded out"],"answer":0,"explanation":"The simple multiplier is 1/(1 − 0.8) = 5, so IS shifts right by 200: Y = 2,800 − 100r. With LM: 2,800 − 100r = 2,000 + 100r → r = 4, Y = 2,400. Income rises by 100, half the 200 the simple multiplier implies; the rise in r from 3% to 4% cuts investment by 20, which with the multiplier removes 100.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-253","question":"An economy is in a liquidity trap, so the LM curve is flat at a very low interest rate. Which policy is likely to be more effective at raising output, and why?","options":["Monetary expansion, because extra money lowers interest rates further","Fiscal expansion, because it raises demand without pushing up interest rates","Monetary expansion, because fiscal policy is fully crowded out","Neither, because output is fixed at full employment"],"answer":1,"explanation":"In a liquidity trap people hold any extra money rather than buy bonds, so more money cannot lower rates further and monetary policy is weak. A rightward IS shift raises income with little rise in interest rates, so there is little crowding out.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-254","question":"In the Mundell–Fleming model of a small open economy with perfect capital mobility and a FLOATING exchange rate, what is the effect of a fiscal expansion on output?","options":["Large: there is no crowding out in an open economy","Large: the currency depreciates and boosts net exports","Little or none: upward pressure on interest rates attracts capital, the currency appreciates and net exports fall","Output falls by more than the increase in spending"],"answer":2,"explanation":"Domestic rates cannot stay above world rates, so capital inflows appreciate the currency until net exports fall by as much as government spending rose. Under floating rates monetary policy is the effective tool; under a fixed rate fiscal policy is.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-255","question":"Assertion (A): Under a fixed exchange rate with perfect capital mobility, a central bank cannot use monetary policy to raise output. Reason (R): To defend the peg it must sell foreign currency when it expands the money supply, which drains the extra domestic money back out of the economy.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true and R explains A. Expanding money pushes interest rates down, capital flows out and the currency weakens; to hold the peg the central bank sells foreign exchange and buys back domestic currency, reversing the expansion.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-256","question":"Under a currency board arrangement, the monetary authority:","options":["Lets the exchange rate float freely and targets inflation","Adjusts the exchange rate daily by a crawling peg formula","Prints money to finance government deficits whenever needed","Issues domestic currency only when fully backed by reserves of an anchor currency at a fixed rate"],"answer":3,"explanation":"A currency board commits to convert domestic currency into the anchor currency at a fixed rate and holds full reserve backing. This gives credibility but gives up independent monetary policy and the lender-of-last-resort role.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-257","question":"To slow a rapid depreciation of the rupee, the central bank sells US dollars from its reserves. If it wants to stop this from tightening domestic liquidity, which accompanying action sterilises the intervention?","options":["Buying government securities through open-market operations","Selling government securities through open-market operations","Raising the cash reserve ratio","Selling more dollars in the forward market"],"answer":0,"explanation":"Selling dollars takes rupees out of the banking system, shrinking reserve money. Buying government securities injects the same rupees back, keeping domestic liquidity unchanged. Selling securities or raising CRR would tighten it further.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-258","question":"A subscription app spends ₹30 lakh on marketing and gains 6,000 new subscribers. Each subscriber pays ₹300 a month at a 40% gross margin, and 4% of subscribers cancel each month. Ignoring discounting, what are the LTV-to-CAC ratio and the CAC payback period?","options":["LTV/CAC = 15; payback ≈ 1.7 months","LTV/CAC = 6; payback ≈ 4.2 months","LTV/CAC = 6; payback ≈ 1.7 months","LTV/CAC = 2.4; payback ≈ 4.2 months"],"answer":1,"explanation":"CAC = 30,00,000/6,000 = ₹500. Monthly gross margin = 0.4 × 300 = ₹120; expected life = 1/0.04 = 25 months; LTV = 120 × 25 = ₹3,000. LTV/CAC = 6. Payback = 500/120 ≈ 4.2 months. Using revenue instead of margin gives LTV/CAC of 15 and payback of 1.7 months.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-259","question":"A subscriber earns a company ₹120 of margin at the end of month 1 and, after that, stays each further month with probability 96% (paying ₹120 at the end of every month retained). The monthly discount rate is 1%. What is the subscriber's discounted lifetime value?","options":["₹3,000","₹2,880","₹2,400","₹12,000"],"answer":2,"explanation":"LTV = Σ 120 × 0.96^(t−1)/1.01^t = 120/(1.01 − 0.96) = 120/0.05 = ₹2,400. Without discounting it would be 120/0.04 = ₹3,000; ₹12,000 discounts at 1% but ignores churn.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-260","question":"The same app (price ₹300 a month, variable cost ₹180, monthly churn 4%) considers two moves: (a) better onboarding that cuts churn to 3%, or (b) a 10% price rise, which its tests show would raise churn to 4.5%. Ignoring discounting, which raises customer lifetime value more?","options":["(b): LTV rises to ₹3,750, against ₹4,000 for (a)","(b): LTV rises to about ₹3,333, against ₹3,000 for (a)","Both raise LTV to ₹4,000","(a): LTV rises to ₹4,000, against about ₹3,333 for (b)"],"answer":3,"explanation":"Current LTV = 120/0.04 = ₹3,000. (a) 120/0.03 = ₹4,000. (b) Margin becomes 330 − 180 = ₹150, but churn rises to 4.5%: 150/0.045 ≈ ₹3,333. Forgetting the churn effect of the price rise gives ₹3,750, still below (a).","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-261","question":"Estimate the annual helmet market in a city of 2 crore people: there is one two-wheeler for every 5 people, each two-wheeler has 1.5 regular riders on average, every rider needs a helmet, helmets are replaced every 3 years and the average price is ₹1,500.","options":["About ₹300 crore a year","About ₹900 crore a year","About ₹200 crore a year","About ₹600 crore a year"],"answer":0,"explanation":"Two-wheelers = 2 crore/5 = 40 lakh; riders = 40 lakh × 1.5 = 60 lakh; helmets bought a year = 60 lakh/3 = 20 lakh; value = 20 lakh × ₹1,500 = ₹300 crore. ₹900 crore forgets the 3-year replacement cycle; ₹200 crore ignores pillion riders.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-262","question":"In market sizing, how do TAM, SAM and SOM differ?","options":["TAM is current sales; SAM is future sales; SOM is the profit pool","TAM is total demand for the category; SAM is the part the firm's offering and channels can serve; SOM is the share it can realistically win","TAM, SAM and SOM are the same market measured in units, value and volume","SOM is always larger than SAM because it includes adjacent markets"],"answer":1,"explanation":"The three are nested: TAM ≥ SAM ≥ SOM. A start-up pitching a large TAM must still show a credible path to its obtainable share given competition, reach and capacity.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-263","question":"Estimate annual public-charging revenue in a city with 10 lakh cars, of which 8% are electric. Each EV drives 40 km a day using 0.15 kWh per km, 30% of charging energy comes from public stations, and public charging costs ₹18 per kWh.","options":["About ₹315 crore a year","About ₹8 crore a year","About ₹95 crore a year","About ₹28 crore a year"],"answer":2,"explanation":"EVs = 80,000. Energy per EV per day = 40 × 0.15 = 6 kWh, of which 1.8 kWh is public. Daily public energy = 80,000 × 1.8 = 1,44,000 kWh → × ₹18 = ₹25.92 lakh a day → × 365 ≈ ₹94.6 crore. Counting all charging as public gives about ₹315 crore; using one month gives about ₹8 crore; applying the 30% public share twice gives about ₹28 crore.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-264","question":"A start-up is launching a ride-sharing app in a new city. Which combination of conditions most strongly favours penetration pricing rather than price skimming?","options":["A patented product with no close substitutes and status-conscious buyers","Small production capacity and a few customers with very high willingness to pay","High switching costs that lock early buyers in regardless of price","Strong network effects, price-sensitive customers and costs that fall sharply with scale"],"answer":3,"explanation":"Low launch prices build volume fast; that matters when each new user makes the service more valuable to others, when demand is elastic and when unit costs fall with scale. Skimming suits differentiated products with inelastic early adopters and limited capacity.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-265","question":"A cinema sells popcorn in three sizes: small ₹150, medium ₹280 and large ₹300. Few people buy medium, but large sales jumped after medium was introduced. What pricing tactic is this?","options":["A decoy: the medium size makes the large look like a bargain","Cost-plus pricing for each size","Predatory pricing against nearby food stalls","Peak-load pricing"],"answer":0,"explanation":"The medium option is 'asymmetrically dominated': for only ₹20 more the large offers much more, so customers anchor on the comparison and trade up. The decoy earns its keep by shifting choices, not by its own sales.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-266","question":"A product sells at ₹100 with a variable cost of ₹75. The firm considers raising its price by 8%. Its price elasticity of demand is −2.5 over this range. Which statement is correct?","options":["Volume can fall by up to 8% before contribution drops; with a 20% fall, contribution falls","Volume can fall by up to 24.2% before contribution drops; with a 20% fall, contribution rises by 5.6%","Volume can fall by up to 24.2% before contribution drops; with a 20% fall, contribution falls by 12%","Any price rise reduces revenue when demand is elastic, so it must reduce contribution"],"answer":1,"explanation":"Contribution per unit rises from ₹25 to ₹33. Break-even volume = 25/33 = 75.8% of current, so volume may fall by 24.2%. Elasticity −2.5 implies a 20% fall: new contribution = 33 × 0.8 = 26.4 per original unit, versus 25: +5.6%. Revenue does fall (1.08 × 0.8 = 0.864), but with thin margins contribution can still rise.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-267","question":"A retailer buys an item for ₹80 and wants a 20% profit margin on the selling price. What price should it charge, and what markup on cost does that represent?","options":["₹96; a 20% markup on cost","₹100; a 20% markup on cost","₹100; a 25% markup on cost","₹96; a 25% markup on cost"],"answer":2,"explanation":"Margin on price: P = cost/(1 − margin) = 80/0.8 = ₹100. Markup on cost = 20/80 = 25%. Adding 20% to cost (₹96) gives only a 16.7% margin.","difficulty":"moderate","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-268","question":"A freemium app has 10 lakh monthly users. Each free user costs ₹2 a month to serve; a paid user pays ₹200 a month and costs ₹10 to serve. Fixed costs are ₹30 lakh a month. What share of users must convert to paid for the app to break even?","options":["About 1.58%","About 2.63%","About 2.50%","About 2.60%"],"answer":3,"explanation":"Let c be the conversion share. Profit = 10,00,000 × [c × 190 − (1 − c) × 2] − 30,00,000 = 0 → 190c − 2 + 2c = 3 → c = 5/192 ≈ 2.60%. Ignoring the cost of free users gives 3/190 ≈ 1.58%; ignoring that converted users stop being free users gives 5/190 ≈ 2.63%.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-269","question":"For a food-delivery platform, the average order is ₹400. It earns a 22% commission from the restaurant and a ₹30 delivery fee from the customer; it pays the rider ₹55, funds discounts of ₹25 and pays a payment-gateway fee of 2% of the order value. What is its contribution per order?","options":["₹30","₹38","₹55","₹0"],"answer":0,"explanation":"Revenue = 0.22 × 400 + 30 = ₹118. Variable costs = 55 + 25 + 0.02 × 400 = ₹88. Contribution = ₹30. Forgetting the gateway fee gives ₹38, forgetting discounts gives ₹55 and leaving out the customer delivery fee gives ₹0, so every line item matters.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-270","question":"Over a year the rupee depreciates 5% against the US dollar (₹ per $ rises 5%), Indian inflation is 6% and US inflation is 2%. What happens to India's real exchange rate against the US?","options":["The rupee depreciates in real terms by 5%, since inflation does not matter","The rupee depreciates in real terms by about 1.04%, a small gain in competitiveness","The rupee appreciates in real terms by about 3%","The rupee depreciates in real terms by about 9%"],"answer":1,"explanation":"Real exchange rate (US goods in terms of Indian goods) = E × P_US/P_India. Its change = 1.05 × 1.02/1.06 − 1 = 1.04%. Most of the nominal depreciation is offset by India's higher inflation, so competitiveness improves only slightly. 9% adds the inflation gap instead of subtracting it.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-271","question":"In the IS–LM economy with IS: Y = 2,600 − 100r and money demand L = 0.5Y − 50r, the real money supply rises from 1,000 to 1,100. What are the new equilibrium income and interest rate?","options":["Y = 2,500; r = 1%","Y = 2,300; r = 3%","Y = 2,400; r = 2%","Y = 2,200; r = 4%"],"answer":2,"explanation":"New LM: 1,100 = 0.5Y − 50r → Y = 2,200 + 100r. With IS: 2,600 − 100r = 2,200 + 100r → r = 2, Y = 2,400. The extra money lowers the interest rate from 3% to 2%, which raises investment and income by 100.","difficulty":"very-hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-272","question":"Under a freely floating exchange rate, how is a balance-of-payments deficit (more demand for foreign currency than supply) normally corrected?","options":["The central bank must sell reserves until the deficit disappears","Domestic money supply automatically rises","The government must impose import quotas","The domestic currency depreciates, making exports cheaper and imports dearer until demand and supply of foreign exchange balance"],"answer":3,"explanation":"With a float the exchange rate is the adjusting price. Depreciation raises export competitiveness and cuts imports (if the Marshall–Lerner condition holds), so no reserve loss is needed, unlike under a fixed rate.","difficulty":"hard","source":"Big 4 advisory · Consulting · MBA placement pattern"},
  {"id":"mgmt-business-economics-273","question":"Demand is Qd = 200 − 4P + 0.5Y and supply is Qs = 2P + 20, where Y is income. If income rises from 400 to 480, by how much do the equilibrium price and quantity change?","options":["Price rises by 6.67, quantity by 13.33","Price rises by 10.00, quantity by 40.00","Price rises by 6.67, quantity by 40.00","Price rises by 20.00, quantity by 13.33"],"answer":0,"explanation":"Demand shifts right by 0.5 × 80 = 40 units. Equating: 200 − 4P + 0.5Y = 2P + 20 → P = (180 + 0.5Y)/6, so P rises by 40/6 = 6.67 and Q = 2P + 20 rises by 13.33; the full 40-unit shift is split between price and quantity.","difficulty":"hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-274","question":"Demand is Qd = 150 − 3P and supply is Qs = 2P − 10. At equilibrium, what are the price elasticities of demand and supply, and what share of a small per-unit tax falls on buyers?","options":["Ed = −1.78, Es = 1.19; buyers bear 60%","Ed = −1.78, Es = 1.19; buyers bear 40%","Ed = −3.00, Es = 2.00; buyers bear 40%","Ed = −1.78, Es = 1.19; buyers bear 50%"],"answer":1,"explanation":"Equilibrium: P = 32, Q = 54. Ed = −3 × 32/54 = −1.78; Es = 2 × 32/54 = 1.19. Buyers' share = Es/(Es + |Ed|) = 40%: the less elastic side (here supply) bears more.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-275","question":"Demand is Qd = 100 − Pd and supply is Qs = Ps, where Pd is the price buyers pay and Ps what sellers receive. A 25% ad valorem tax is levied on the seller's price (Pd = 1.25 Ps). What are Pd, Ps and the tax revenue?","options":["Pd = 62.50, Ps = 37.50, revenue 937.50","Pd = 55.56, Ps = 44.44, revenue 617.28","Pd = 55.56, Ps = 44.44, revenue 493.83","Pd = 57.14, Ps = 42.86, revenue 612.24"],"answer":2,"explanation":"100 − 1.25Ps = Ps → Ps = 100/2.25 = 44.44, Pd = 55.56, Q = 44.44. Revenue = (Pd − Ps) × Q = 11.11 × 44.44 = 493.83.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-276","question":"In a market with linear demand and supply, a per-unit tax of ₹5 creates a deadweight loss of ₹15 crore. If the tax is raised to ₹10 (and the market still trades), what is the new deadweight loss?","options":["₹30 crore","₹45 crore","₹15 crore","₹60 crore"],"answer":3,"explanation":"DWL = ½ × tax × fall in quantity, and the fall in quantity is itself proportional to the tax, so DWL rises with the SQUARE of the tax: 15 × 2² = ₹60 crore.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-277","question":"Demand is Qd = 100 − 2P and supply is Qs = 3P. A per-unit tax t gives traded quantity Q = 60 − 1.2t. What tax maximises tax revenue, and what is that revenue?","options":["t = ₹25; revenue ₹750","t = ₹50; revenue ₹0","t = ₹25; revenue ₹1,500","t = ₹20; revenue ₹720"],"answer":0,"explanation":"Revenue = t × (60 − 1.2t); maximise: 60 − 2.4t = 0 → t = 25, Q = 30, revenue = ₹750. Beyond ₹25, higher rates shrink the base faster than they raise the rate (a Laffer-type effect).","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-278","question":"Two straight-line demand curves pass through the same point (P = ₹20, Q = 100). Curve A has slope −0.1 (₹ per unit) and curve B has slope −0.5. At that point:","options":["B is more elastic because its slope is larger","A is five times as elastic as B","Both have the same elasticity because they pass through the same point","A is one-fifth as elastic as B"],"answer":1,"explanation":"Elasticity = (dQ/dP) × P/Q. For A, dQ/dP = −10, so e = −2.0; for B, dQ/dP = −2, so e = −0.4. At a common point, the flatter curve is more elastic.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-279","question":"When the price of brand B rises from ₹40 to ₹50, sales of brand A rise from 200 to 240 units. Using the midpoint method, what is the cross-price elasticity, and how are the goods related?","options":["0.80; substitutes","−0.82; complements","0.82; substitutes","1.22; substitutes"],"answer":2,"explanation":"%ΔQ_A = 40/220 = 18.18%; %ΔP_B = 10/45 = 22.22%; elasticity = 0.82 > 0, so they are substitutes. Using initial values gives 0.80.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-280","question":"When monthly household income rises from ₹50,000 to ₹60,000, spending visits to restaurants rise from 10 to 14 a month. Using the midpoint method, what is the income elasticity and how is the good classified?","options":["2.00; a luxury normal good","1.83; a necessity","0.55; a necessity","1.83; a luxury (income-elastic) normal good"],"answer":3,"explanation":"%ΔQ = 4/12 = 33.3%; %ΔY = 10,000/55,000 = 18.2%; Ey = 1.83 > 1, a luxury. Using initial values gives 2.00, the same classification but the wrong number.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-281","question":"Food has an income elasticity of 0.5. If a household's income rises 20% while prices are unchanged, what happens to food's share of its budget (initially 40%)?","options":["It falls to about 36.7%","It stays at 40%","It rises to 44.0%","It falls to 20.0%"],"answer":0,"explanation":"Food spending rises 0.5 × 20% = 10% while income rises 20%: new share = 40% × 1.10/1.20 = 36.7%. Engel's law: necessities take a falling share as income grows.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-282","question":"Domestic demand is Qd = 100 − P and domestic supply Qs = P − 20. The world price is ₹40 and the country is a price-taker. A ₹10 per-unit tariff is imposed. What are imports after the tariff, tariff revenue and the deadweight loss?","options":["Imports 40; revenue ₹400; deadweight loss ₹0","Imports 20; revenue ₹200; deadweight loss ₹100","Imports 20; revenue ₹200; deadweight loss ₹50","Imports 30; revenue ₹300; deadweight loss ₹100"],"answer":1,"explanation":"At ₹40: Qd = 60, Qs = 20, imports 40. At ₹50: Qd = 50, Qs = 30, imports 20; revenue = 10 × 20 = ₹200. DWL = production triangle ½ × 10 × 10 + consumption triangle ½ × 10 × 10 = ₹100.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-283","question":"Why does a binding rent ceiling usually cause a larger housing shortage in the long run than in the short run?","options":["Demand becomes perfectly inelastic in the long run","The ceiling rises automatically with inflation","Both demand and especially supply are more elastic in the long run, as landlords stop building and maintaining rental units","Long-run supply is perfectly inelastic, so it cannot adjust"],"answer":2,"explanation":"Over time landlords convert or neglect units and builders stop adding rental supply, while more people seek the cheap housing. Greater elasticities widen the gap between quantity demanded and supplied at the fixed rent.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-284","question":"Demand is Qd = 300 − 5P and supply is Qs = 4P − 60. A ceiling of ₹30 is imposed. If the quantity supplied ends up being resold to the highest bidders, what price does it fetch in the black market?","options":["₹40","₹30","₹42","₹48"],"answer":3,"explanation":"At ₹30 only Qs = 60 units are supplied. Buyers would pay the price at which Qd = 60: 300 − 5P = 60 → P = ₹48, above the free-market ₹40 because quantity is restricted.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-285","question":"With demand Qd = 300 − 5P and supply Qs = 4P − 60, a binding price ceiling of ₹30 is imposed (no black market). What is the deadweight loss?","options":["₹360","₹720","₹200","₹400"],"answer":0,"explanation":"Free market: P = 40, Q = 100. At ₹30, Q = 60; the demand price for 60 units is ₹48 and the supply price ₹30. DWL = ½ × (48 − 30) × (100 − 60) = ₹360. Using only the ₹10 gap to the free price (₹200) understates it.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-286","question":"A wheat farmer supplies 1% of the market. Market demand elasticity is −0.5 and the supply elasticity of all other farmers is 1.0. Using e_firm = e_market/s − e_others × (1 − s)/s, what demand elasticity does the farmer face?","options":["−50","−149","−0.5","−99"],"answer":1,"explanation":"e_firm = −0.5/0.01 − 1.0 × 0.99/0.01 = −50 − 99 = −149. Even though market demand is inelastic, a single small firm faces a nearly horizontal demand curve.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-287","question":"A good's demand rises by 30 units at every price and its supply rises by 30 units at every price (parallel horizontal shifts). With linear curves, what happens?","options":["Both price and quantity rise","Quantity rises by 60 units","Quantity rises by 30 units and price is unchanged","Price falls and quantity is unchanged"],"answer":2,"explanation":"Equal horizontal shifts of both curves move the intersection straight across: equilibrium quantity rises by exactly 30 and price stays put. With unequal shifts the price effect depends on which shift is bigger.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-288","question":"In a cobweb model, demand is Qd = 100 − 2Pₜ and farmers plant on last season's price: Qs = −20 + Pₜ₋₁. Starting away from equilibrium, what happens to prices over time?","options":["They oscillate with growing swings","They move smoothly to ₹40 without oscillating","They converge to ₹60","They oscillate and converge to ₹40, because supply is less price-responsive than demand"],"answer":3,"explanation":"Equilibrium: 100 − 2P = −20 + P → P = 40. Each period's price deviation is −(1/2) times the last (supply slope 1 ÷ demand slope 2), so the swings shrink and the path converges.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-289","question":"Demand for good X is Qx = 100 − 2Px + 0.5Py + 0.01M. At Px = ₹10, Py = ₹20 and income M = ₹2,000, what are the cross-price and income elasticities of X?","options":["Cross-price 0.091; income 0.182","Cross-price 0.500; income 0.010","Cross-price 0.182; income 0.091","Cross-price 0.100; income 0.200"],"answer":0,"explanation":"Qx = 110. Cross-price = 0.5 × 20/110 = 0.091 (substitutes); income = 0.01 × 2,000/110 = 0.182 (normal necessity). The coefficients are slopes, not elasticities.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-290","question":"Inverse demand is P = 50 − 0.5Q. What is the point price elasticity of demand at Q = 40, and is marginal revenue positive there?","options":["−0.67; no, MR is negative","−1.50; yes, MR = ₹10","−1.50; no, MR = −₹10","−0.50; yes, MR = ₹30"],"answer":1,"explanation":"At Q = 40, P = 30; dQ/dP = −2, so e = −2 × 30/40 = −1.5 (elastic). MR = 50 − Q = ₹10 > 0, consistent with elastic demand.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-291","question":"Demand is Qd = 120 − 3P and supply is Qs = 2P. A rise in input costs shifts supply UP by ₹6 at every quantity (Qs = 2(P − 6)). By how much does the market price rise?","options":["₹6.00","₹3.60","₹2.40","₹12.00"],"answer":2,"explanation":"Old: 120 − 3P = 2P → P = 24. New: 120 − 3P = 2P − 12 → P = 26.40. Price rises ₹2.40, i.e. 40% of the cost increase (= Es-type share 2/(2 + 3) on the buyers' side).","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-292","question":"Demand for rice is price-inelastic. A bumper harvest raises the quantity farmers bring to market. What is the most likely result for farmers as a group?","options":["Total farm income rises because they sell more","Prices are unaffected because demand is inelastic","Income is unchanged because the effects cancel","Prices fall proportionately more than quantity rises, so total farm income falls"],"answer":3,"explanation":"With inelastic demand, a large price cut is needed to sell the extra output, and the percentage price fall exceeds the percentage quantity rise, cutting total revenue (the 'paradox of plenty').","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-293","question":"Over several years, weather shocks shifted wheat supply while demand stayed stable. A researcher plots the observed price–quantity pairs and fits a line. What does that line estimate?","options":["The demand curve, because supply shifts trace out points along a stable demand curve","The supply curve, because the shocks were to supply","Neither curve; it is meaningless","The average of demand and supply slopes"],"answer":0,"explanation":"If only supply shifts, each equilibrium lies on the same demand curve, so the fitted line identifies demand. This is the logic behind using supply shifters as instruments.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-294","question":"A product's price elasticity is −0.8 and its income elasticity 1.5. Next year incomes are expected to rise 6% and the firm plans a 4% price rise. Approximately how will its sales volume change?","options":["+12.2%","+5.8%","−3.2%","+9.0%"],"answer":1,"explanation":"%ΔQ ≈ Ey × %ΔY + Ed × %ΔP = 1.5 × 6 + (−0.8) × 4 = 9.0 − 3.2 = +5.8%.","difficulty":"very-hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-295","question":"Assertion (A): A ₹10 per-unit tax collected from buyers has the same effect on prices paid, prices received and quantity as a ₹10 tax collected from sellers. Reason (R): The economic incidence of a tax depends on the elasticities of demand and supply, not on who remits it.","options":["Both are true, but R does not explain A","A is false, because sellers always bear a tax collected from them","Both A and R are true, and R explains A","A is true, R is false"],"answer":2,"explanation":"Either way a ₹10 wedge opens between the price buyers pay and sellers receive; where the wedge sits depends only on the relative elasticities.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-296","question":"Labour demand is Ld = 1,000 − 20w and labour supply Ls = 30w − 250 (w in ₹ per hour). A minimum wage of ₹30 is set. How many workers are unemployed, and how many fewer are employed than without the floor?","options":["150 unemployed; 100 fewer employed","250 unemployed; 250 fewer employed","100 unemployed; 150 fewer employed","250 unemployed; 100 fewer employed"],"answer":3,"explanation":"Equilibrium: 1,000 − 20w = 30w − 250 → w = 25, L = 500. At ₹30: Ld = 400, Ls = 650, unemployment = 250; employment falls 500 − 400 = 100. Unemployment exceeds the job loss because more people now want to work.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-297","question":"Which goods can have an upward-sloping demand curve over some range, and why?","options":["Giffen goods (strong inferior-good income effect) and Veblen goods (higher price raises status value)","All normal goods, when income rises","Complements, because their prices move together","Necessities, because demand is inelastic"],"answer":0,"explanation":"A Giffen good's income effect outweighs the substitution effect; a Veblen good is valued partly for its high price. Inelastic or normal goods still have downward-sloping demand.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-298","question":"A sudden permanent rise in demand for cement hits a market where plants take three years to build. Compared with the short run, the long-run outcome is most likely:","options":["A larger price increase and a smaller quantity increase","A smaller price increase and a larger quantity increase","The same price and quantity, since demand shifted only once","A fall in price below the original level, always"],"answer":1,"explanation":"Supply is more elastic in the long run as new capacity enters, so the initial price spike is partly reversed while output expands further.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-299","question":"A metro cuts fares from ₹40 to ₹30 and daily ridership rises from 2 lakh to 2.5 lakh. Using the midpoint method, what is the price elasticity, and what happened to fare revenue?","options":["−1.00; revenue was unchanged","−0.78; revenue rose","−0.78; revenue fell from ₹80 lakh to ₹75 lakh","−1.29; revenue fell"],"answer":2,"explanation":"%ΔQ = 0.5/2.25 = 22.2%; %ΔP = 10/35 = 28.6%; Ed = −0.78 (inelastic). Revenue: 40 × 2 = ₹80 lakh vs 30 × 2.5 = ₹75 lakh, consistent with inelastic demand.","difficulty":"very-hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-300","question":"In a small open economy, the supply of steel is perfectly elastic at the world price. If the government imposes a ₹1,000 per-tonne tax on steel consumption, who bears it?","options":["Sellers bear all of it","It is split equally","Nobody, because quantity adjusts instead","Buyers bear all of it; the price paid rises by ₹1,000"],"answer":3,"explanation":"With perfectly elastic supply, sellers will not accept any lower net price, so the entire wedge shows up in the buyers' price. Quantity falls along the demand curve.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-301","question":"According to Marshall's rules of derived demand, the demand for a type of skilled labour is MORE elastic when:","options":["Labour costs are a large share of total cost and the final product's demand is elastic","Labour is hard to substitute with machines","Labour is a tiny share of total cost","The demand for the final product is inelastic"],"answer":0,"explanation":"Derived demand is more elastic when the input is easily substituted, is a big share of costs, other inputs are elastically supplied, and the final good's demand is elastic.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-302","question":"Demand is Qd = 90 − P and supply is Qs = 2P. The government pays sellers a subsidy of ₹6 per unit. What price do buyers pay, what do sellers receive including the subsidy, and what does the subsidy cost?","options":["Buyers ₹24, sellers ₹30, cost ₹360","Buyers ₹26, sellers ₹32, cost ₹384","Buyers ₹26, sellers ₹32, cost ₹360","Buyers ₹28, sellers ₹34, cost ₹372"],"answer":1,"explanation":"90 − Pb = 2(Pb + 6) → Pb = 26, Ps = 32, Q = 64. Cost = 6 × 64 = ₹384 (on the new, larger quantity). Buyers gain ₹4 of the ₹6 because demand is less elastic than supply here.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-303","question":"A firm faces constant price elasticity of demand of −0.6 for its product at all prices. What does this imply about its pricing if it maximises profit?","options":["It should cut price to raise revenue","It is already at the revenue-maximising price","It is not at a profit maximum: raising price would raise revenue and cut costs, so it should raise price until demand becomes elastic","It should keep price constant because elasticity is constant"],"answer":2,"explanation":"With |Ed| < 1 everywhere, MR is negative, so higher prices always raise revenue and lower output cuts cost. A profit-maximising monopolist never operates on the inelastic part of demand.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-304","question":"At the current price, demand elasticity is −1.4. Approximately what happens to total revenue if price is raised by 2%?","options":["Rises by about 0.8%","Falls by about 2.8%","Rises by about 2.0%","Falls by about 0.8%"],"answer":3,"explanation":"%ΔTR ≈ %ΔP × (1 + Ed) = 2% × (1 − 1.4) = −0.8%. Quantity falls 2.8% while price rises 2%.","difficulty":"hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-305","question":"When a binding price ceiling is imposed on a product, which non-price response is most typical among sellers?","options":["Reducing quality, service or maintenance and adding queues or tie-in conditions","Raising output to meet demand","Advertising more to boost demand","Cutting prices further below the ceiling"],"answer":0,"explanation":"With price capped below equilibrium, excess demand is rationed by other means; sellers economise on quality and buyers bear waiting costs.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-306","question":"Demand is Qd = 100 − 2P and supply is Qs = 3P. A ₹10 per-unit tax is imposed. What are the losses of consumer surplus and producer surplus?","options":["CS falls by ₹216, PS by ₹324","CS falls by ₹324, PS by ₹216","CS falls by ₹288, PS by ₹192","CS falls by ₹360, PS by ₹240"],"answer":1,"explanation":"Equilibrium: P = 20, Q = 60. With tax: Pd = 26, Ps = 16, Q = 48. CS loss = 6 × (48 + 60)/2 = ₹324; PS loss = 4 × (48 + 60)/2 = ₹216. Together they exceed revenue (₹480) by the ₹60 deadweight loss.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-307","question":"Which statements are correct? I. A good with an income elasticity of −0.4 is inferior. II. A cross-price elasticity of +1.2 means the goods are complements. III. A price elasticity of −2 means a 1% price rise cuts quantity by 2%.","options":["I, II and III","II and III only","I and III only","I and II only"],"answer":2,"explanation":"Negative income elasticity marks an inferior good; a POSITIVE cross-price elasticity signals substitutes (complements are negative); |Ed| = 2 means a 2% quantity fall per 1% price rise.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-308","question":"Group A's demand is q = 40 − P (for P ≤ 40) and group B's demand is q = 60 − 2P (for P ≤ 30). What is market quantity demanded at P = 35 and at P = 20?","options":["0 at ₹35; 40 at ₹20","5 at ₹35; 20 at ₹20","5 at ₹35; 60 at ₹20","5 at ₹35; 40 at ₹20"],"answer":3,"explanation":"At ₹35 only group A buys (B's choke price is 30): 40 − 35 = 5. At ₹20 both buy: 20 + 20 = 40. Adding the equations without respecting B's choke price would give −5 at ₹35.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-309","question":"Supply is Qs = 5P + 50. Which statement about its price elasticity is correct?","options":["Supply is inelastic at every positive price, with elasticity rising toward 1 as price rises","Supply is unit elastic everywhere because it is linear","Supply is elastic at every positive price","Elasticity is constant at 5"],"answer":0,"explanation":"Es = 5P/(5P + 50) < 1 for all P > 0 because the curve hits the quantity axis at a positive quantity; it approaches 1 as P grows.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-310","question":"Market demand is P = 100 − Q. If price rises from ₹40 to ₹50, by what percentage does consumer surplus fall?","options":["25.00%","30.56%","16.67%","20.00%"],"answer":1,"explanation":"CS = ½ × (100 − P) × Q: at ₹40, ½ × 60 × 60 = 1,800; at ₹50, ½ × 50 × 50 = 1,250. Fall = 30.56%; CS falls faster than quantity because both the base and height shrink.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-311","question":"A state raises the tax on a luxury product with highly elastic demand. Which outcome is most likely?","options":["Revenue rises in proportion to the tax rate","Buyers bear the whole tax because demand is elastic","Quantity falls sharply, so tax revenue rises little or even falls, and sellers bear much of the burden only if supply is relatively inelastic","Quantity is unaffected because luxuries are status goods"],"answer":2,"explanation":"Elastic demand shrinks the tax base and shifts incidence toward sellers. Revenue can fall if the rate is already high; buyers bear more only when demand is relatively inelastic.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-312","question":"A firm's marginal revenue is ₹40 when its price is ₹100. What is the price elasticity of demand at that point?","options":["−0.60","−2.50","−1.40","−1.67"],"answer":3,"explanation":"MR = P(1 + 1/Ed): 40 = 100(1 + 1/Ed) → 1/Ed = −0.6 → Ed = −1.67. −0.60 is the reciprocal.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-313","question":"A consumer has utility U = X·Y, income ₹1,000 and faces Px = Py = ₹10. If Px doubles to ₹20, how much extra income would exactly restore her original utility (compensating variation)?","options":["₹414.21","₹500.00","₹292.89","₹1,000.00"],"answer":0,"explanation":"Initially X = Y = 50, U = 2,500. With Cobb–Douglas halves, U = (M/40)(M/20) = M²/800; setting this to 2,500 gives M = ₹1,414.21, so CV = ₹414.21. ₹500 (old X × price rise) over-compensates because she can substitute toward Y.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-314","question":"Same consumer (U = X·Y, income ₹1,000, Py = ₹10): Px rises from ₹10 to ₹20. What income loss at the ORIGINAL prices would hurt her as much as the price rise (equivalent variation)?","options":["₹414.21","₹292.89","₹500.00","₹250.00"],"answer":1,"explanation":"After the rise she buys X = 25, Y = 50, so U = 1,250. At old prices U = M²/400; U = 1,250 needs M = ₹707.11, so EV = ₹292.89. EV is smaller than the CV (₹414.21) here because of the income effect.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-315","question":"A consumer's utility is U = 10√X + Y, where Y is money spent on everything else (price ₹1). If Px = ₹0.50 and her income is ₹500, how many units of X does she buy, and what happens if her income rises to ₹800?","options":["100 units; 160 units","400 units; 640 units","100 units; still 100 units","25 units; 40 units"],"answer":2,"explanation":"Set MUx/Px = MUy/Py: (5/√X)/0.5 = 1 → √X = 10 → X = 100. With quasi-linear utility there is no income effect on X (as long as income covers it), so extra income all goes to Y.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-316","question":"At prices (Px, Py) = (2, 3) a consumer with ₹26 buys bundle A = (4, 6). At prices (3, 2) with ₹24 she buys B = (6, 3). Are these choices consistent with the weak axiom of revealed preference?","options":["Yes: B costs more than A at the first prices","Yes: incomes differ, so no comparison is possible","No: because A has more of Y","No: each bundle was affordable when the other was chosen, so each is revealed preferred to the other"],"answer":3,"explanation":"At the first prices B costs 2×6 + 3×3 = 21 ≤ 26, so A ≻ B. At the second prices A costs 3×4 + 2×6 = 24 ≤ 24, so B ≻ A. Both cannot hold: WARP is violated.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-317","question":"A doctor's hourly fee rises and she chooses to work FEWER hours. Which explanation fits standard labour-supply theory?","options":["The income effect (buying more leisure as she gets richer) outweighs the substitution effect (leisure became costlier)","The substitution effect outweighs the income effect","Leisure must be an inferior good for her","Her labour supply curve must be perfectly inelastic"],"answer":0,"explanation":"A higher wage raises the price of leisure (substitution toward work) but also raises income (more demand for leisure, a normal good). If the income effect dominates, the supply curve bends backward.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-318","question":"A consumer earns ₹1,00,000 this year and ₹1,10,000 next year and can borrow or lend at 10%. What is the maximum she can consume this year, and the maximum next year?","options":["₹2,10,000 this year or ₹2,10,000 next year","₹2,00,000 this year or ₹2,20,000 next year","₹1,00,000 this year or ₹2,10,000 next year","₹2,00,000 this year or ₹2,10,000 next year"],"answer":1,"explanation":"PV of lifetime income = 1,00,000 + 1,10,000/1.1 = ₹2,00,000 (all borrowed against next year). FV = 1,00,000 × 1.1 + 1,10,000 = ₹2,20,000. The budget line's slope is −(1 + r).","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-319","question":"An investor with utility U = √W faces a gamble paying wealth of ₹100 or ₹400 with equal probability. What are its certainty equivalent and risk premium?","options":["₹250 and ₹0","₹225 and ₹175","₹225 and ₹25","₹200 and ₹50"],"answer":2,"explanation":"EU = 0.5 × 10 + 0.5 × 20 = 15, so the certainty equivalent is 15² = ₹225. Expected wealth = ₹250, so the risk premium = 250 − 225 = ₹25 (positive because utility is concave).","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-320","question":"A shopkeeper with wealth ₹10,00,000 faces a 10% chance of a ₹6,40,000 fire loss. His utility is U = √W. What is the most he would pay for full insurance, compared with the expected loss?","options":["₹64,000 versus an expected loss of ₹64,000","₹78,400 versus an expected loss of ₹6,40,000","₹1,00,000 versus an expected loss of ₹64,000","₹78,400 versus an expected loss of ₹64,000"],"answer":3,"explanation":"EU = 0.9 × √10,00,000 + 0.1 × √3,60,000 = 900 + 60 = 960; certainty equivalent = 960² = ₹9,21,600. Max premium = 10,00,000 − 9,21,600 = ₹78,400, above the ₹64,000 expected loss because he is risk-averse.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-321","question":"A firm's short-run total cost is TC = 1,000 + 10Q − 0.2Q² + 0.002Q³. Below what market price should it shut down in the short run?","options":["₹5","₹10","₹20","₹7.50"],"answer":0,"explanation":"AVC = 10 − 0.2Q + 0.002Q²; dAVC/dQ = −0.2 + 0.004Q = 0 → Q = 50, AVC = 10 − 10 + 5 = ₹5. Below minimum AVC the firm cannot cover variable costs, so it shuts down; fixed cost ₹1,000 is irrelevant.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-322","question":"At the current output, a firm's marginal cost is ₹40 and its average cost ₹50. What is its cost elasticity of output, and what does it indicate?","options":["1.25; diseconomies of scale","0.8; economies of scale (average cost falling)","0.8; diseconomies of scale","1.25; economies of scale"],"answer":1,"explanation":"Cost elasticity = %ΔC/%ΔQ = MC/AC = 40/50 = 0.8. Below 1, costs rise less than proportionally with output, so AC is falling—economies of scale.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-323","question":"In an industry, the minimum efficient scale (MES) is 2 lakh units a year. At a price equal to minimum average cost, the market buys 10 lakh units. What is the maximum number of firms that can operate at MES, and what market structure is likely?","options":["50 firms; perfect competition","1 firm; natural monopoly","5 firms; an oligopoly","10 firms; monopolistic competition"],"answer":2,"explanation":"10 lakh/2 lakh = 5 efficient-sized firms. With so few firms able to reach low costs, the market tends toward oligopoly; if MES exceeded demand, it would be a natural monopoly.","difficulty":"hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-324","question":"A firm's technology is Q = min(L/2, K): each unit needs 2 hours of labour and 1 machine-hour. The wage is ₹200 per hour and the machine rental ₹500 per hour. What is the minimum cost of producing 100 units?","options":["₹70,000","₹50,000","₹1,40,000","₹90,000"],"answer":3,"explanation":"With fixed proportions there is no substitution: 100 units need L = 200 and K = 100, costing 200 × 200 + 100 × 500 = ₹90,000. ₹70,000 forgets that each unit needs two labour-hours.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-325","question":"A firm's production function is Q = 2L + 3K (perfect substitutes). The wage is ₹10 and the rental rate ₹12. How should it produce 600 units at least cost?","options":["Use only capital: K = 200, cost ₹2,400","Use only labour: L = 300, cost ₹3,000","Use equal L and K, cost ₹2,640","Use only capital: K = 200, cost ₹3,600"],"answer":0,"explanation":"Cost per unit of output: labour 10/2 = ₹5, capital 12/3 = ₹4. With perfect substitutes the firm uses only the cheaper input per unit of output: K = 200, cost ₹2,400.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-326","question":"A firm's production function is Q = 5L^0.6 K^0.3. If labour alone rises by 10%, by about how much does output rise, and what are the returns to scale?","options":["About 6.00%; constant returns to scale","About 5.89%; decreasing returns to scale","About 8.96%; decreasing returns to scale","About 5.89%; increasing returns to scale"],"answer":1,"explanation":"Output elasticity of labour = 0.6, so Q rises by 1.1^0.6 − 1 = 5.89% (≈ 6%). Exponents sum to 0.9 < 1, so doubling all inputs less than doubles output.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-327","question":"Real output grows 7% in a year. The capital stock grows 8% and labour input 2%. Capital's share of income is 0.4 and labour's 0.6. What is total factor productivity (TFP) growth?","options":["3.0%","1.6%","2.6%","4.6%"],"answer":2,"explanation":"Growth accounting: TFP = 7 − (0.4 × 8 + 0.6 × 2) = 7 − 4.4 = 2.6%. Swapping the shares gives 7 − (0.6 × 8 + 0.4 × 2) = 1.4%.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-328","question":"A competitive firm's output is Q = 20√L. Output sells at ₹5 and the wage is ₹25 per worker-day. How many worker-days should it hire?","options":["16","2","8","4"],"answer":3,"explanation":"MPL = 10/√L; the firm hires until P × MPL = w: 50/√L = 25 → √L = 2 → L = 4. 16 equates MPL (not its value) to the wage.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-329","question":"A single employer in a town faces labour supply w = 10 + L and has a marginal revenue product of labour MRP = 70 − L. How many workers does it hire and at what wage, compared with a competitive labour market?","options":["20 at ₹30, versus 30 at ₹40 under competition","30 at ₹40 in both cases","20 at ₹50, versus 30 at ₹40","30 at ₹30, versus 20 at ₹40"],"answer":0,"explanation":"Marginal cost of labour = d(wL)/dL = 10 + 2L. Set equal to MRP: 10 + 2L = 70 − L → L = 20, paid w = 10 + 20 = ₹30. Competition sets supply = MRP: 10 + L = 70 − L → L = 30, w = ₹40.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-330","question":"Producing 100 units of X alone costs ₹500 and 50 units of Y alone ₹400; producing both together costs ₹750. What is the degree of economies of scope?","options":["16.7%","20.0%","37.5%","30.0%"],"answer":1,"explanation":"SC = [C(X) + C(Y) − C(X, Y)]/C(X, Y) = (500 + 400 − 750)/750 = 20.0%. Positive SC means joint production is cheaper; dividing by the separate cost total gives 16.7%.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-331","question":"Which statement about the long-run average cost (LRAC) curve as an envelope of short-run curves (SRAC) is correct?","options":["LRAC always touches each SRAC at the SRAC's minimum","LRAC lies above some SRAC curves","Where LRAC is falling, it is tangent to each SRAC to the left of that SRAC's minimum point","LRAC is tangent to SRAC only where both are rising"],"answer":2,"explanation":"In the economies-of-scale region, it is cheaper to run a larger plant below capacity than a smaller plant at its minimum, so tangency is left of the SRAC minimum; only at minimum LRAC does tangency occur at the SRAC minimum.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-332","question":"Which is the most commonly cited source of diseconomies of scale in very large firms?","options":["Bulk purchasing discounts","Spreading R&D over more units","Specialisation of labour","Coordination and monitoring costs as management layers multiply"],"answer":3,"explanation":"Bulk buying, R&D spreading and specialisation are sources of economies of scale. Beyond some size, communication, bureaucracy and motivation problems raise average cost.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-333","question":"For the Cobb–Douglas production function Q = A·L^α·K^β, which statement is correct?","options":["The elasticity of substitution is 1, so a 10% rise in w/r raises K/L by 10%","The elasticity of substitution equals α + β","Inputs are perfect substitutes","The elasticity of substitution is zero"],"answer":0,"explanation":"Cost minimisation gives K/L = (β/α)(w/r), so K/L moves one-for-one in percentage terms with w/r: elasticity of substitution = 1, whatever α and β. Factor cost shares therefore stay constant.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-334","question":"A firm with Q = L^0.5 K^0.5 pays a wage of ₹8 and a rental rate of ₹2. Along its least-cost expansion path, what is the capital–labour ratio?","options":["K/L = 1/4","K/L = 4","K/L = 1","K/L = 2"],"answer":1,"explanation":"Cost minimisation sets MRTS = MPL/MPK = K/L equal to w/r = 8/2 = 4. Expensive labour leads the firm to use relatively more capital.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-335","question":"A consumer with Cobb–Douglas utility U = X^0.3 Y^0.7 sees the price of X rise by 20%. What happens to her spending on X and to the quantity of X she buys?","options":["Spending rises 20%; quantity unchanged","Spending falls 20%; quantity falls 20%","Spending on X is unchanged; quantity falls by about 16.7%","Spending unchanged; quantity falls 20%"],"answer":2,"explanation":"Cobb–Douglas demand is X = 0.3M/Px: spending on X is always 30% of income (unit-elastic demand). Quantity falls to 1/1.2 of its level, a 16.7% fall.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-336","question":"A factory's only variable input is labour at ₹200 an hour. At current output, the marginal product of an hour is 25 units and the average product is 40 units. What are marginal cost and average variable cost, and is AVC rising or falling?","options":["MC ₹5, AVC ₹8; AVC is falling","MC ₹8, AVC ₹5; AVC is falling","MC ₹0.125, AVC ₹0.20; AVC is rising","MC ₹8, AVC ₹5; AVC is rising"],"answer":3,"explanation":"MC = w/MPL = 200/25 = ₹8; AVC = w/APL = 200/40 = ₹5. Since MC > AVC, AVC is rising (and MP < AP means AP is falling).","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-337","question":"A firm has a budget of ₹1,20,000. The wage is ₹600 a day and capital rent ₹2,000 a day. If the wage rises to ₹800, what happens to its isocost line (K on vertical axis)?","options":["It pivots inward on the labour axis (from 200 to 150 days) and becomes steeper, slope from −0.3 to −0.4","It shifts parallel inward","It pivots on the capital axis and becomes flatter","It is unchanged because the budget is fixed"],"answer":0,"explanation":"Isocost: 600L + 2,000K = 1,20,000, slope −w/r = −0.3. With w = 800, the L-intercept drops to 150, the K-intercept stays at 60 and the slope becomes −0.4.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-338","question":"A firm's technology is Q = L^0.3 K^0.7 and it minimises cost. Its total cost is ₹10 lakh a month. How much does it spend on labour?","options":["₹7 lakh","₹3 lakh","₹5 lakh","₹4.3 lakh"],"answer":1,"explanation":"With Cobb–Douglas and cost minimisation, wL/rK = α/β, so labour's share of cost equals α/(α + β) = 0.3/1.0 = 30%: ₹3 lakh.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-339","question":"A farmer both grows and eats rice. The market price of rice rises sharply. Which statement is correct?","options":["She must be worse off, because a consumer always loses from a price rise","She must buy more rice because of the income effect","She may be better off, since the higher price raises the value of her endowment of rice","Her welfare is unaffected because she grows her own rice"],"answer":2,"explanation":"For a net seller, a price rise raises income from her endowment more than it raises the cost of what she eats. Whether she is better off depends on whether she is a net seller or buyer.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-340","question":"Water is essential yet cheap, while diamonds are inessential yet costly. Which concept resolves this 'paradox of value'?","options":["Prices reflect total utility","Water has no utility at the margin because it is free","Diamonds have higher production costs, so marginal utility is irrelevant","Prices reflect marginal utility, not total utility; water is abundant, so its marginal utility is low"],"answer":3,"explanation":"Total utility from water is enormous, but because we consume so much, the last litre adds little; scarce diamonds have high marginal utility. Price tracks the margin.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-341","question":"Which utility function represents the SAME preferences as U = X·Y?","options":["V = ln X + ln Y","V = X + Y","V = X²·Y","V = min(X, Y)"],"answer":0,"explanation":"ln X + ln Y = ln(XY) is a strictly increasing transformation of XY, so it ranks every bundle identically. X²Y changes the MRS (2Y/X versus Y/X), so it describes different preferences.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-342","question":"A competitive firm's short-run total cost is TC = 100 + 2Q². What is its short-run supply curve?","options":["Q = P/2 for P ≥ ₹28.28","Q = P/4 for any P > 0","Q = P/4 only for P ≥ ₹28.28","Q = P/2 for any P > 0"],"answer":1,"explanation":"MC = 4Q, so P = MC gives Q = P/4. AVC = 2Q is below MC everywhere and its minimum is 0, so the firm supplies at any positive price; the ₹28.28 minimum ATC is the long-run break-even, not the shutdown point.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-343","question":"A competitive firm's total costs for 0–4 units are ₹50, ₹70, ₹85, ₹105 and ₹135. The market price is ₹25. How many units should it produce, and what is its profit?","options":["4 units; loss of ₹35","0 units; loss of ₹50","3 units; loss of ₹30","2 units; loss of ₹35"],"answer":2,"explanation":"Marginal costs are 20, 15, 20, 30. Produce while P ≥ MC: units 1–3 (MC 20, 15, 20), not the 4th (MC 30). Revenue 75 − cost 105 = −₹30, better than shutting down (−₹50 fixed cost).","difficulty":"very-hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-344","question":"A firm's output is Q = 10L² − 0.5L³. At what labour input does marginal product peak, and at what input does average product peak?","options":["MP peaks at L = 10; AP peaks at L ≈ 6.67","Both peak at L = 10","MP peaks at L ≈ 13.3; AP peaks at L = 10","MP peaks at L ≈ 6.67; AP peaks at L = 10"],"answer":3,"explanation":"MP = 20L − 1.5L² peaks where 20 − 3L = 0 → L ≈ 6.67. AP = 10L − 0.5L² peaks at L = 10, where MP = AP (= 50). MP always peaks before AP.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-345","question":"Assertion (A): A compensated (Hicksian) demand curve can never slope upward. Reason (R): The substitution effect of a price rise, holding utility constant, always reduces the quantity demanded.","options":["Both A and R are true, and R explains A","Both are true, but R does not explain A","A is false, because Giffen goods have upward-sloping compensated demand","A is true, R is false"],"answer":0,"explanation":"Compensated demand removes the income effect, leaving only the substitution effect, which is always non-positive. Giffen behaviour requires a large perverse income effect, so it shows up only in ordinary (Marshallian) demand.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-346","question":"Why does a fixed-basket (Laspeyres) consumer price index tend to OVERSTATE the rise in the cost of living?","options":["It uses current-period quantities","It ignores consumers' substitution away from goods whose relative prices have risen","It gives too little weight to food","It counts quality improvements as price rises only when products improve"],"answer":1,"explanation":"Holding the base-period basket fixed misses substitution toward relatively cheaper goods, so the index rises faster than the true cost of maintaining utility. Unmeasured quality gains and new goods add further upward bias.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-347","question":"A plant sells 1,000 units a month at ₹50 with variable cost ₹40 a unit. It also incurs fixed costs of ₹15,000 a month that would be avoided if the plant were mothballed, and ₹20,000 of unavoidable fixed costs. Should it keep operating in the short run?","options":["Yes: price exceeds average variable cost","Yes: closing still leaves the ₹20,000 unavoidable cost","No: its ₹10,000 contribution does not cover the ₹15,000 of avoidable fixed costs","No: it does not cover total fixed costs of ₹35,000"],"answer":2,"explanation":"The relevant comparison is contribution (₹10,000) against all costs that closing would save (₹15,000). Losing ₹25,000 by operating versus ₹20,000 by mothballing means shut. P > AVC is not enough when some fixed costs are avoidable.","difficulty":"very-hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-348","question":"In a perfectly competitive, constant-cost industry, demand rises permanently. What happens in the long run?","options":["Price stays permanently higher, attracting no entry","Each existing firm permanently expands output and earns economic profit","Price falls below the original level due to economies of scale","Price returns to its original level (minimum LRAC) and output rises through entry of new firms"],"answer":3,"explanation":"Short-run profits attract entry; with input prices unaffected (constant cost), entry continues until price is back at minimum LRAC. The long-run industry supply curve is horizontal.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-349","question":"A firm makes a product in two plants with MC₁ = 10 + 2q₁ and MC₂ = 20 + q₂. It wants to produce 40 units at least cost. How should output be split?","options":["Plant 1: 16.67; plant 2: 23.33","Plant 1: 20.00; plant 2: 20.00","Plant 1: 23.33; plant 2: 16.67","Plant 1: 5.00; plant 2: 35.00"],"answer":0,"explanation":"Least cost requires equal marginal costs: 10 + 2q₁ = 20 + (40 − q₁) → 3q₁ = 50 → q₁ = 16.67, q₂ = 23.33; both MCs equal 43.33.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-350","question":"Average wages in a factory rise 8% while output per worker rises 5%. By approximately how much does unit labour cost change?","options":["13.00%","2.86%","3.00%","−2.78%"],"answer":1,"explanation":"Unit labour cost = wage/productivity, so it changes by 1.08/1.05 − 1 = 2.86% (≈ 3%). Productivity gains offset most of the wage rise.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-351","question":"A person is offered either ₹500 for certain or a 50% chance of ₹1,000 (else nothing) and strictly prefers the gamble. Her utility of wealth is most likely:","options":["Concave (risk-averse)","Linear (risk-neutral)","Convex (risk-loving)","Undefined, because the expected values are equal"],"answer":2,"explanation":"With equal expected values, a risk-averse (concave) person takes the certain ₹500, a risk-neutral one is indifferent, and only a risk-lover (convex utility) strictly prefers the gamble.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-352","question":"The government gives poor households a food voucher worth ₹1,000 a month that can be spent only on food. A household already spends ₹3,000 a month on food. Compared with a ₹1,000 cash transfer, the voucher:","options":["Raises food spending by exactly ₹1,000 more than cash","Makes the household worse off than cash","Has no effect on the household's welfare","Has the same effect, because it is inframarginal—the household would spend at least ₹1,000 on food anyway"],"answer":3,"explanation":"If the household already spends more than the voucher's value on food, the voucher frees up ₹1,000 of cash for other uses, exactly like a cash grant. It binds only for households that would spend less than ₹1,000 on food.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-353","question":"A monopolist faces demand P = 100 − Q and has marginal cost MC = 10 + Q. What are its price and output, and the deadweight loss compared with a competitive market with the same supply (MC) curve?","options":["P = ₹70, Q = 30; DWL = ₹225","P = ₹55, Q = 45; DWL = ₹0","P = ₹70, Q = 30; DWL = ₹112.50","P = ₹70, Q = 30; DWL = ₹450"],"answer":0,"explanation":"MR = 100 − 2Q = 10 + Q → Q = 30, P = 70 (MC there = 40). Competition: 100 − Q = 10 + Q → Q = 45. DWL = ½ × (70 − 40) × (45 − 30) = ₹225.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-354","question":"A monopolist faces demand P = 100 − Q with constant MC = ₹20 (no fixed cost). Unregulated, it sells 40 units at ₹60. If a regulator caps the price at ₹40, what output does it now choose?","options":["40 units","60 units","30 units","80 units"],"answer":1,"explanation":"Under the cap, MR = ₹40 for every unit up to where demand meets the cap (Q = 60). Since MC = 20 < 40 it sells all 60; beyond 60 it would have to cut price below the cap. A well-set cap raises output.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-355","question":"A utility has demand P = 100 − Q, constant MC = ₹20 and a fixed cost of ₹1,200. If regulators set price equal to average cost (the larger-output solution), what are price and output, and what is the loss under marginal-cost pricing instead?","options":["AC pricing: P = ₹60, Q = 40; MC pricing loses ₹1,200","AC pricing: P = ₹40, Q = 60; MC pricing breaks even","AC pricing: P = ₹40, Q = 60; MC pricing loses ₹1,200","AC pricing: P = ₹20, Q = 80; MC pricing loses ₹1,600"],"answer":2,"explanation":"AC = 20 + 1,200/Q = 100 − Q → Q² − 80Q + 1,200 = 0 → Q = 60 (or 20), P = 40. With P = MC = 20, Q = 80 and the firm loses its whole ₹1,200 fixed cost—the natural-monopoly pricing dilemma.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-356","question":"A competitive industry has 100 identical firms, each with TC = 50 + q². Market demand is Q = 1,000 − 50P. What is the short-run equilibrium price, and what will happen in the long run?","options":["P = ₹10 with each firm earning ₹25, so firms will enter","P = ₹14.14 with zero profit, so no change","P = ₹20 with each firm earning ₹50, so firms will enter","P = ₹10 with each firm losing ₹25, so firms will exit"],"answer":3,"explanation":"Each firm's supply is q = P/2 (from MC = 2q), so market supply = 50P. 1,000 − 50P = 50P → P = 10, q = 5. Profit = 50 − (50 + 25) = −₹25 (but P > AVC = 5, so they produce). Losses drive exit until P = min ATC = ₹14.14.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-357","question":"A firm's price elasticity of demand is −2 and its advertising elasticity of demand is 0.1. By the Dorfman–Steiner rule, what share of sales revenue should it spend on advertising?","options":["5%","20%","10%","2%"],"answer":0,"explanation":"Optimal advertising-to-sales ratio = advertising elasticity/|price elasticity| = 0.1/2 = 5%. Firms with inelastic demand and responsive customers advertise more intensively.","difficulty":"very-hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-358","question":"An airline is the only carrier on a route, but any rival could enter and exit quickly with leased aircraft and no sunk costs. According to contestable-market theory, what price will it charge?","options":["The monopoly price, because it is the only seller","Close to average cost, earning about normal profit, because any higher price invites hit-and-run entry","Below marginal cost to deter entry","A price determined by the kinked demand curve"],"answer":1,"explanation":"With free entry and costless exit, potential competition disciplines the incumbent; market structure (one seller) matters less than contestability.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-359","question":"An incumbent has average cost of ₹40. A potential entrant's minimum average cost is ₹50 and it believes the incumbent will keep its price after entry. What is the highest price the incumbent can charge while deterring entry?","options":["₹40","The monopoly price","Just below ₹50","Just below ₹45"],"answer":2,"explanation":"Limit pricing sets the price just below the entrant's minimum average cost, so entry would be unprofitable. The incumbent sacrifices some short-run profit but keeps a margin of nearly ₹10 a unit.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-360","question":"A mobile operator offers ₹2 per MB for the first 1 GB and ₹1 per MB beyond that, available to all customers, letting them self-select. This is an example of:","options":["First-degree price discrimination","Third-degree price discrimination","Peak-load pricing","Second-degree price discrimination"],"answer":3,"explanation":"Second-degree discrimination charges different prices by quantity (or version) with the same menu for everyone. Third-degree uses observable groups; first-degree charges each buyer their reservation price.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-361","question":"A monopolist with demand P = 100 − Q and constant MC = ₹20 can practise perfect (first-degree) price discrimination. What output does it sell and what is its profit?","options":["80 units; ₹3,200","40 units; ₹1,600","80 units; ₹1,600","40 units; ₹3,200"],"answer":0,"explanation":"It sells to everyone willing to pay at least MC: Q = 80 (the competitive output, so no deadweight loss). Profit = all surplus = ½ × 80 × (100 − 20) = ₹3,200.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-362","question":"Two firms compete in quantities (Cournot). Market demand is P = 100 − Q; firm 1's MC is ₹10 and firm 2's is ₹20. What are the equilibrium outputs and price?","options":["q₁ = q₂ = 28.33, P = ₹43.33","q₁ = 33.33, q₂ = 23.33, P = ₹43.33","q₁ = 23.33, q₂ = 33.33, P = ₹43.33","q₁ = 45.00, q₂ = 40.00, P = ₹15.00"],"answer":1,"explanation":"Reaction functions: q₁ = (90 − q₂)/2, q₂ = (80 − q₁)/2. Solving: q₁ = 33.33, q₂ = 23.33, P = ₹43.33. The lower-cost firm produces more.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-363","question":"Two firms sell an identical product and compete on price (Bertrand). Firm A's constant MC is ₹30 and firm B's is ₹36; there are no capacity limits. What is the equilibrium?","options":["Both price at ₹30 and split the market","Both price at ₹36 and split the market","A captures the market at a price just below ₹36","A prices at ₹30 and earns zero profit"],"answer":2,"explanation":"B cannot price below ₹36 without losses. A undercuts to just below ₹36, wins all sales and earns about ₹6 a unit; pricing at ₹30 would throw that margin away.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-364","question":"Market demand is Q = 100 − P. A competitive fringe supplies Qf = P − 20 (for P ≥ 20). A dominant firm with constant MC = ₹20 sets the price and lets the fringe supply what it wants. What price does it set, and how much do it and the fringe sell?","options":["P = ₹60; dominant firm 20, fringe 40","P = ₹40; dominant firm 60, fringe 0","P = ₹30; dominant firm 60, fringe 10","P = ₹40; dominant firm 40, fringe 20"],"answer":3,"explanation":"Residual demand = (100 − P) − (P − 20) = 120 − 2P, i.e. P = 60 − Q_d/2, so MR = 60 − Q_d. Set MR = 20 → Q_d = 40, P = 40; fringe = 20; total 60 = 100 − 40.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-365","question":"Two firms face P = 100 − Q with MC = ₹10 and agree to split the monopoly output equally (22.5 units each). If firm 1 secretly deviates to its best response while firm 2 keeps to 22.5, what is firm 1's profit compared with sticking to the deal?","options":["₹1139.06 versus ₹1012.50","₹1012.50 versus ₹1012.50","₹1350.00 versus ₹1012.50","₹1139.06 versus ₹2025.00"],"answer":0,"explanation":"Collusion: Q = 45, P = 55, each earns 45 × 22.5 = ₹1012.50. Best response to 22.5: q₁ = (90 − 22.5)/2 = 33.75, P = 43.75, profit = 33.75 × 33.75 = ₹1139.06. The gain from cheating is why cartels are fragile.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-366","question":"An industry's firms have market shares of 30%, 25%, 20%, 10%, 5%, 5% and 5%. What are its four-firm concentration ratio (CR4) and Herfindahl–Hirschman index (HHI)?","options":["CR4 = 85%; HHI = 2,025","CR4 = 85%; HHI = 2,100","CR4 = 75%; HHI = 2,100","CR4 = 85%; HHI = 100"],"answer":1,"explanation":"CR4 = 30 + 25 + 20 + 10 = 85%. HHI = 900 + 625 + 400 + 100 + 25 + 25 + 25 = 2,100. Leaving out the small firms gives 2,025; HHI squares shares, so it weights large firms heavily.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-367","question":"Which distinguishes predatory pricing from limit pricing?","options":["Predation is legal everywhere; limit pricing is always illegal","Limit pricing requires pricing below marginal cost","Predation cuts price below cost to drive out an existing rival and recoup later; limit pricing keeps price just low enough to deter entry","They are the same strategy"],"answer":2,"explanation":"Predatory pricing targets rivals already in the market with deliberate losses, expecting monopoly profits later. Limit pricing deters potential entrants while staying profitable.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-368","question":"A food-delivery platform charges restaurants a commission but gives customers free delivery. Which economic logic best explains this?","options":["Customers have perfectly inelastic demand","Restaurants are price-takers in a perfectly competitive market","Free delivery is required by competition law","In a two-sided market, the side whose participation creates more value for the other (and is more price-sensitive) is subsidised"],"answer":3,"explanation":"Platforms price to get both sides on board: each extra customer raises restaurants' willingness to join, so customers may be charged below cost while restaurants pay more.","difficulty":"hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-369","question":"A firm sets prices by adding a fixed 30% markup to unit cost for every product. Compared with profit-maximising pricing, this is most likely to:","options":["Under-price products with inelastic demand and over-price those with elastic demand","Always maximise profit if costs are measured correctly","Over-price inelastic products and under-price elastic ones","Give the same prices as the Lerner rule"],"answer":0,"explanation":"Optimal markups vary inversely with elasticity (Lerner rule). A uniform markup leaves money on the table where customers are insensitive and loses volume where they are sensitive.","difficulty":"moderate","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-370","question":"A firm launching a new messaging app prices it below cost initially. Which conditions best justify this penetration pricing?","options":["Highly inelastic early-adopter demand","Strong network effects or learning-curve cost declines that make early market share valuable later","A patent that blocks all competition","Rising marginal costs as output expands"],"answer":1,"explanation":"Penetration pricing pays when volume today raises future value (network effects, switching costs, scale or learning economies). Inelastic early adopters favour skimming instead.","difficulty":"moderate","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-371","question":"In a perfectly competitive, constant-cost industry, a per-unit tax of ₹10 is imposed on sellers. In long-run equilibrium, how much does the price paid by consumers rise?","options":["By ₹5","By nothing; firms absorb it","By the full ₹10","By more than ₹10"],"answer":2,"explanation":"Long-run supply is horizontal at minimum LRAC. Firms must cover cost plus tax to stay, so exit continues until price rises by the full ₹10—consumers bear all of it in the long run.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-372","question":"A profit-maximising monopolist (earning positive profit) is hit first by a lump-sum licence fee and, separately, by a 30% tax on economic profit. How do its price and output respond?","options":["Both raise price and cut output","The licence fee raises price; the profit tax does not","The profit tax raises price; the licence fee does not","Neither tax changes price or output (as long as it stays in business)"],"answer":3,"explanation":"Neither tax affects MR or MC, so the profit-maximising output is unchanged. A 30% profit tax scales profit down but leaves the same output as the maximiser.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-373","question":"Beyond the standard deadweight-loss triangle, which additional social costs of monopoly do economists highlight?","options":["X-inefficiency (slack cost control) and rent-seeking spending to acquire or protect monopoly power","Excessive output and very low prices","Too much innovation","Lower producer surplus than under competition"],"answer":0,"explanation":"Sheltered firms may let costs drift up, and resources spent lobbying for protection are wasted. Both add to the welfare loss beyond the Harberger triangle.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-374","question":"A firm sells the same product in two separated markets with constant marginal cost of ₹20. Demand elasticity is −2 in market A and −4 in market B. What prices maximise profit?","options":["₹26.67 in A and ₹40 in B","₹40 in A and ₹26.67 in B","₹40 in both markets","₹30 in A and ₹25 in B"],"answer":1,"explanation":"Apply P = MC/(1 + 1/E) in each: A: 20/(1 − 0.5) = 40; B: 20/(1 − 0.25) = 26.67. The less elastic market pays more.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-375","question":"Why does a monopolist have no supply curve in the usual sense?","options":["Because it always produces at minimum ATC","Because its MC curve is horizontal","Its output at a given price depends on the shape of the demand curve (via MR), so there is no unique price–quantity mapping","Because it never produces in the short run"],"answer":2,"explanation":"A competitive firm's MC above AVC is its supply curve because P = MR. For a monopolist, the same MC can be paired with different prices depending on demand elasticity.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-376","question":"Two stores both promise to 'match any lower price' for an identical product. What is the most likely effect on prices?","options":["Prices fall to marginal cost faster","Prices become more volatile","No effect, because consumers rarely claim the match","Prices tend to stay HIGH, because undercutting a rival wins no customers"],"answer":3,"explanation":"A price-match guarantee removes the payoff from cutting price (the rival matches automatically), so it can sustain tacit collusion even though it looks pro-consumer.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-377","question":"Two ice-cream sellers with identical products and prices choose locations along a straight beach with evenly spread customers who walk to the nearest seller. Where do they end up?","options":["Both at the centre, side by side","At the quarter points, minimising walking","At the two ends of the beach","Randomly, since profits are equal anywhere"],"answer":0,"explanation":"Each can steal customers by moving toward the other, so the Nash equilibrium is both at the middle (minimum differentiation), even though quarter points minimise total travel—Hotelling's principle.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-378","question":"A monopolist's annual rent doubles. Assuming it remains profitable enough to stay in business, how should it change its price and output?","options":["Raise price to recover the rent","Leave both unchanged","Cut output to save costs","Raise output to spread the fixed cost"],"answer":1,"explanation":"A fixed cost does not affect MR or MC, so the profit-maximising output and price stay the same; only profit falls. Spreading fixed costs is a trap.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-379","question":"A monopolist sells a highly durable good (e.g. land plots) and cannot commit to future prices. According to the Coase conjecture, what happens?","options":["It can charge the monopoly price forever because the good is durable","It prefers to make the good less durable only to cut costs","Buyers anticipate future price cuts and wait, forcing the monopolist's price down toward competitive levels","Durability has no effect on pricing power"],"answer":2,"explanation":"Once early buyers are served, the seller wants to cut price to reach the rest; rational buyers foresee this and delay. Remedies include leasing, buy-back guarantees or capacity limits.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-380","question":"Which condition best defines a natural monopoly?","options":["The firm owns a natural resource","The government grants it an exclusive licence","Its marginal cost is rising over the relevant range","The cost function is subadditive: one firm can produce the market's output more cheaply than two or more firms"],"answer":3,"explanation":"Natural monopoly is a cost concept. Average costs falling over the relevant range is a sufficient (not necessary) condition for subadditivity.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-381","question":"A regulated utility is allowed to earn a fixed rate of return on its capital base, set above its true cost of capital. What distortion is predicted?","options":["It over-invests in capital relative to labour (Averch–Johnson effect)","It under-invests in capital to cut costs","It charges below marginal cost","It reduces output below the monopoly level"],"answer":0,"explanation":"If the allowed return exceeds the cost of capital, each extra rupee of capital raises allowed profit, so the firm substitutes capital for other inputs beyond the cost-minimising mix.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-382","question":"Which statement about third-degree price discrimination and total welfare is correct?","options":["It always reduces total welfare","It can raise total welfare if it lets the firm serve a market that would otherwise not be served at a single price","It always raises consumer surplus in every market","It has no effect on total output"],"answer":1,"explanation":"With linear demands and all markets served, it tends to lower welfare (output unchanged, misallocation). But if a uniform price would shut out a low-value market, discrimination adds output and can be welfare-improving.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-383","question":"In long-run monopolistic-competition equilibrium, a firm's demand is P = 60 − 2q and its marginal cost is ₹20 at the profit-maximising output. What are its output, price and average total cost?","options":["q = 20, P = ₹20, ATC = ₹20","q = 10, P = ₹40, ATC = ₹20","q = 10, P = ₹40, ATC = ₹40","q = 15, P = ₹30, ATC = ₹30"],"answer":2,"explanation":"MR = 60 − 4q = 20 → q = 10, P = 40. Zero long-run profit means the demand curve is tangent to ATC there, so ATC = ₹40 > MC, with excess capacity.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-384","question":"A monopolist faces demand P = 200 − 4Q and has total cost TC = 100 + 20Q + Q². What are its profit-maximising price and profit?","options":["P = ₹128; profit = ₹1,620","P = ₹110; profit = ₹1,520","P = ₹92; profit = ₹1,196","P = ₹128; profit = ₹1,520"],"answer":3,"explanation":"MR = 200 − 8Q; MC = 20 + 2Q; equal at Q = 18. P = 200 − 72 = 128. Profit = 128 × 18 − (100 + 360 + 324) = 2,304 − 784 = ₹1,520.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-385","question":"A monopolist faces constant-elasticity demand with elasticity −2 and constant marginal cost. If marginal cost rises by ₹10, by how much does its price rise?","options":["₹20","₹10","₹5","₹13.33"],"answer":0,"explanation":"With constant elasticity, P = MC/(1 + 1/E) = 2 × MC, so price rises by twice the cost increase—over 100% pass-through, unlike the 50% under linear demand.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-386","question":"A competitive firm faces a price of ₹60 and has TC = 200 + 10q + q². What output maximises profit, and what is the profit?","options":["q = 30; profit = ₹400","q = 25; profit = ₹425","q = 25; profit = ₹625","q = 50; profit = −₹200"],"answer":1,"explanation":"MC = 10 + 2q = 60 → q = 25. Revenue 1,500 − cost (200 + 250 + 625 = 1,075) = ₹425. ₹625 forgets the fixed cost.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-387","question":"An incumbent builds large excess capacity before any rival enters. In entry-deterrence theory, why can this work where a mere threat to cut prices might not?","options":["Excess capacity lowers the entrant's costs","It signals that the incumbent is unprofitable","Sunk capacity makes high post-entry output credible, since the extra output is cheap to produce once capacity exists","Regulators prohibit entry into markets with spare capacity"],"answer":2,"explanation":"A price-war threat is often not credible because fighting hurts the incumbent too. Irreversible investment changes the incumbent's own incentives after entry, making aggressive output its best response.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-388","question":"Match each practice with its type. (p) A car dealer haggles to charge each buyer close to their maximum; (q) senior-citizen discounts on rail fares; (r) 'buy 2, get the 3rd at half price'. Types: (1) first-degree; (2) second-degree; (3) third-degree.","options":["p-1, q-2, r-3","p-3, q-1, r-2","p-2, q-3, r-1","p-1, q-3, r-2"],"answer":3,"explanation":"Individual haggling approximates first-degree; group pricing by an observable trait (age) is third-degree; quantity-based menus are second-degree.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-389","question":"Which conditions make tacit collusion EASIER to sustain? I. Few firms. II. Homogeneous products and transparent prices. III. Large, infrequent, lumpy orders. IV. Stable demand.","options":["I, II and IV only","I, II, III and IV","I and III only","II, III and IV only"],"answer":0,"explanation":"Few sellers, transparency and stable demand make cheating easy to detect and punish. Large infrequent orders raise the one-off gain from undercutting, making collusion harder.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-390","question":"For two identical firms with constant marginal cost facing linear demand, how do market prices rank under joint-profit collusion, Cournot and Bertrand competition?","options":["Cournot > collusion > Bertrand","Collusion > Cournot > Bertrand (= MC)","Bertrand > Cournot > collusion","Collusion = Cournot > Bertrand"],"answer":1,"explanation":"Collusion replicates the monopoly price; Cournot gives an intermediate price above MC; homogeneous-product Bertrand drives price to MC.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-391","question":"Firms in a monopolistically competitive industry are earning economic profits. As new firms enter, what happens to each existing firm's demand curve?","options":["It shifts right and becomes less elastic","It becomes perfectly elastic immediately","It shifts left and becomes more elastic as close substitutes multiply","It is unaffected because products are differentiated"],"answer":2,"explanation":"Entrants take customers and add substitutes, so each firm's demand shifts left and flattens until it is tangent to ATC.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-392","question":"A regulated railway must cover its fixed costs by marking prices up above marginal cost on its freight and passenger services. Ramsey pricing says the markups should be:","options":["Equal percentages on both services","Larger on the service with more elastic demand","Zero on both, with a government subsidy","Larger on the service with less elastic demand"],"answer":3,"explanation":"To raise the required revenue with the least distortion of quantities, the percentage markup should be inversely proportional to each service's demand elasticity (inverse elasticity rule).","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-393","question":"In a penalty kick, the kicker aims Left or Right and the goalkeeper dives Left or Right simultaneously. Scoring probabilities: (L, L) 0.4, (L, R) 0.9, (R, L) 0.8, (R, R) 0.3, where the first letter is the kicker's choice. In the mixed-strategy equilibrium, how often does the goalkeeper dive Left, and what is the scoring probability?","options":["60% of the time; 0.60","50% of the time; 0.60","60% of the time; 0.55","40% of the time; 0.65"],"answer":0,"explanation":"The goalkeeper mixes to make the kicker indifferent: 0.4q + 0.9(1 − q) = 0.8q + 0.3(1 − q) → q = 0.6. Scoring probability = 0.4 × 0.6 + 0.9 × 0.4 = 0.60. (The kicker aims Left 50% of the time.)","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-394","question":"Row chooses T, M or B; Column chooses L, C or R. Payoffs (Row, Column): T: (3,2) (2,1) (4,0); M: (1,1) (1,3) (2,2); B: (2,4) (3,2) (1,3). Applying iterated elimination of strictly dominated strategies, what outcome remains?","options":["(B, L) with payoffs (2, 4)","(T, L) with payoffs (3, 2)","(T, R) with payoffs (4, 0)","(M, C) with payoffs (1, 3)"],"answer":1,"explanation":"M is strictly dominated by T (3 > 1, 2 > 1, 4 > 2). Without M, Column's R is dominated by L (2 > 0, 4 > 3). Then C is dominated by L (2 > 1, 4 > 2), leaving L; Row's best reply to L is T (3 > 2).","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-395","question":"Two partners choose between a Cricket match and a Concert. Payoffs (A, B): both Cricket (3, 1); both Concert (1, 3); different choices (0, 0). How many Nash equilibria does this game have, counting mixed strategies?","options":["One: both choose Cricket","Two, both in pure strategies, and no mixed one","Three: two in pure strategies and one in mixed strategies","None, because their preferences conflict"],"answer":2,"explanation":"Both-Cricket and both-Concert are pure equilibria. In the mixed one, A plays Cricket with probability 3/4 and B plays Cricket with probability 1/4, each making the other indifferent.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-396","question":"Two firms each decide whether to build a large plant (Aggressive) or stay small (Soft). Payoffs (A, B): both Aggressive (−10, −10); A Aggressive/B Soft (8, 2); A Soft/B Aggressive (2, 8); both Soft (5, 5). What are the pure-strategy Nash equilibria?","options":["(Soft, Soft) only","(Aggressive, Aggressive) only","There is no pure-strategy equilibrium","(Aggressive, Soft) and (Soft, Aggressive)"],"answer":3,"explanation":"This is a game of Chicken: each wants to be aggressive only if the other backs down. (Soft, Soft) is not an equilibrium because each could gain 3 by switching to Aggressive.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-397","question":"Two suppliers can each invest in a Joint platform or go it Alone. Payoffs (A, B): both Joint (10, 10); A Joint/B Alone (0, 7); A Alone/B Joint (7, 0); both Alone (7, 7). Which statement is correct?","options":["Both (Joint, Joint) and (Alone, Alone) are equilibria; Joint is payoff-dominant but Alone is safer (risk-dominant)","Only (Joint, Joint) is an equilibrium","Going Alone is a dominant strategy for both","There is no pure-strategy equilibrium"],"answer":0,"explanation":"If the other goes Joint, Joint is best (10 > 7); if the other goes Alone, Alone is best (7 > 0). Alone guarantees 7 whatever happens, and becomes the better bet if the chance the other goes Joint is below 70%.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-398","question":"In an ultimatum game, a proposer offers a split of ₹100 (in whole rupees) and the responder can accept or reject; rejection gives both nothing. What is the subgame-perfect equilibrium when both care only about money, and what do experiments typically find?","options":["Offer ₹50 and accept, in theory and experiments alike","Offer ₹1 (or ₹0) and accept; in experiments, low offers (below about 20–30%) are often rejected","Offer ₹1 and reject, because it is unfair","No equilibrium exists because the game is sequential"],"answer":1,"explanation":"By backward induction a money-maximising responder accepts any positive amount, so the proposer offers the minimum. Real people often punish unfair offers, which is why typical offers are 40–50%.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-399","question":"In a centipede game, two players alternate choosing Take (ending the game) or Pass (which grows the pot) for a fixed, known number of rounds; taking always gives the mover slightly more than passing would if the other then takes. What does backward induction predict?","options":["Both pass until the last round","The second player takes at the last round","The first player takes at the first move","They split the final pot equally"],"answer":2,"explanation":"At the last node the mover takes; anticipating that, the previous mover takes; unravelling to the start, the first player takes immediately—even though passing would make both richer.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-400","question":"An entrant decides to Enter or Stay out; if it enters, the incumbent Fights or Accommodates. Payoffs (entrant, incumbent): Out (0, 100); Enter–Fight (−20, 30); Enter–Accommodate (40, 50). Before the game, the incumbent can sink ₹30 into capacity that raises its Fight payoff by ₹40 (Fight becomes 70 − 30 = 40 net; Accommodate becomes 50 − 30 = 20). Should it, and what happens?","options":["No: the threat is already credible","Yes, but the entrant still enters and the incumbent accommodates","No: sinking ₹30 always lowers its profit","Yes: Fight becomes credible (40 > 20), the entrant stays out, and the incumbent nets 70"],"answer":3,"explanation":"Without commitment, after entry the incumbent prefers Accommodate (50 > 30), so it gets 50. With capacity, Fight (40) beats Accommodate (20), so the entrant stays out and the incumbent earns 100 − 30 = 70 > 50.","difficulty":"very-hard","source":"Consulting · Strategy case interview"},
  {"id":"mgmt-business-economics-401","question":"Two firms play a pricing prisoner's dilemma exactly 10 times, and both know it. Under standard assumptions of rationality and common knowledge, what does backward induction predict?","options":["Both defect (price low) in every round","Both cooperate in rounds 1–9 and defect in round 10","Cooperation is sustained because of the threat of punishment","They alternate between cooperating and defecting"],"answer":0,"explanation":"In round 10 there is no future, so both defect; knowing that, round 9 is effectively the last, and so on back to round 1. Cooperation can arise with an uncertain or infinite horizon.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-402","question":"In a repeated pricing game, cooperation pays 6 a period each, deviating once pays 10, and the punishment (both defect forever) pays 2. Each period there is a 60% chance the game continues and the interest rate is 10%. Can grim-trigger cooperation be sustained?","options":["No: the effective discount factor 0.6 is below the required 0.8","Yes: the effective discount factor 0.545 exceeds the required 0.5","No: the discount factor 0.909 is irrelevant because the game may end","Yes: any positive continuation probability suffices"],"answer":1,"explanation":"Needed: δ ≥ (10 − 6)/(10 − 2) = 0.5. Effective δ = continuation probability/(1 + r) = 0.6/1.1 = 0.545 ≥ 0.5, so cooperation holds (just).","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-403","question":"Which statements are correct? I. Every dominant-strategy equilibrium is a Nash equilibrium. II. Every Nash equilibrium involves dominant strategies. III. A Nash equilibrium can be Pareto-inefficient.","options":["I, II and III","II and III only","I and III only","I only"],"answer":2,"explanation":"If each plays a dominant strategy, nobody can gain by deviating, so it is Nash; the reverse fails (e.g. coordination games). The prisoner's dilemma shows a Nash outcome that both would prefer to escape.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-404","question":"In a zero-sum game, Row's payoffs are: R1: (4, 2, 5); R2: (3, 1, 6); R3: (6, 3, 7) against Column's C1, C2, C3. Does a saddle point exist, and what is the value of the game?","options":["Yes: (R1, C3) with value 5","No: the players must mix","Yes: (R3, C3) with value 7","Yes: (R3, C2) with value 3"],"answer":3,"explanation":"Row's maximin: row minima are 2, 1, 3 → choose R3 (3). Column's minimax: column maxima are 6, 3, 7 → choose C2 (3). They coincide at 3, a saddle point.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-405","question":"Firm A chooses a Big or Small plant; B observes and then chooses Big or Small. Payoffs (A, B): Big–Big (2, 1); Big–Small (6, 3); Small–Big (3, 6); Small–Small (4, 4). What is the subgame-perfect outcome?","options":["A builds Big, B builds Small: (6, 3)","Both build Small: (4, 4)","A builds Small, B builds Big: (3, 6)","Both build Big: (2, 1)"],"answer":0,"explanation":"If A is Big, B prefers Small (3 > 1); if A is Small, B prefers Big (6 > 4). So A compares 6 (Big) with 3 (Small) and builds Big—a first-mover advantage.","difficulty":"hard","source":"Consulting · Strategy case interview"},
  {"id":"mgmt-business-economics-406","question":"Two parties bargain over ₹1 crore with alternating offers and no deadline. Each discounts a one-round delay by a factor of 0.8. In the Rubinstein equilibrium, what share does the first proposer get?","options":["50%, since both are equally patient","About 55.6% (₹0.556 crore), and the offer is accepted immediately","80%, the discount factor","About 44.4%, since the responder can wait"],"answer":1,"explanation":"Proposer's share = 1/(1 + δ) = 1/1.8 = 55.6%. The responder accepts δ/(1 + δ) = 44.4% because rejecting means waiting a round to propose and getting only the discounted equivalent.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-407","question":"In a sealed-bid second-price (Vickrey) auction for a licence worth ₹50 crore to a bidder, what should she bid?","options":["Somewhat below ₹50 crore to earn a surplus","Above ₹50 crore to make sure she wins","Exactly ₹50 crore, her true value, whatever others do","Her estimate of the second-highest value"],"answer":2,"explanation":"Her bid only determines whether she wins, not what she pays (the second-highest bid). Bidding true value ensures she wins exactly when the price is below her value—a weakly dominant strategy.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-408","question":"In a first-price sealed-bid auction, 4 risk-neutral bidders have private values drawn independently and uniformly between 0 and ₹100 lakh. In the symmetric equilibrium, what does a bidder with value ₹80 lakh bid?","options":["₹80 lakh","₹40 lakh","₹20 lakh","₹60 lakh"],"answer":3,"explanation":"With n bidders and uniform values, the equilibrium bid is (n − 1)/n × value = 3/4 × 80 = ₹60 lakh. Shading falls as competition grows; with 2 bidders it would be ₹40 lakh.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-409","question":"Several oil companies bid for drilling rights whose value is the same for all but uncertain; each has an unbiased estimate. Why might the winner overpay, and what should a rational bidder do?","options":["The winner is likely the one who most overestimated value; bidders should shade bids below their estimates","Winners overpay only if they are risk-loving; no adjustment needed","Because sealed bids are illegal for common-value goods","The winner always underpays, so bids should be raised"],"answer":0,"explanation":"In common-value auctions, winning is bad news about one's estimate (it was the highest). The winner's curse is avoided by conditioning bids on the event of winning, which means bidding less.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-410","question":"With risk-neutral bidders, independent private values from the same distribution and the highest bidder always winning, which statement follows from the revenue-equivalence theorem?","options":["First-price auctions always yield more revenue than second-price auctions","English, Dutch, first-price and second-price sealed-bid auctions yield the same expected revenue","Second-price auctions always yield more revenue","Expected revenue depends on whether bids are open or sealed"],"answer":1,"explanation":"Under these assumptions, bid shading in first-price formats exactly offsets paying the second price in the others, so expected revenue is equal. Risk aversion or correlated values break the result.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-411","question":"In an open ascending (English) auction with private values ₹90, ₹75, ₹60 and ₹40 lakh, who wins and at about what price?","options":["The ₹90 lakh bidder, at ₹90 lakh","The ₹75 lakh bidder, at ₹75 lakh","The ₹90 lakh bidder, at just above ₹75 lakh","The ₹90 lakh bidder, at about ₹66 lakh (the average)"],"answer":2,"explanation":"Bidding continues until the second-highest bidder drops out at ₹75 lakh, so the highest-value bidder wins at about the second-highest value—the same outcome as a Vickrey auction.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-412","question":"Employers pay ₹20 lakh to workers they believe are high-productivity and ₹10 lakh to others. Each year of an MBA-type credential costs a low-productivity worker ₹6 lakh and a high-productivity worker ₹3 lakh. For a separating equilibrium in which only high types acquire y years, what range of y works?","options":["Any y above 1.67 years","Between 3.33 and 6.67 years","Any y below 3.33 years","Between 1.67 and 3.33 years"],"answer":3,"explanation":"Low types must not mimic: 6y ≥ 10 → y ≥ 1.67. High types must find it worth it: 3y ≤ 10 → y ≤ 3.33. The signal works because it is cheaper for the high type, not because it raises productivity.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-413","question":"Fishermen share a lake. Each gains by catching more, but total catch above a sustainable level depletes the stock for all. Which game structure does this 'tragedy of the commons' most resemble, and what is a standard remedy?","options":["An n-player prisoner's dilemma; tradable quotas or defined property rights","A coordination game; a focal point","A zero-sum game; mixed strategies","A sequential game; first-mover advantage"],"answer":0,"explanation":"Each player's dominant strategy is to overfish though all would gain from restraint—the PD structure. Quotas, licences or ownership internalise the cost.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-414","question":"An auditor chooses whether to Inspect a firm (cost 5); the firm chooses Cheat or Comply. Cheating undetected gains the firm 10; if inspected, a cheater pays a fine of 40; complying gives 0. In the mixed-strategy equilibrium, how often does the auditor inspect?","options":["10% of the time","20% of the time","50% of the time","12.5% of the time"],"answer":1,"explanation":"The auditor's probability makes the FIRM indifferent: p(−40) + (1 − p)(10) = 0 → 50p = 10 → p = 0.2. A counter-intuitive feature: raising the fine lowers the inspection rate, not the cheating rate.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-415","question":"Four residents each have ₹100. Every rupee put into a common fund is doubled and shared equally among all four. What is each resident's dominant strategy, and what is the socially best outcome?","options":["Contribute everything; contribute nothing","Contribute ₹50; contribute ₹50","Contribute nothing; all contribute everything (each ends with ₹200)","Contribute nothing; that is also socially best"],"answer":2,"explanation":"Each rupee contributed returns only 2/4 = ₹0.50 to the contributor, so free-riding dominates. If all contribute ₹100, the fund of ₹800 gives each ₹200—a public-goods prisoner's dilemma.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-416","question":"Two firms first choose production capacities and then compete on price. What does theory (Kreps–Scheinkman) predict about the outcome?","options":["It always yields the Bertrand outcome, P = MC","It yields the monopoly price","No equilibrium exists","It resembles the Cournot outcome, with prices above marginal cost"],"answer":3,"explanation":"Capacity limits stop undercutting from capturing the whole market, softening price competition. With capacity chosen first, the equilibrium replicates Cournot quantities and prices.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-417","question":"In a repeated oligopoly where demand fluctuates and current demand is observed, when is tacit collusion hardest to sustain?","options":["In periods of unusually HIGH demand, because the one-time gain from undercutting is largest","In periods of low demand, because profits are low","When demand is stable","Only when the number of firms is two"],"answer":0,"explanation":"The gain from cheating depends on today's demand while the punishment depends on future average profits. In a boom the temptation is large, so price wars are predicted in booms (Rotemberg–Saloner).","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-418","question":"Which statement about strategic complements and substitutes is correct?","options":["Prices are strategic substitutes; quantities are complements","In Bertrand price competition, prices are strategic complements; in Cournot competition, quantities are strategic substitutes","Both prices and quantities are strategic complements","The distinction applies only to sequential games"],"answer":1,"explanation":"If a rival raises its price, your best response is to raise yours (upward-sloping reaction curves). If a rival raises its output, your best response is to cut yours (downward-sloping).","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-419","question":"Payoffs (A, B): A Up: B Left (4, 3), B Right (1, 2); A Down: B Left (3, 1), B Right (2, 4). How many pure-strategy Nash equilibria are there, and which?","options":["None; the game requires mixed strategies","Only (Up, Left)","Two: (Up, Left) and (Down, Right)","Only (Down, Right)"],"answer":2,"explanation":"Check each cell: (Up, Left): B prefers Left (3 > 2)? Yes; A prefers Up (4 > 3)? Yes—so (Up, Left) is an equilibrium. (Down, Right): A prefers Down (2 > 1), B prefers Right (4 > 1)—also an equilibrium. Neither player has a dominant strategy.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-420","question":"Two firms simultaneously decide whether to enter a market that can profitably hold only one. Payoffs: if both enter, each gets −5; if one enters, it gets 20 and the other 0; if neither, both 0. In the symmetric mixed-strategy equilibrium, what is each firm's probability of entering?","options":["50%","20%","25%","80%"],"answer":3,"explanation":"Indifference: entering gives p(−5) + (1 − p)(20) = 20 − 25p, staying out gives 0, so p = 0.8. Coordination failure (both entering) then occurs 64% of the time.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-421","question":"Which features made the 'tit-for-tat' strategy successful in Axelrod's repeated prisoner's dilemma tournaments?","options":["It is nice (never defects first), retaliatory, forgiving and clear","It always defects, so it is never exploited","It defects randomly to keep rivals guessing","It cooperates no matter what the rival does"],"answer":0,"explanation":"Tit-for-tat starts by cooperating, copies the rival's last move (punishing defection immediately), returns to cooperation once the rival does, and is easy for others to recognise.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-422","question":"In a Hawk–Dove game, the prize is worth V = 4 and the cost of losing a fight is C = 6. Hawks fight, Doves share or retreat. In the evolutionarily stable mixed population, what share are Hawks?","options":["50.0%","66.7%","40.0%","100.0%"],"answer":1,"explanation":"Hawk payoff vs Hawk = (V − C)/2 = −1, vs Dove = V = 4; Dove vs Hawk = 0, vs Dove = V/2 = 2. Equal payoffs: −h + 4(1 − h) = 2(1 − h) → h = V/C = 2/3.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-423","question":"In a zero-sum game Row's payoffs are: Top: (3, −1); Bottom: (−2, 4) against Column's Left and Right. What probability should Row place on Top, and what is the value of the game?","options":["0.5; value 1","0.6; value 0","0.6; value 1","0.4; value 2"],"answer":2,"explanation":"Row equalises Column's options: 3p − 2(1 − p) = −p + 4(1 − p) → 10p = 6 → p = 0.6. Value = 3(0.6) − 2(0.4) = 1.0.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-424","question":"Which statement summarises the folk theorem for infinitely repeated games?","options":["The one-shot Nash equilibrium is the only possible outcome","Cooperation is always the unique equilibrium","Repetition makes mixed strategies impossible","With sufficiently patient players, many outcomes—including full cooperation—can be sustained as equilibria by threats of future punishment"],"answer":3,"explanation":"If the discount factor is high enough, any feasible payoff that gives each player more than their minmax payoff can be supported. This explains both tacit collusion and why multiple equilibria arise.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-425","question":"Two firms play matching pennies sequentially: firm 1 chooses Heads or Tails, then firm 2 sees the choice and picks. Firm 2 wins if the choices DIFFER. What is the outcome, and what does it illustrate?","options":["Firm 2 always wins: a second-mover (information) advantage","Firm 1 always wins: a first-mover advantage","Each wins half the time, as in the simultaneous game","Neither can win, because there is no equilibrium"],"answer":0,"explanation":"Seeing firm 1's choice, firm 2 simply picks the opposite. In games where a rival benefits from reacting (e.g. fashion, undercutting), moving second can be an advantage.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-426","question":"Two pharma firms decide whether to run a costly R&D programme. Payoffs (₹ crore): both Invest (20, 20); A Invests, B doesn't (60, 10); A doesn't, B Invests (10, 60); neither (30, 30). What is the Nash equilibrium and is it efficient?","options":["Neither invests (30, 30); it is efficient","Both invest (20, 20); it is inefficient because both would be better off not investing","Only A invests (60, 10)","There are two pure equilibria (60, 10) and (10, 60)"],"answer":1,"explanation":"Invest is dominant for each (20 > 10 and 60 > 30), so both invest and earn 20, worse than 30 each from mutual restraint—an R&D prisoner's dilemma.","difficulty":"hard","source":"Consulting · Strategy case interview"},
  {"id":"mgmt-business-economics-427","question":"Two firms independently choose a meeting time 'sometime on Monday' with no communication, and both gain only if they pick the same time. Why might both pick 12 noon?","options":["It is the unique Nash equilibrium","It is a dominant strategy","It is a focal (Schelling) point—a salient choice that each expects the other to make","It is the mixed-strategy equilibrium"],"answer":2,"explanation":"Every common time is a Nash equilibrium. Salience from culture or convention helps players coordinate on one of many equilibria.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-428","question":"An army burns the bridges behind it before battle. In game-theoretic terms, what is the logic?","options":["It signals weakness, inviting attack","It lowers its own payoff in every outcome, so it is never rational","It converts a sequential game into a simultaneous one","It removes the option to retreat, making the threat to fight credible and possibly deterring the opponent"],"answer":3,"explanation":"Limiting one's own options can be valuable when it changes the rival's expectations; commitment works because it is visible and irreversible.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-429","question":"Payoffs (Row, Column): Row A: Col X (5, 5), Col Y (0, 6); Row B: Col X (6, 0), Col Y (1, 1). Which is correct?","options":["(B, Y) is the unique Nash equilibrium, though (A, X) gives both more","(A, X) is the unique Nash equilibrium","Both (A, X) and (B, Y) are Nash equilibria","There is no pure-strategy equilibrium"],"answer":0,"explanation":"B strictly dominates A for Row (6 > 5, 1 > 0) and Y strictly dominates X for Column (6 > 5, 1 > 0), so (B, Y) with (1, 1) is the unique equilibrium—a prisoner's dilemma.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-430","question":"A buyer values a business at ₹100 crore and the seller values it at ₹60 crore. The buyer has another target that would give it ₹20 crore of surplus. Using a simple Nash-bargaining split of the surplus above both parties' outside options, what price results?","options":["₹80 crore","₹70 crore","₹60 crore","₹90 crore"],"answer":1,"explanation":"Total surplus = 100 − 60 = 40, but the buyer can get 20 elsewhere, so only 20 is genuinely 'extra'; splitting it equally gives the buyer 20 + 10 = 30, i.e. a price of 100 − 30 = ₹70 crore. Ignoring the outside option gives ₹80 crore.","difficulty":"very-hard","source":"Consulting · Strategy case interview"},
  {"id":"mgmt-business-economics-431","question":"Two duopolists earn ₹1,012.5 each by colluding, ₹900 each in Cournot equilibrium and ₹1,139 by cheating once on a colluding rival. Using grim-trigger strategies (revert to Cournot forever), what minimum discount factor sustains collusion?","options":["0.471","0.111","0.529","0.500"],"answer":2,"explanation":"δ ≥ (cheat − collude)/(cheat − punish) = (1,139 − 1,012.5)/(1,139 − 900) = 0.529. More patient firms (higher δ) can sustain the cartel.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-432","question":"In a mixed-strategy Nash equilibrium, a player randomises between two actions. Which statement must be true?","options":["Each action is chosen with probability 0.5","Her mixing probabilities are chosen to maximise her own expected payoff directly","Her opponent must be playing a pure strategy","Both actions give her the same expected payoff, given the opponent's mixed strategy"],"answer":3,"explanation":"A player is only willing to mix if she is indifferent. Her probabilities are pinned down by the need to keep the OTHER player indifferent, not by her own payoffs.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-433","question":"In a closed economy, the MPC out of disposable income is 0.75 and there is a proportional income tax of 20%. If the government cuts LUMP-SUM taxes by ₹40 crore, by how much does equilibrium income rise?","options":["₹75 crore","₹120 crore","₹100 crore","₹30 crore"],"answer":0,"explanation":"Expenditure multiplier = 1/[1 − 0.75(1 − 0.2)] = 2.5; a lump-sum tax cut first raises spending by 0.75 × 40 = 30, so ΔY = 30 × 2.5 = ₹75 crore. Ignoring the proportional tax gives ₹120 crore.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-434","question":"With an MPC of 0.8 and lump-sum taxes, compare raising government purchases by ₹100 crore with raising transfer payments by ₹100 crore.","options":["Both raise income by ₹500 crore","Purchases raise income by ₹500 crore; transfers by ₹400 crore","Purchases ₹400 crore; transfers ₹500 crore","Purchases ₹500 crore; transfers ₹80 crore"],"answer":1,"explanation":"Purchases enter spending fully: 100 × 1/(1 − 0.8) = 500. Transfers first raise disposable income, of which only 80% is spent: 100 × 0.8/0.2 = 400.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-435","question":"An economy has an MPC of 0.75 and a 20% proportional income tax (no other leakages). Government purchases rise by ₹100 crore. By how much does the budget deficit change once income has fully adjusted?","options":["It rises by ₹100 crore","It is unchanged, because extra taxes pay for the spending","It rises by ₹50 crore","It rises by ₹20 crore"],"answer":2,"explanation":"Multiplier = 1/(1 − 0.75 × 0.8) = 2.5, so Y rises ₹250 crore and tax revenue by 0.2 × 250 = ₹50 crore. The deficit rises by 100 − 50 = ₹50 crore: the spending partly finances itself.","difficulty":"very-hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-436","question":"Okun's law for an economy says each 1 percentage point of unemployment above the natural rate is associated with output 2% below potential. Natural unemployment is 5% and actual unemployment 7%. Potential GDP is ₹300 lakh crore. Roughly how large is the output gap?","options":["About ₹6 lakh crore (2% below potential)","About ₹21 lakh crore (7% below potential)","About ₹4 lakh crore","About ₹12 lakh crore (4% below potential)"],"answer":3,"explanation":"Unemployment is 2 points above natural, so output is about 2 × 2 = 4% below potential: 0.04 × 300 = ₹12 lakh crore.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-437","question":"Potential output grows at 6% a year. Okun's coefficient is 2 (each 2% of growth shortfall raises unemployment by 1 point). If actual growth is 3% this year, what happens to unemployment?","options":["It rises by about 1.5 percentage points","It rises by about 3 percentage points","It falls by about 1.5 percentage points","It rises by about 6 percentage points"],"answer":0,"explanation":"Δu ≈ −(g − g_potential)/2 = −(3 − 6)/2 = +1.5 points. Growth merely positive is not enough to stop unemployment rising; it must keep pace with potential.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-438","question":"Inflation follows π = πᵉ − 0.5(u − uₙ). Expected inflation is 4%, the natural rate of unemployment is 5% and actual unemployment is 7%. What is inflation, and what happens to it next year if expectations adapt (πᵉ = last year's π) and unemployment stays at 7%?","options":["5% now, then 6%","3% now, then 2%","3% now, and stays at 3%","4% now, then 3%"],"answer":1,"explanation":"π = 4 − 0.5 × 2 = 3%. Next year πᵉ = 3, so π = 3 − 1 = 2%. Keeping unemployment above the natural rate makes inflation keep falling (accelerationist view).","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-439","question":"An economy's sacrifice ratio is estimated at 2.5 (percentage points of a year's GDP lost per point of inflation reduction). The central bank wants to cut inflation from 9% to 5%. What cumulative output loss should it expect?","options":["About 2.5% of GDP","About 4% of GDP","About 10% of a year's GDP","About 1.6% of GDP"],"answer":2,"explanation":"Loss = sacrifice ratio × reduction in inflation = 2.5 × 4 = 10 percentage-point-years of GDP, typically spread over several years. Credible policy can lower the ratio.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-440","question":"A sharp rise in global oil prices shifts the short-run aggregate supply curve left. With no policy response, what are the short-run effects on the price level and real output?","options":["Both rise","Price level falls and output rises","Price level rises and output is unchanged","Price level rises and real output falls"],"answer":3,"explanation":"A leftward SRAS shift along a fixed AD curve raises prices and lowers output—stagflation. Policy then faces a trade-off between fighting inflation and supporting output.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-441","question":"Starting at potential output, a burst of export demand shifts AD right. Nominal wages are fixed by contracts in the short run but adjust over time. What happens in the short run and the long run?","options":["SR: higher prices and output above potential; LR: wages rise, SRAS shifts left, output returns to potential at a higher price level","SR and LR: permanently higher output and prices","SR: no change; LR: higher output","SR: higher output; LR: lower prices and higher output"],"answer":0,"explanation":"Sticky wages let firms expand output as prices rise. As contracts reset, higher wages shift SRAS left until output is back at potential; the long-run effect is only on the price level.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-442","question":"The government cuts taxes by ₹1 lakh crore this year, financed by bonds to be repaid with future taxes, and keeps spending unchanged. Under Ricardian equivalence, what happens?","options":["Consumption rises by MPC × ₹1 lakh crore","Households save the whole tax cut to pay future taxes, so consumption and aggregate demand are unchanged","Interest rates rise and crowd out investment","Output rises by the tax multiplier"],"answer":1,"explanation":"Forward-looking households see that a debt-financed tax cut today implies equal-PV tax rises later, so lifetime wealth is unchanged. Private saving rises one-for-one with government dissaving.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-443","question":"Under the permanent income hypothesis, which tax change has the largest effect on current consumption?","options":["A one-time ₹10,000 tax rebate","A one-time ₹20,000 rebate announced to be reversed next year","A permanent ₹10,000 annual tax cut","A temporary tax cut lasting six months"],"answer":2,"explanation":"Consumption depends on permanent (long-run average) income. A permanent cut raises permanent income by the full amount each year, while temporary rebates change it only slightly and are mostly saved.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-444","question":"A worker expects to earn ₹10 lakh a year for 40 working years, then retire for 20 years with no other income. With a zero real interest rate and a wish for equal consumption every year, how much does she consume and save each working year?","options":["Consume ₹10 lakh, save nothing","Consume ₹5 lakh, save ₹5 lakh","Consume ₹8 lakh, save ₹2 lakh","Consume ₹6.67 lakh, save ₹3.33 lakh"],"answer":3,"explanation":"Lifetime income = 40 × 10 = ₹400 lakh over 60 years → ₹6.67 lakh a year. She saves ₹3.33 lakh in each working year and dissaves ₹6.67 lakh in each retired year.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-445","question":"Imported smartphones become much more expensive while domestically produced goods' prices are unchanged. How do the CPI and the GDP deflator respond?","options":["The CPI rises; the GDP deflator does not","The GDP deflator rises; the CPI does not","Both rise equally","Neither changes, because imports are excluded from both"],"answer":0,"explanation":"The CPI covers goods households buy, including imports. The GDP deflator covers only domestically produced output, so import prices do not enter it.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-446","question":"An economy produces only apples and oranges. Year 1: 100 apples at ₹2 and 50 oranges at ₹4. Year 2: 110 apples at ₹3 and 60 oranges at ₹4. Using year 1 as the base, what are real GDP growth and the year-2 GDP deflator?","options":["42.5% and 123.9","15.0% and 123.9","15.0% and 142.5","10.0% and 123.9"],"answer":1,"explanation":"Real GDP: year 1 = ₹400, year 2 at year-1 prices = ₹460 → growth 15.0%. Nominal year 2 = ₹570; deflator = 570/460 × 100 = 123.9. Nominal growth (42.5%) mixes price and quantity.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-447","question":"In a year, private saving is ₹200 lakh crore, private investment ₹180 lakh crore and the government budget deficit ₹50 lakh crore. What must the current account balance be?","options":["A surplus of ₹20 lakh crore","A surplus of ₹70 lakh crore","A deficit of ₹30 lakh crore","A deficit of ₹50 lakh crore"],"answer":2,"explanation":"From national accounts, (S − I) + (T − G) = CA: (200 − 180) + (−50) = −30. The country borrows ₹30 lakh crore from abroad because private surplus doesn't cover the fiscal deficit.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-448","question":"In a Solow model with y = k^0.5, the saving rate is 20%, population growth 2% and depreciation 3% (no technological progress). What are steady-state capital and output per worker?","options":["k* = 4, y* = 2","k* = 16, y* = 3.2","k* = 64, y* = 8","k* = 16, y* = 4"],"answer":3,"explanation":"Steady state: s·y = (n + δ)k → 0.2√k = 0.05k → √k = 4 → k* = 16, y* = 4. Consumption per worker = 0.8 × 4 = 3.2.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-449","question":"In a Solow model with Cobb–Douglas output per worker y = k^α (α = 0.3), what saving rate maximises steady-state consumption per worker (the Golden Rule), and what condition defines it?","options":["30%; the marginal product of capital equals n + δ","50%; output per worker is maximised","30%; the saving rate equals population growth","100%; capital per worker is maximised"],"answer":0,"explanation":"Golden Rule: choose s so that MPK = n + δ at the steady state. With Cobb–Douglas, this implies capital's income share, α = 30%, is the golden saving rate. More saving raises output but lowers consumption.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-450","question":"Country A's real GDP per capita grows 7% a year and country B's 2%. Roughly how long does each take to double, and how many times larger will A's per-capita GDP be after 70 years relative to its start?","options":["A: 10 years, B: 35 years; about 7 times","A: 10 years, B: 35 years; about 114 times","A: 7 years, B: 2 years; about 70 times","A: 10 years, B: 35 years; about 4.9 times"],"answer":1,"explanation":"Rule of 70: doubling time ≈ 70/g: 10 years for A, 35 for B. Exactly, 1.07⁷⁰ ≈ 114 (the rule's seven doublings suggest about 128). Small growth gaps compound into huge income differences.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-451","question":"A country has a working-age population of 70 crore, of whom 46 crore are employed and 4 crore are unemployed and actively seeking work. What are the unemployment rate and labour-force participation rate?","options":["5.7% and 71.4%","8.0% and 65.7%","8.0% and 71.4%","8.7% and 71.4%"],"answer":2,"explanation":"Labour force = 46 + 4 = 50 crore; unemployment rate = 4/50 = 8%; participation = 50/70 = 71.4%. Dividing unemployed by the working-age population (5.7%) is the trap.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-452","question":"In a recession, some unemployed people stop searching because they believe no jobs are available. What happens to the measured unemployment rate as a result?","options":["It rises, because they are still jobless","It is unchanged, because they were never counted","It rises, because the participation rate rises","It falls, because discouraged workers leave the labour force"],"answer":3,"explanation":"Only active job-seekers count as unemployed. When they stop searching, both the number unemployed and the labour force shrink, lowering the measured rate and understating labour-market slack.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-453","question":"The natural rate of unemployment consists of:","options":["Frictional and structural unemployment","Cyclical and frictional unemployment","Cyclical unemployment only","Structural and cyclical unemployment"],"answer":0,"explanation":"At the natural rate, cyclical unemployment is zero; what remains is frictional (job search) and structural (skills or location mismatch) unemployment.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-454","question":"Which effects explain why the aggregate demand curve slopes downward? I. Wealth (real-balance) effect. II. Interest-rate effect. III. Exchange-rate (open-economy) effect. IV. Substitution between goods within a market.","options":["I, II, III and IV","I, II and III only","I and II only","II, III and IV only"],"answer":1,"explanation":"A lower price level raises real money wealth, lowers interest rates (boosting investment) and makes exports cheaper. Within-market substitution explains a single good's demand curve, not aggregate demand.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-455","question":"An economy has C = 200 + 0.75(Y − T), I = 200 − 25r, G = 100, T = 100 and real money demand L = Y − 100r with real money supply 1,000. If G rises by 50, what happens to equilibrium income and the interest rate?","options":["Y rises from 1,350 to 1,550; r unchanged","Y rises from 1,350 to 1,400; r rises from 3.5 to 4.0","Y rises from 1,350 to 1,450; r rises from 3.5 to 4.5","Y rises from 1,350 to 1,450; r unchanged"],"answer":2,"explanation":"IS: Y = 1,700 − 100r; LM: Y = 1,000 + 100r → Y = 1,350, r = 3.5. With G + 50, IS: Y = 1,900 − 100r → Y = 1,450, r = 4.5. Income rises 100, not the simple-multiplier 200, because higher r crowds out investment.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-456","question":"In the same economy (IS: Y = 1,700 − 100r; LM from money demand L = Y − 100r with real money supply 1,000), the central bank raises the real money supply to 1,100. What are the new income and interest rate?","options":["Y = 1,450 and r = 3.5","Y = 1,400 and r = 3.5","Y = 1,100 and r = 6.0","Y = 1,400 and r = 3.0"],"answer":3,"explanation":"New LM: Y = 1,100 + 100r. With IS Y = 1,700 − 100r: 2Y = 2,800 → Y = 1,400, r = 3.0. Lower interest rates stimulate investment, raising income by 50.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-457","question":"According to the classical dichotomy, a permanent 10% increase in the money supply in the long run:","options":["Raises the price level by about 10% and leaves real output and real interest rates unchanged","Raises real output by 10%","Lowers real interest rates permanently","Has no effect on prices"],"answer":0,"explanation":"Long-run money neutrality: nominal variables scale with money, while real variables are determined by real factors such as technology and preferences.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-458","question":"If investment becomes much more sensitive to interest rates (a flatter IS curve), how do the effects of monetary and fiscal policy change in the IS–LM model?","options":["Both become more powerful","Monetary policy becomes more powerful; fiscal policy suffers more crowding out","Fiscal policy becomes more powerful; monetary less","Neither changes, since only the LM curve matters"],"answer":1,"explanation":"A flat IS means a given fall in r (from monetary easing) produces a big rise in investment and income. The same sensitivity means fiscal expansion's rise in r crowds out more investment.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-459","question":"If money demand is completely insensitive to the interest rate, so the LM curve is vertical, what is the effect of a debt-financed rise in government spending?","options":["Income rises by the full simple multiplier","Income rises and the interest rate is unchanged","Income is unchanged; the interest rate rises until private investment falls by the full amount (complete crowding out)","Both income and interest rate fall"],"answer":2,"explanation":"With a vertical LM, income is pinned down by the money supply. A rightward IS shift only raises r, displacing private spending one-for-one—the classical case.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-460","question":"Which of the following is INCLUDED in India's GDP?","options":["Unpaid household cooking and cleaning","The sale of a second-hand car between two individuals","Interest received on government bonds by households","The imputed rent of owner-occupied houses"],"answer":3,"explanation":"National accounts impute a rental value for owner-occupied housing to treat owners and renters alike. Unpaid household services, transfers of existing assets and government interest (a transfer) are excluded.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-461","question":"An economy's gross value added at basic prices is ₹200 lakh crore. Product taxes are ₹25 lakh crore and product subsidies ₹5 lakh crore. What is GDP at market prices?","options":["₹220 lakh crore","₹230 lakh crore","₹225 lakh crore","₹180 lakh crore"],"answer":0,"explanation":"GDP at market prices = GVA at basic prices + product taxes − product subsidies = 200 + 25 − 5 = ₹220 lakh crore. Adding subsidies gives ₹230 lakh crore.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-462","question":"In a closed economy without taxes, the MPC is 0.8 and investment also rises with income, with a marginal propensity to invest of 0.1. What is the autonomous expenditure multiplier?","options":["5","10","4.5","9"],"answer":1,"explanation":"Induced spending per rupee of income = 0.8 + 0.1 = 0.9, so the multiplier = 1/(1 − 0.9) = 10. Ignoring induced investment gives 5.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-463","question":"Equilibrium income is ₹1,600 crore while full-employment income is ₹1,500 crore. The MPC is 0.75 and taxes are lump-sum. By how much must lump-sum taxes rise to close the inflationary gap?","options":["₹25 crore","₹100 crore","₹33.33 crore","₹75 crore"],"answer":2,"explanation":"The tax multiplier is −MPC/(1 − MPC) = −3, so ΔT = 100/3 = ₹33.33 crore. ₹25 crore is the cut in government purchases (multiplier 4) that would do the same job.","difficulty":"very-hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-464","question":"Assertion (A): When investment depends positively on income, an attempt by households to save more can lower the economy's TOTAL saving. Reason (R): Higher desired saving cuts income, which in turn cuts induced investment, and in equilibrium saving equals investment.","options":["Both are true, but R does not explain A","A is false: total saving is always unchanged","A is true, R is false","Both A and R are true, and R explains A"],"answer":3,"explanation":"In a closed economy without government, equilibrium saving equals investment. If investment falls with income, the fall in income caused by thrift lowers investment and hence realised saving.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-465","question":"In a simple Keynesian economy, planned spending is less than output at the current level of income. What happens next?","options":["Unplanned inventories build up, so firms cut production and income falls toward equilibrium","Firms raise prices because demand is excessive","Inventories fall, so firms expand output","Nothing; the economy is already in equilibrium"],"answer":0,"explanation":"Output above planned spending means unsold goods pile up as unplanned inventory investment. Firms respond by cutting output until planned expenditure equals income.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-466","question":"What does 'hysteresis' in unemployment mean?","options":["Unemployment always returns quickly to its natural rate","A long period of high unemployment can raise the natural rate itself, as skills erode and the long-term unemployed become detached","Inflation and unemployment always move together","The natural rate is unaffected by actual unemployment"],"answer":1,"explanation":"Prolonged recessions can permanently damage employability and labour-force attachment, so the natural rate depends on the path of actual unemployment.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-467","question":"Which of the following is generally considered a LEADING indicator of the business cycle?","options":["The unemployment rate","The average duration of unemployment","New orders for capital goods","The consumer price index for services"],"answer":2,"explanation":"New orders signal future production. Unemployment and its duration tend to lag the cycle; services inflation is also a lagging indicator.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-468","question":"Why might small 'menu costs' of changing prices lead to large fluctuations in output, according to New Keynesian economics?","options":["Menu costs force firms to change prices every day","Menu costs make money neutral in the short run","Menu costs only affect restaurants","Firms rationally leave prices unchanged after small demand shocks, so output absorbs the shock, and this price stickiness has large aggregate effects"],"answer":3,"explanation":"For an individual firm the private loss from not adjusting is small (second-order), but aggregate demand externalities make the social cost of widespread price stickiness large.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-469","question":"Under rational expectations and fully flexible prices, what is the effect of a fully anticipated expansionary monetary policy on real output?","options":["None: it raises prices only (the policy-ineffectiveness proposition)","A large, lasting rise in output","A temporary rise in output, then a fall below potential","A fall in prices and a rise in output"],"answer":0,"explanation":"If agents anticipate the policy, wages and prices adjust immediately, so real variables are unaffected. Only unanticipated policy can move output in this framework.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-470","question":"What is the Lucas critique of policy evaluation?","options":["Fiscal policy is always ineffective","Estimated relationships (e.g. the Phillips curve) may change when policy changes, because people's expectations and behaviour respond to the new policy","Econometric models should never be used","Monetary policy affects only nominal variables"],"answer":1,"explanation":"Parameters estimated under one policy regime embed expectations formed under that regime; using them to predict outcomes under a new regime can be badly misleading.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-471","question":"After an adverse supply shock, the central bank chooses to 'accommodate' it by expanding aggregate demand. What are the consequences compared with not accommodating?","options":["Output falls more and prices rise less","Both output and prices return immediately to their original levels","Output falls less, but the price level rises more","Prices fall and output rises above potential"],"answer":2,"explanation":"Shifting AD right offsets the output loss from the leftward SRAS shift but adds to the price increase, risking higher inflation expectations.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-472","question":"Which policy is most clearly a supply-side measure intended to shift long-run aggregate supply to the right?","options":["A temporary increase in government purchases","A cut in the policy repo rate","A one-time cash transfer to households","Reforms that make it easier to start businesses and improve workforce skills"],"answer":3,"explanation":"Long-run aggregate supply depends on productive capacity: labour, capital, technology and institutions. Spending, rate cuts and transfers act mainly on aggregate demand.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-473","question":"A customer deposits ₹1,000 of new cash in a bank. All banks keep exactly the required reserve ratio of 10%, lend the rest, and all loans are redeposited (no cash leakage). What are the maximum increase in total deposits and in total bank loans?","options":["Deposits ₹10,000; loans ₹9,000","Deposits ₹9,000; loans ₹9,000","Deposits ₹10,000; loans ₹10,000","Deposits ₹1,000; loans ₹900"],"answer":0,"explanation":"Deposit multiplier = 1/0.10 = 10, so deposits can rise to ₹10,000. ₹1,000 of that is backed by the original cash held as reserves, so new loans total ₹9,000.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-474","question":"Banks must hold 10% reserves but, being cautious, hold an extra 5% of deposits as excess reserves. The public holds no extra cash. By how much does the maximum deposit multiplier fall?","options":["From 10 to 9.5","From 10 to 6.67","From 10 to 5","It does not change, since only required reserves matter"],"answer":1,"explanation":"Multiplier = 1/(required + excess) = 1/0.15 = 6.67 instead of 1/0.10 = 10. Banks' willingness to lend, not just regulation, limits money creation.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-475","question":"According to the Fisher effect, if expected inflation rises permanently from 4% to 6% while the real interest rate stays at 2%, what happens to nominal interest rates in the long run?","options":["They stay at 6%","They fall, because real rates are unchanged","They rise by about 2 percentage points, to about 8%","They rise to about 12%"],"answer":2,"explanation":"i ≈ r + πᵉ: 2% + 6% = 8% versus 6% before. Nominal rates move one-for-one with expected inflation in the long run.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-476","question":"Interest income is taxed at 25% on its NOMINAL amount. Expected inflation rises by 2 percentage points. By how much must the nominal interest rate rise to keep savers' after-tax real return unchanged?","options":["2.00 percentage points","1.50 percentage points","2.50 percentage points","About 2.67 percentage points"],"answer":3,"explanation":"After-tax real return = i(1 − t) − π. Holding it constant requires Δi(0.75) = Δπ = 2, so Δi = 2/0.75 = 2.67 points (the Darby effect).","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-477","question":"Reserve money (currency plus bank reserves, paying no interest) is ₹40 lakh crore. Inflation runs steadily at 5%. Approximately what is the annual 'inflation tax' on money holders?","options":["About ₹2 lakh crore","About ₹40 lakh crore","About ₹0.2 lakh crore","About ₹8 lakh crore"],"answer":0,"explanation":"Inflation erodes the real value of non-interest-bearing money: 5% × ₹40 lakh crore ≈ ₹2 lakh crore a year, a revenue source for the issuer (part of seigniorage).","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-478","question":"Money supply grows 8% a year, velocity rises 1% a year and real output grows 6% a year. Using the quantity equation in growth-rate form, what is the approximate inflation rate?","options":["2%","3%","1%","8%"],"answer":1,"explanation":"%ΔM + %ΔV ≈ %ΔP + %ΔY → 8 + 1 = π + 6 → π ≈ 3%. Ignoring the velocity change gives 2%.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-479","question":"Which of these is a cost even of fully ANTICIPATED, steady inflation?","options":["Arbitrary redistribution from lenders to borrowers","Uncertainty about future real returns","Shoe-leather costs from holding less cash and menu costs of repricing","Unexpected falls in real wages"],"answer":2,"explanation":"Redistribution and uncertainty arise from UNANTICIPATED inflation. Even predictable inflation makes people economise on money balances and forces firms to reprice.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-480","question":"A bank lends at a fixed 9% for a year, expecting 4% inflation. Inflation turns out to be 7%. What real return did the bank expect, and what did it earn?","options":["Expected 5.00%; earned 2.00%","Expected 1.87%; earned 4.81%","Expected 4.81%; earned 7.00%","Expected 4.81%; earned 1.87%"],"answer":3,"explanation":"Real return = 1.09/(1 + π) − 1: expected 1.09/1.04 − 1 = 4.81%; actual 1.09/1.07 − 1 = 1.87%. Unexpected inflation transfers wealth from lender to borrower.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-481","question":"A government's debt is 80% of GDP. The nominal interest rate on its debt is 7% and nominal GDP grows 10% a year. What primary balance (as % of GDP) keeps the debt-to-GDP ratio constant?","options":["A primary DEFICIT of about 2.18% of GDP","A primary SURPLUS of about 2.18% of GDP","A primary surplus of 2.40% of GDP","A balanced primary budget is required"],"answer":0,"explanation":"Debt-stabilising primary balance = (r − g)/(1 + g) × d = (0.07 − 0.10)/1.10 × 0.80 = −2.18%. With growth above the interest rate, the government can run a primary deficit of about 2.18% and keep the ratio stable.","difficulty":"very-hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-482","question":"Why are fiscal multipliers generally thought to be LARGER when the central bank's policy rate is stuck at its lower bound?","options":["Taxes are higher at the lower bound","The central bank does not raise rates in response, so there is little interest-rate crowding out","Imports fall to zero","Households become Ricardian"],"answer":1,"explanation":"Normally a fiscal expansion is partly offset as rates rise. At the lower bound the central bank wants to ease anyway, so it lets the fiscal boost work fully.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-483","question":"Under the RBI's liquidity adjustment framework, how are the Marginal Standing Facility (MSF) rate and the Standing Deposit Facility (SDF) rate positioned relative to the repo rate?","options":["MSF below repo; SDF above repo","Both equal to the repo rate","MSF above repo (ceiling of the corridor); SDF below repo (floor)","MSF is the floor and SDF the ceiling"],"answer":2,"explanation":"Banks can borrow overnight at the MSF (a penal rate above repo) and park surplus funds at the SDF (below repo), so the overnight call rate trades within this corridor around the policy repo rate.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-484","question":"Banks' net demand and time liabilities total ₹200 lakh crore. If the central bank cuts the cash reserve ratio by 50 basis points, how much primary liquidity is released into the banking system?","options":["₹10 lakh crore","₹0.1 lakh crore","₹50 lakh crore","₹1 lakh crore"],"answer":3,"explanation":"Released reserves = 0.5% × 200 = ₹1 lakh crore. The eventual money-supply effect can be larger through the multiplier.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-485","question":"To stop the rupee from appreciating, the RBI buys dollars from banks and simultaneously sells government securities of an equal amount. What is the purpose of the second step?","options":["To sterilise the intervention by draining the rupee liquidity created by the dollar purchase, keeping money supply and rates unchanged","To push interest rates down","To raise the money supply further","To finance the government deficit"],"answer":0,"explanation":"Buying dollars injects rupees (reserve money rises). Selling bonds absorbs them, so foreign-exchange intervention does not loosen domestic monetary conditions.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-486","question":"Through which channel is quantitative easing (large-scale central bank purchases of long-term bonds) mainly expected to stimulate the economy?","options":["Directly raising the short-term policy rate","Lowering long-term yields and term premia, raising asset prices and easing financial conditions","Increasing the government's tax revenue","Raising banks' reserve requirements"],"answer":1,"explanation":"With short rates near zero, buying long bonds pushes down long-term yields (portfolio balance), supports asset prices and signals that policy will stay easy.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-487","question":"A central bank announces it will keep its policy rate low 'for an extended period, until inflation sustainably returns to target'. What is this tool, and how does it work?","options":["Open market operations: it injects reserves directly","Moral suasion: it persuades banks to lend","Forward guidance: it lowers expected future short rates and hence long-term rates today","Yield-curve control: it fixes the 10-year yield"],"answer":2,"explanation":"Long rates reflect expected future short rates. Credible commitments about the policy path move those expectations and ease financial conditions without changing the current rate.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-488","question":"In India's money-supply measures, broad money (M3) differs from narrow money (M1) mainly by including:","options":["Currency with the public","Demand deposits with banks","Post office savings only","Time deposits with the banking system"],"answer":3,"explanation":"M1 = currency with the public + demand deposits + other deposits with the RBI. M3 = M1 + time deposits with the banking system.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-489","question":"Which of the following is a component of reserve money (M0) in India?","options":["Bankers' deposits with the RBI","Time deposits with commercial banks","Demand deposits of the public with banks","Government securities held by banks"],"answer":0,"explanation":"Reserve money = currency in circulation + bankers' deposits with the RBI + other deposits with the RBI. Commercial bank deposits are part of broad money, not reserve money.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-490","question":"Assertion (A): When a commercial bank makes a new loan, it typically creates a new deposit in the borrower's account at the same time. Reason (R): Banks must first collect an equal amount of new deposits before they can lend.","options":["Both A and R are true, and R explains A","A is true, but R is false","Both are true, but R does not explain A","A is false, R is true"],"answer":1,"explanation":"Modern banks create broad money by lending: the loan is matched by a new deposit. Lending is constrained by capital, profitability, regulation and the central bank's rate setting, not by prior deposit collection.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-491","question":"A 10-year nominal government bond yields 7.2% and a 10-year inflation-indexed bond yields 2.0% (real). Ignoring risk premia, what average annual inflation does the market expect?","options":["About 9.20%","About 3.60%","About 5.10%","About 2.00%"],"answer":2,"explanation":"Breakeven inflation: (1.072/1.02) − 1 ≈ 5.10% (≈ 7.2 − 2.0 = 5.2%). It also contains inflation-risk and liquidity premia in practice.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-492","question":"Why do central banks monitor 'core' inflation, which excludes food and fuel prices?","options":["Food and fuel are not part of the consumer basket","Core inflation is always higher than headline inflation","Only core inflation affects household welfare","Food and fuel prices are volatile and often driven by supply shocks, so core inflation better shows underlying, persistent inflation pressure"],"answer":3,"explanation":"Transitory supply shocks to food and energy can swing headline inflation; core is a better guide to demand-driven trend inflation, though persistent food inflation can still feed expectations.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-493","question":"Inflation falls from 8% to 3% over two years. This is best described as:","options":["Disinflation: prices are still rising, but more slowly","Deflation: the price level is falling","Stagflation: prices fall with rising unemployment","Reflation: prices are recovering"],"answer":0,"explanation":"Deflation means a falling price level (negative inflation). A fall in a still-positive inflation rate is disinflation.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-494","question":"According to Irving Fisher's debt-deflation theory, why can falling prices deepen a recession?","options":["Deflation raises real wages, increasing consumption","Deflation raises the real burden of nominal debts, forcing distressed borrowers to cut spending and sell assets, pushing prices down further","Deflation lowers real interest rates, boosting investment","Deflation makes exports less competitive"],"answer":1,"explanation":"Debts fixed in nominal terms become heavier as prices fall; fire sales and spending cuts reinforce the deflation—a self-feeding spiral.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-495","question":"What is 'fiscal dominance' in monetary economics?","options":["Fiscal policy being more effective than monetary policy","The central bank controlling the government budget","A situation where government financing needs force the central bank to keep rates low or monetise deficits, undermining its inflation goal","Government spending exceeding private spending"],"answer":2,"explanation":"When debt is high and the central bank accommodates it (low rates, purchases of government bonds), monetary policy serves debt sustainability rather than price stability.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-496","question":"Workers demand higher wages to keep up with rising prices, firms pass the higher wage costs on as higher prices, and the cycle repeats. This is called:","options":["Demand-pull inflation","The paradox of thrift","Crowding out","A wage–price spiral"],"answer":3,"explanation":"A wage–price spiral is self-reinforcing cost-push inflation, sustained when inflation expectations become embedded in wage settlements.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-497","question":"Why can a credible, independent central bank reduce inflation at a lower cost in lost output than a central bank with low credibility?","options":["Credible announcements lower inflation expectations quickly, so wages and prices adjust without a long period of high unemployment","Independent central banks can print less money","Credibility raises potential output permanently","Credible central banks can ignore the Phillips curve"],"answer":0,"explanation":"If people believe the disinflation, expected inflation falls and the short-run Phillips curve shifts down quickly; the sacrifice ratio falls.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-498","question":"Kydland and Prescott's time-inconsistency argument implies that a policymaker with discretion will tend to produce:","options":["Lower inflation and higher output","Higher inflation without lower unemployment, because the public anticipates the temptation to inflate","No inflation at all","Higher output permanently"],"answer":1,"explanation":"Once expectations are set, the policymaker is tempted to create surprise inflation; rational agents foresee this, so expected and actual inflation end up higher with no output gain. Rules or independence help.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-499","question":"Which statement about the lags of fiscal and monetary policy is generally correct?","options":["Both have negligible lags","Monetary policy has a longer inside lag","Fiscal policy usually has a longer inside (decision) lag; monetary policy usually has a longer outside (effect) lag","Fiscal policy affects the economy only after several years"],"answer":2,"explanation":"Budget changes need legislative approval (long inside lag) but act quickly once spent; rate changes are decided quickly but take many months to affect spending and inflation.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-500","question":"Under the Baumol–Tobin model, a person spends ₹12 lakh a year evenly, each trip to withdraw cash costs ₹100, and the interest rate on deposits is 6%. What is her optimal average cash holding?","options":["₹63,246","₹44,721","₹50,000","₹31,623"],"answer":3,"explanation":"Optimal withdrawal = √(2YF/i) = √(2 × 12,00,000 × 100/0.06) = ₹63,246; average holding is half of that: ₹31,623. Money demand rises with the square root of spending and falls with the interest rate.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-501","question":"Prices rise 2% every month for a year. What is the annual inflation rate?","options":["26.82%","24.00%","24.82%","2.00%"],"answer":0,"explanation":"Inflation compounds: 1.02¹² − 1 = 26.82%. Multiplying by 12 understates it.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-502","question":"A price index is 120 in year 1, 126 in year 2 and 135 in year 3. What are the inflation rates in years 2 and 3?","options":["6.00% and 9.00%","5.00% and 7.14%","5.00% and 12.50%","5.00% and 7.50%"],"answer":1,"explanation":"Year 2: 126/120 − 1 = 5.00%. Year 3: 135/126 − 1 = 7.14%. Index-point changes (6 and 9) are not percentages.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-503","question":"Over a year, the price level rises 7% while real GDP falls 2% and unemployment rises. Which type of inflation is most consistent with this data?","options":["Demand-pull inflation","Deflation","Cost-push inflation from an adverse supply shock","Inflation caused by rising productivity"],"answer":2,"explanation":"Demand-pull inflation comes with rising output; prices rising while output falls points to a leftward shift in aggregate supply.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-504","question":"A government spends ₹50 lakh crore on goods and transfers, collects ₹40 lakh crore in taxes, and pays ₹8 lakh crore of interest on existing debt. It sells ₹15 lakh crore of new bonds to the public. How much must it finance by borrowing from the central bank (money creation)?","options":["₹10 lakh crore","₹18 lakh crore","₹0","₹3 lakh crore"],"answer":3,"explanation":"Total deficit = (50 − 40) + 8 = ₹18 lakh crore = new bonds + new money. With ₹15 lakh crore from bonds, ₹3 lakh crore must be monetised. Forgetting interest would wrongly suggest bonds cover everything (₹0).","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-505","question":"A country's actual budget deficit is 5% of GDP. Output is 4% below potential, and the budget balance worsens by 0.5% of GDP for each 1% of negative output gap. What are the cyclical and structural deficits?","options":["Cyclical 2%; structural 3%","Cyclical 3%; structural 2%","Cyclical 4%; structural 1%","Cyclical 0.5%; structural 4.5%"],"answer":0,"explanation":"Cyclical component = 0.5 × 4 = 2% of GDP (it disappears when output returns to potential). Structural deficit = 5 − 2 = 3%, which needs policy action.","difficulty":"very-hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-506","question":"What is the main moral-hazard concern associated with deposit insurance?","options":["Depositors may withdraw funds more often","Banks may take more risk because insured depositors have less reason to monitor them","Bank runs become more frequent","Interest rates on deposits must rise"],"answer":1,"explanation":"Deposit insurance prevents runs but weakens market discipline, so regulators pair it with capital requirements and supervision.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-507","question":"Why might a bank refuse to lend more to a group of borrowers even when they are willing to pay a higher interest rate (Stiglitz–Weiss credit rationing)?","options":["Banks are legally barred from raising rates","Demand for loans is perfectly inelastic","Higher rates attract riskier borrowers and encourage riskier projects, so expected bank returns can fall","Higher rates always lower banks' costs"],"answer":2,"explanation":"Adverse selection and moral hazard mean the bank's expected return can peak at a rate below the market-clearing rate, so it rations credit instead of raising the price.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-508","question":"Income-tax slabs are fixed in nominal rupees. With 6% inflation and wages rising 6%, what happens to households' real tax burden?","options":["It falls, because tax slabs are fixed","It is unchanged, because real incomes are constant","It falls, because inflation erodes tax revenue","It rises, as nominal incomes move into higher slabs while real incomes are unchanged (bracket creep)"],"answer":3,"explanation":"Progressive slabs not indexed to inflation tax a larger share of the same real income, a hidden tax increase.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-509","question":"A bank has ₹1,000 crore of deposits costing 6%. It keeps a 4% CRR (earning nothing), invests 18% in government securities at 7% (SLR) and lends the rest at 10%. If the CRR rises to 5%, by how much does its annual net interest income change?","options":["Falls by ₹1.0 crore","Falls by ₹0.6 crore","Falls by ₹0.4 crore","Unchanged, as deposits are unchanged"],"answer":0,"explanation":"Loans fall from ₹780 crore to ₹770 crore, losing 10% on ₹10 crore = ₹1.0 crore; NII goes from ₹30.6 crore to ₹29.6 crore. CRR acts as a tax on banks because reserves earn no interest.","difficulty":"very-hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-510","question":"In a country where both full-weight and debased (lighter) coins of the same face value circulate legally, which tends to disappear from circulation, and why?","options":["The debased coins, because people refuse them","The full-weight coins, because people hoard or melt the more valuable money and spend the debased coins ('bad money drives out good')","Neither, because face values are equal","Both, because people switch to barter"],"answer":1,"explanation":"Gresham's law: when two monies must be accepted at the same value, people spend the one with lower intrinsic value and keep the one worth more.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-511","question":"The policy repo rate is 6.5%, current inflation is 5% and expected inflation is 4.5%. The neutral real rate is estimated at 1.5%. Is policy restrictive or accommodative in real terms?","options":["Accommodative: the real rate is below 1.5%","Neutral: the real rate exactly equals 1.5%","Restrictive: the ex-ante real rate (about 2%) exceeds the neutral 1.5%","Restrictive, because the nominal rate exceeds inflation"],"answer":2,"explanation":"Ex-ante real rate ≈ 6.5 − 4.5 = 2.0% > 1.5% neutral, so policy is mildly restrictive. A nominal rate above inflation alone does not tell you the stance.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-512","question":"The public holds currency equal to 25% of its deposits, and banks hold reserves equal to 5% of deposits. If reserve money rises by ₹10,000 crore, by how much does the money supply (currency + deposits) rise?","options":["₹2,00,000 crore","₹33,333 crore","₹50,000 crore","₹41,667 crore"],"answer":3,"explanation":"Money multiplier = (1 + c)/(c + r) = 1.25/0.30 = 4.167; ΔM = 10,000 × 4.167 = ₹41,667 crore. Ignoring currency drain gives 1/0.05 = 20 (₹2 lakh crore).","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-513","question":"In one hour, India can produce 10 m of cloth or 5 kg of tea; Sri Lanka can produce 4 m of cloth or 4 kg of tea. Which statement is correct?","options":["India has a comparative advantage in cloth and Sri Lanka in tea, though India has an absolute advantage in both","India should produce both goods because it is better at both","India has a comparative advantage in tea","No gains from trade are possible"],"answer":0,"explanation":"Opportunity cost of 1 kg tea: India 2 m cloth, Sri Lanka 1 m cloth. Sri Lanka gives up less cloth per kg of tea, so it specialises in tea; India in cloth (0.5 kg tea per m vs 1 kg).","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-514","question":"In the same example (India: 10 m cloth or 5 kg tea per hour; Sri Lanka: 4 m cloth or 4 kg tea per hour), within what range must the terms of trade lie for both countries to gain?","options":["Between 0.5 and 1 metre of cloth per kg of tea","Between 1 and 2 metres of cloth per kg of tea","Exactly 1.5 metres of cloth per kg of tea","Between 2 and 2.5 metres of cloth per kg of tea"],"answer":1,"explanation":"India gives up 2 m cloth to make 1 kg tea, so it gains from buying tea for less than 2 m; Sri Lanka gains from selling tea for more than 1 m. Any price between the two opportunity costs works.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-515","question":"A senior partner is both a better consultant and a faster typist than her assistant. Why does she still let the assistant do the typing?","options":["Because the assistant has an absolute advantage in typing","Because typing has no value","Her opportunity cost of typing (forgone billable consulting) is higher, so the assistant has the comparative advantage in typing","Because the partner has a comparative advantage in both tasks"],"answer":2,"explanation":"Comparative advantage depends on opportunity cost, not on who is absolutely better. Nobody can have a comparative advantage in everything.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-516","question":"Country X can make 60 tonnes of rice or 30 machines a year; Country Y can make 40 tonnes of rice or 40 machines (linear PPFs). Without trade, each splits resources equally. If they fully specialise by comparative advantage, how much does total world output change?","options":["Rice and machines both stay the same","Rice rises to 100 tonnes and machines to 70","Rice falls to 40 tonnes, machines rise to 60","Rice rises from 50 to 60 tonnes and machines from 35 to 40"],"answer":3,"explanation":"Without trade: X makes 30 rice + 15 machines, Y makes 20 rice + 20 machines (totals 50, 35). X's opportunity cost of a machine is 2 rice vs Y's 1, so X makes rice (60) and Y makes machines (40)—more of both.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-517","question":"India is labour-abundant relative to Germany, which is capital-abundant. According to the Heckscher–Ohlin model, what pattern of trade is predicted?","options":["India exports labour-intensive goods and imports capital-intensive goods","India exports capital-intensive goods","Trade depends only on differences in technology","Both export the same goods"],"answer":0,"explanation":"H–O says countries export goods that use their relatively abundant factor intensively; technology is assumed identical, unlike in the Ricardian model.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-518","question":"According to the Stolper–Samuelson theorem, when a labour-abundant country opens up to trade, what happens to factor returns?","options":["Both labour and capital gain in real terms","The real wage of labour rises and the real return to capital falls","Real wages fall because imports compete with labour","Factor returns are unaffected; only prices change"],"answer":1,"explanation":"Trade raises the relative price of the labour-intensive export good, which raises the real return of the factor used intensively in it (labour) and lowers the other factor's real return.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-519","question":"What was the Leontief paradox?","options":["Countries with high wages always have trade deficits","Free trade lowers welfare for both countries","The US, thought to be capital-abundant, was found to export goods that were relatively labour-intensive","Tariffs increase imports"],"answer":2,"explanation":"Leontief's input–output study contradicted Heckscher–Ohlin. Explanations include skilled labour (human capital) and natural resources being omitted.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-520","question":"India both exports and imports cars. Which theory best explains such intra-industry trade between similar economies?","options":["Differences in factor endowments","Ricardian differences in labour productivity","Transport costs","Economies of scale combined with product differentiation and consumers' taste for variety"],"answer":3,"explanation":"New trade theory (Krugman): firms specialise in particular varieties to exploit scale economies, and consumers in both countries want variety, so similar goods flow both ways.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-521","question":"A small importing country replaces a ₹10 per-unit tariff with an import quota that results in exactly the same import volume and domestic price. What changes?","options":["The ₹10-per-unit revenue becomes quota rent captured by whoever holds the import licences, instead of going to the government","Domestic price falls","Domestic production rises","Deadweight loss disappears"],"answer":0,"explanation":"An equivalent quota leaves prices, quantities and deadweight losses the same; only the area that was tariff revenue becomes licence-holders' rent (possibly going to foreigners).","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-522","question":"A large exporting country pays a per-unit export subsidy on wheat. What happens to the world price and to its terms of trade?","options":["The world price rises, improving its terms of trade","The world price falls, worsening its terms of trade","No change in the world price","Its terms of trade improve because exports rise"],"answer":1,"explanation":"Subsidised exports raise world supply, lowering the world price; the exporter sells more at a lower price, a terms-of-trade loss on top of the subsidy's cost.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-523","question":"Why can a small tariff raise national welfare for a LARGE importing country but not for a small one?","options":["A large country has no deadweight loss from tariffs","Small countries cannot collect tariff revenue","A large importer can push down the world price of its imports (terms-of-trade gain) that may exceed the deadweight loss","Tariffs always raise welfare for both"],"answer":2,"explanation":"A large buyer's tariff cuts world demand, so foreign exporters absorb part of the tariff. The optimal tariff balances this gain against efficiency losses—though it invites retaliation.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-524","question":"A finished product's world price is ₹100, of which imported inputs are ₹50. The country puts a 20% tariff on the product and a 10% tariff on the inputs. What is the effective rate of protection for domestic producers?","options":["20%","10%","15%","30%"],"answer":3,"explanation":"Value added at world prices = 50. With tariffs: price 120, inputs 55, value added = 65. ERP = (65 − 50)/50 = 30%: tariff escalation protects value added more than the nominal 20% suggests.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-525","question":"Under WTO rules, 'dumping' occurs when a firm:","options":["Exports a product at a price below its normal value, typically its home-market price (or cost)","Sells more abroad than at home","Exports goods of lower quality","Charges a higher price abroad than at home"],"answer":0,"explanation":"Dumping is international price discrimination or below-cost selling; importing countries may impose anti-dumping duties if it causes material injury to domestic producers.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-526","question":"After a sharp depreciation of the rupee, India's trade balance worsens for a few quarters before improving. What explains this?","options":["Depreciation always worsens the trade balance permanently","In the short run import and export volumes are slow to adjust, so higher rupee import costs dominate (J-curve)","Marshall–Lerner conditions are met immediately","Imports become cheaper after depreciation"],"answer":1,"explanation":"Contracts and habits fix volumes in the short run, so the import bill in rupees rises. As elasticities grow over time (Marshall–Lerner satisfied), volumes adjust and the balance improves.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-527","question":"One-year interest rates are 7% in India and 3% in the US. If uncovered interest parity holds, what does the market expect for the rupee over the year?","options":["An appreciation of about 3.9%","No change, since only covered parity matters","A depreciation of about 3.9% against the dollar","A depreciation of about 10%"],"answer":2,"explanation":"UIP: expected ₹/$ change ≈ (1.07/1.03) − 1 = 3.9%. Higher rupee returns are offset by expected rupee depreciation, so investors expect equal returns in either currency.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-528","question":"How are these recorded in India's balance of payments? (p) Remittances sent home by Indians working abroad; (q) A foreign firm building a factory in India; (r) Dividends paid by an Indian company to foreign shareholders.","options":["p: capital account; q: current account; r: financial account","p: financial account; q: financial account; r: current account","p: current account; q: capital account; r: financial account","p: current account (secondary income); q: financial account (FDI inflow); r: current account (primary income debit)"],"answer":3,"explanation":"Remittances are unilateral transfers (secondary income). FDI is a financial-account flow. Investment income (dividends, interest) is primary income in the current account.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-529","question":"A large rise in remittance inflows from Indians working abroad, other things equal, will:","options":["Improve India's current account balance","Improve the capital account","Worsen the financial account balance","Have no effect on the balance of payments"],"answer":0,"explanation":"Personal transfers are recorded as credits under secondary income in the current account, helping offset India's merchandise trade deficit.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-530","question":"A country runs current account deficits for many years, financed by foreign borrowing and FDI. What happens to its net international investment position (NIIP), ignoring valuation changes?","options":["It becomes more positive","It becomes more negative, as foreign claims on the country accumulate","It is unaffected by current account deficits","It rises only if the deficits are financed by FDI"],"answer":1,"explanation":"A current account deficit means net borrowing from or selling assets to the rest of the world, so net foreign liabilities rise each year by roughly the deficit.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-531","question":"The 'twin deficits' hypothesis links a country's budget deficit with its current account deficit. Which national-accounts identity underlies it?","options":["S + I = G − T + CA","CA = G − T","(S − I) + (T − G) = CA, so a larger budget deficit lowers the current account unless private saving rises or investment falls","A budget deficit always raises the current account"],"answer":2,"explanation":"National saving = private saving + public saving (T − G). If private saving and investment are unchanged, a wider budget deficit must be matched by a wider current-account deficit.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-532","question":"An economy's GDP is ₹300 lakh crore. Consumption is ₹200 lakh crore, investment ₹80 lakh crore and government purchases ₹40 lakh crore. Using the absorption approach, what is its trade (net exports) balance?","options":["A surplus of ₹20 lakh crore","A deficit of ₹60 lakh crore","Balanced","A deficit of ₹20 lakh crore"],"answer":3,"explanation":"Absorption A = C + I + G = 320 > Y = 300, so NX = Y − A = −₹20 lakh crore: the country spends more than it produces.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-533","question":"A central bank defends a fixed exchange rate while running persistently expansionary policy, and its foreign reserves are falling steadily. What does first-generation currency-crisis theory predict?","options":["Speculators will attack before reserves run out, forcing an abrupt collapse of the peg","The peg can be maintained indefinitely","The currency will appreciate","Reserves will rise as speculators buy the currency"],"answer":0,"explanation":"Inconsistent fundamentals make abandonment inevitable; anticipating the devaluation, speculators sell the currency early, draining remaining reserves in one sudden attack (Krugman model).","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-534","question":"A country discovers large natural-gas reserves and exports surge. Its manufacturing sector then shrinks. This is called:","options":["The Leontief paradox","Dutch disease: resource export earnings appreciate the real exchange rate and draw resources away, hurting other traded sectors","The J-curve","Immiserising growth"],"answer":1,"explanation":"Resource inflows raise the real exchange rate (via nominal appreciation or higher domestic prices), making manufacturing less competitive.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-535","question":"Imports make up 20% of a country's consumer basket. The currency depreciates 10%, and 50% of that is passed through to import prices. Other prices are unchanged. What is the approximate first-round effect on consumer price inflation?","options":["+10.0 percentage points","+2.0 percentage points","+1.0 percentage point","+5.0 percentage points"],"answer":2,"explanation":"Import prices rise 10% × 50% = 5%; with a 20% weight, CPI rises 0.2 × 5% = 1.0 point (before second-round effects).","difficulty":"very-hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-536","question":"The rupee depreciates 10% against the US dollar and appreciates 5% against the euro. If the dollar has a 60% weight and the euro 40% in the rupee's nominal effective exchange rate, what is the approximate change in the NEER?","options":["A depreciation of about 10%","An appreciation of about 2.5%","A depreciation of about 7.5%","A depreciation of about 4%"],"answer":3,"explanation":"NEER change ≈ 0.6 × (−10%) + 0.4 × (+5%) = −6% + 2% = −4%: a weighted average against trading partners.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-537","question":"The rupee's 40-currency REER index (base = 100) stands at 106. What does this most directly suggest?","options":["The rupee has appreciated about 6% in real (inflation-adjusted), trade-weighted terms since the base period, which may hurt export competitiveness","The rupee has depreciated 6% in nominal terms against the dollar","Indian inflation is 6%","The rupee is undervalued by 6%"],"answer":0,"explanation":"REER adjusts the nominal effective rate for relative inflation. A value above 100 means real appreciation versus the base, though whether that is 'overvaluation' depends on the base year being in equilibrium.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-538","question":"A country holds foreign-exchange reserves of $600 billion and its annual imports of goods and services are $720 billion. How many months of imports do its reserves cover?","options":["12 months","10 months","8.3 months","1.2 months"],"answer":1,"explanation":"Monthly imports = 720/12 = $60 billion; cover = 600/60 = 10 months. A common rule of thumb treats at least 3 months as a minimum.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-539","question":"In the Mundell–Fleming model of a small open economy with perfect capital mobility and a FIXED exchange rate, what is the effect of a fiscal expansion?","options":["It has no effect on income","It causes the currency to appreciate","It is highly effective: the central bank must expand money supply to hold the peg, so income rises strongly","It raises domestic interest rates permanently"],"answer":2,"explanation":"Fiscal expansion pushes up rates and attracts inflows; to stop appreciation the central bank buys foreign currency, raising money supply—reinforcing the expansion. Monetary policy is the impotent one.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-540","question":"In the Mundell–Fleming model with perfect capital mobility and a FLOATING exchange rate, how does a monetary expansion raise output?","options":["By lowering interest rates permanently below world rates","By appreciating the currency and cutting imports","It cannot raise output","Lower domestic interest rates cause capital outflows and currency depreciation, which raises net exports"],"answer":3,"explanation":"Domestic rates cannot stay below world rates, so the effect works through the exchange rate: depreciation boosts net exports until income rises enough to restore money-market equilibrium.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-541","question":"Why are price levels (e.g. of haircuts and restaurant meals) generally higher in rich countries than in poor ones?","options":["Higher productivity in traded goods raises wages economy-wide, pushing up prices of non-traded services (Balassa–Samuelson effect)","Rich countries have higher tariffs","PPP holds exactly for all goods","Exchange rates are always overvalued in rich countries"],"answer":0,"explanation":"Traded-goods prices are equalised by trade, but wage gains from traded-sector productivity spill over to services where productivity grows slowly, raising their prices—and the overall price level.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-542","question":"A country allows its currency to be freely converted for trade, travel and remittances but restricts conversion for buying foreign assets. This is:","options":["Full capital account convertibility","Current account convertibility without full capital account convertibility","A currency board","A fixed exchange rate regime"],"answer":1,"explanation":"Current-account transactions (goods, services, income, transfers) are free while many capital-account flows face limits—the position India adopted in 1994.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-543","question":"Country A imposes a 25% tariff on all imports of a good. The cheapest world supplier, C, sells at ₹80 and partner B at ₹90. A then signs a free-trade agreement with B only. What happens and what is the effect on A?","options":["Imports switch to B and A gains unambiguously","Imports stay with C because it is cheapest","Imports switch from C to B (trade diversion); consumers pay ₹10 less but the government loses ₹20 of tariff revenue per unit","Trade creation only, since prices fall"],"answer":2,"explanation":"Before: C's good costs 80 × 1.25 = ₹100 vs B's ₹112.50. After the FTA, B's tariff-free ₹90 beats ₹100, so A buys from the less efficient B. Consumers save ₹10, but revenue of ₹20 a unit is lost: a net ₹10 loss per unit on existing imports.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-544","question":"A large importing country imposes a ₹10 per-unit tariff, and the world price it pays falls from ₹50 to ₹46. What is the domestic price and how is the tariff borne?","options":["₹60; domestic consumers bear all ₹10","₹56; foreign exporters bear ₹6 and consumers ₹4","₹46; foreign exporters bear all of it","₹56; domestic consumers bear ₹6 and foreign exporters ₹4 per unit"],"answer":3,"explanation":"Domestic price = new world price + tariff = 46 + 10 = ₹56: consumers pay ₹6 more and foreign sellers receive ₹4 less. The ₹4 per unit is a terms-of-trade gain for the importer.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-545","question":"Which statement about the infant-industry argument for protection is correct?","options":["It justifies temporary protection only if the industry will become competitive and its future gains outweigh the costs of protection","It justifies permanent tariffs for all new industries","It is based on terms-of-trade gains","It shows tariffs always raise welfare"],"answer":0,"explanation":"The case rests on learning-by-doing or market failures; in practice protection often becomes permanent, and subsidies may be better targeted than tariffs.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-546","question":"Under a 'crawling peg' exchange-rate regime, the currency:","options":["Floats freely without intervention","Is fixed to an anchor but adjusted in small, pre-announced or periodic steps","Is replaced by a foreign currency","Is fixed permanently by law"],"answer":1,"explanation":"A crawling peg allows gradual adjustment, often to offset inflation differentials, avoiding large one-time devaluations.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-547","question":"To defend its currency during a speculative attack, a central bank sharply raises its policy rate. What is the main cost of this defence?","options":["It always leads to currency appreciation","It increases foreign-exchange reserves without limit","Higher rates hurt domestic borrowers, banks and growth, possibly deepening a recession","It has no domestic effects"],"answer":2,"explanation":"High rates make holding the currency more attractive but squeeze the domestic economy; if markets doubt the government will tolerate the pain, the defence may fail.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-548","question":"According to the gravity model of trade, which pair of countries would be expected to trade the most?","options":["Two small economies far apart","A large economy and a small one far apart","Countries with identical factor endowments only","Two large economies that are geographically close"],"answer":3,"explanation":"The gravity model predicts bilateral trade rises with the product of GDPs and falls with distance (and other trade frictions).","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-549","question":"A country's export price index rises from 100 to 120 while its import price index rises from 100 to 150. What happens to its terms of trade?","options":["They fall to 80, a 20% deterioration","They rise to 125","They fall to 70","They are unchanged, since both prices rose"],"answer":0,"explanation":"Terms of trade = export prices/import prices × 100 = 120/150 × 100 = 80: each unit of exports now buys 20% fewer imports.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-550","question":"Following the change above, the country's terms of trade index is 80 but its export volume index rises from 100 to 130. What is its income terms of trade index, and what does it indicate?","options":["80: purchasing power fell 20%","104: the purchasing power of its exports over imports rose despite worse terms of trade","130: purchasing power rose 30%","62: purchasing power fell sharply"],"answer":1,"explanation":"Income terms of trade = (Px/Pm) × Qx = 0.80 × 130 = 104, showing that higher export volumes more than offset the price deterioration.","difficulty":"very-hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-551","question":"According to Dornbusch's overshooting model, how does the exchange rate react to an unexpected permanent monetary expansion when goods prices are sticky?","options":["It depreciates gradually to its long-run level","It appreciates in the short run","It depreciates immediately by MORE than its long-run amount, then gradually appreciates back toward it","It is unaffected until prices adjust"],"answer":2,"explanation":"Interest rates fall in the short run, so uncovered parity requires the currency to be expected to appreciate; that is only possible if it first jumps beyond its new long-run level.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-552","question":"An imported component costs $50. India levies a 10% ad valorem tariff on its rupee value. If the rupee moves from ₹84 to ₹88 per dollar, what happens to its landed price (ignore other costs)?","options":["It rises from ₹4,620 to ₹4,840, about 14.76%","It rises from ₹4,200 to ₹4,400, about 4.76%","It rises by ₹200, about 4.33%","It rises from ₹4,620 to ₹4,840, about 4.76%"],"answer":3,"explanation":"Landed price = 50 × rate × 1.10: ₹4,620 at ₹84 and ₹4,840 at ₹88. An ad valorem tariff scales with the rupee value, so the percentage rise equals the depreciation, 88/84 − 1 = 4.76%.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-553","question":"Demand for a chemical is P = 100 − Q and the marginal private cost is MPC = 20 + Q. Each unit's marginal external damage rises with output: MD = 0.5Q. What is the socially efficient output, and what per-unit Pigouvian tax achieves it?","options":["Q = 32; tax ₹16 per unit","Q = 40; tax ₹20 per unit","Q = 32; tax ₹20 per unit","Q = 26.7; tax ₹13.33 per unit"],"answer":0,"explanation":"Social MC = 20 + 1.5Q = 100 − Q → Q* = 32. The tax should equal marginal damage AT the efficient output: 0.5 × 32 = ₹16. Using damage at the market output (40 → ₹20) over-taxes.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-554","question":"A regulator is unsure about firms' abatement costs. The marginal damage from pollution is nearly constant, while the marginal abatement cost curve is steep. According to Weitzman's prices-vs-quantities analysis, which instrument is preferable?","options":["A fixed quantity cap","An emissions tax (price instrument)","Either; they are always equivalent","No regulation, because costs are uncertain"],"answer":1,"explanation":"When marginal damage is flat relative to marginal abatement cost, getting the price right matters more than getting the quantity right, so a tax causes smaller expected welfare losses than a cap.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-555","question":"Used cars are either good (worth ₹4 lakh to buyers) or lemons (worth ₹2 lakh), half each; only sellers know which. Owners of good cars will not sell below ₹3.5 lakh; lemon owners accept ₹1.5 lakh. If buyers are risk-neutral and pay expected value, what happens?","options":["All cars trade at ₹3 lakh","Good cars trade at ₹4 lakh and lemons at ₹2 lakh","Buyers offer at most ₹3 lakh, good-car owners withdraw, and only lemons trade at about ₹2 lakh","No cars trade at all"],"answer":2,"explanation":"With both types on offer, buyers pay 0.5 × 4 + 0.5 × 2 = ₹3 lakh, below good owners' ₹3.5 lakh minimum. Once good cars leave, buyers know only lemons remain and pay ₹2 lakh—Akerlof's adverse selection.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-556","question":"A voluntary health insurance pool attracts mainly high-risk people, pushing premiums up and driving out low-risk ones. Which measures directly address this adverse selection?","options":["Higher deductibles for all policyholders","Paying doctors a fixed salary","Lowering premiums for everyone","Mandatory or group coverage, and risk-based screening of applicants"],"answer":3,"explanation":"Adverse selection arises before the contract from hidden information about risk. Pooling everyone (mandates, employer groups) or screening by risk tackles it; deductibles mainly address moral hazard.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-557","question":"After buying comprehensive car insurance, some drivers become less careful about locking their cars. Which contract feature most directly reduces this problem?","options":["A deductible or co-payment so the insured bears part of each loss","Charging every driver the same premium","Requiring a medical test before issue","Offering policies only to young drivers"],"answer":0,"explanation":"This is moral hazard—hidden action after the contract. Making the insured share losses restores some incentive to take care.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-558","question":"Shareholders cannot observe how hard a CEO works, only the firm's results, which also depend on luck. Why is paying the CEO entirely in shares not necessarily optimal?","options":["Because shares give no incentive to work","It gives strong incentives but loads all the firm's risk on a risk-averse manager, who must then be paid a large risk premium","Because shareholders can observe effort directly","Because fixed salaries always produce more effort"],"answer":1,"explanation":"Principal–agent theory trades off incentives against insurance: more pay-for-performance raises effort but also the risk borne by the agent, so optimal contracts mix fixed and variable pay.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-559","question":"Which is an example of SCREENING (rather than signalling) to overcome asymmetric information?","options":["A job seeker earning a costly degree to show ability","A firm offering a long warranty on its products","An insurer offering a menu of policies—high deductible/low premium versus low deductible/high premium—so customers self-select by risk","A company paying a large dividend to show strong cash flow"],"answer":2,"explanation":"In screening the uninformed party designs choices that make the informed party reveal its type. In signalling the informed party acts first to reveal its type.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-560","question":"A firm pays wages well above the market-clearing level even though many qualified people would accept less. Which theory explains this as profit-maximising?","options":["The law of diminishing returns","Monopsony power","The theory of comparative advantage","Efficiency-wage theory: higher pay raises effort, cuts turnover and attracts better applicants"],"answer":3,"explanation":"If productivity depends on the wage, paying above market can lower cost per unit of effective labour. A side-effect is involuntary unemployment.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-561","question":"In an Edgeworth box for two consumers and two goods, which statement about the contract curve is correct?","options":["It is the set of allocations where the consumers' marginal rates of substitution are equal, so no Pareto improvement is possible","It contains only the allocation where both consumers have equal amounts","It shows allocations that both consumers prefer to their endowments","Every point on it is reached by free trade from any endowment"],"answer":0,"explanation":"Points where indifference curves are tangent (equal MRS) are Pareto-efficient. The core is the part of the contract curve both prefer to their endowment; equal division is not required.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-562","question":"The First Fundamental Theorem of Welfare Economics states that a competitive equilibrium is Pareto-efficient. Which condition is NOT required for it?","options":["Complete markets with no externalities","An equal distribution of income","Price-taking behaviour by all agents","Symmetric (full) information"],"answer":1,"explanation":"The theorem needs perfect competition, complete markets, no externalities or public goods and full information. It says nothing about equity—an efficient outcome can be very unequal.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-563","question":"A factory's smoke causes ₹50 lakh a year of damage to a neighbouring laundry. A filter would eliminate it at a cost of ₹30 lakh a year. Bargaining is costless. What happens if (i) the laundry has the right to clean air, and (ii) the factory has the right to pollute?","options":["(i) filter installed; (ii) pollution continues","(i) the factory shuts down; (ii) the filter is installed","The filter is installed in both cases; only who pays differs","Neither case leads to the filter"],"answer":2,"explanation":"(i) The factory installs the ₹30 lakh filter rather than pay ₹50 lakh damages. (ii) The laundry pays the factory between ₹30 and ₹50 lakh to install it. The efficient outcome holds either way (Coase theorem).","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-564","question":"A regulator set up to control prices in an industry gradually begins to make decisions that favour the incumbent firms over consumers. This is called:","options":["Rent control","The free-rider problem","Crowding out","Regulatory capture"],"answer":3,"explanation":"Concentrated industry interests have strong incentives to influence regulators, while dispersed consumers do not—a form of government failure.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-565","question":"A public bridge costs ₹100 crore now and yields net social benefits of ₹12 crore a year forever, starting next year. At a social discount rate of 8%, what is its net present value?","options":["₹50 crore","₹20 crore","₹1,100 crore","₹38.89 crore"],"answer":0,"explanation":"PV of a perpetuity = 12/0.08 = ₹150 crore; NPV = 150 − 100 = ₹50 crore. Lower social discount rates favour long-lived public investments.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-566","question":"Workers accept an extra ₹5,000 a year in wages for a job that raises their annual risk of death by 1 in 10,000. What value of a statistical life does this imply?","options":["₹50 lakh","₹5 crore","₹5 lakh","₹50 crore"],"answer":1,"explanation":"VSL = willingness to accept per unit of risk = 5,000/(1/10,000) = ₹5,00,00,000 = ₹5 crore. It values small risk changes, not any particular life.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-567","question":"Which statement about the Gini coefficient is correct?","options":["A higher Gini means a more equal distribution","It measures absolute poverty","It equals the area between the Lorenz curve and the line of equality divided by the total area under that line, ranging from 0 (perfect equality) to 1","Two countries with the same Gini must have identical Lorenz curves"],"answer":2,"explanation":"The further the Lorenz curve bows below the equality line, the higher the Gini. Lorenz curves can cross, so equal Ginis can hide different distributions.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-568","question":"Employees say they want to save for retirement but rarely enrol in a voluntary pension plan. After the employer switches to automatic enrolment with an opt-out, participation jumps. Which behavioural concepts best explain this?","options":["Loss aversion and the endowment effect only","Rational expectations","The winner's curse","Present bias and the power of defaults (status quo bias)"],"answer":3,"explanation":"Present-biased people keep postponing costly decisions; making saving the default uses inertia to their long-term benefit—a classic 'nudge'.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-569","question":"A product sells at ₹500 with variable cost ₹300 a unit. Fixed costs are ₹4 lakh for output up to 3,000 units, but jump to ₹6 lakh beyond that (a second shift). What is the break-even volume, and what is the profit at 3,500 units?","options":["2,000 units; ₹1 lakh","2,000 units; ₹3 lakh","3,000 units; ₹1 lakh","2,000 units; ₹1.2 lakh"],"answer":0,"explanation":"Break-even = 4,00,000/200 = 2,000 units (within the first range). At 3,500 units: contribution 3,500 × 200 = ₹7 lakh − ₹6 lakh fixed = ₹1 lakh, less than the ₹2 lakh earned at 3,000 units.","difficulty":"hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-570","question":"A firm expects to sell 10,000 units at a full cost of ₹200 a unit. It has ₹50 lakh invested in the product and wants a 20% pre-tax return on that investment. What price should it set under target-return pricing?","options":["₹240","₹300","₹220","₹700"],"answer":1,"explanation":"Required profit = 20% × 50 lakh = ₹10 lakh, i.e. ₹100 a unit; price = 200 + 100 = ₹300. ₹240 applies 20% to unit cost instead.","difficulty":"moderate","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-571","question":"An e-commerce firm tests a 10% price rise. Units sold fall 15%. Before the change, variable cost was 70% of price. What happens to revenue and to total contribution?","options":["Revenue falls 6.5%; contribution falls 6.5%","Revenue rises 10%; contribution rises 10%","Revenue falls 6.5%; contribution rises about 13.3%","Revenue falls 5%; contribution falls about 15%"],"answer":2,"explanation":"Revenue = 1.10 × 0.85 = 0.935 (−6.5%). Unit contribution rises from 0.30P to 1.10P − 0.70P = 0.40P, so contribution = 0.40 × 0.85 = 0.34 vs 0.30, +13.3%. Revenue alone can mislead pricing decisions.","difficulty":"very-hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-572","question":"A new appliance brand offers a 7-year warranty when rivals offer 1 year. Why can this credibly signal high quality?","options":["Warranties are free to offer","Consumers ignore warranties","Warranties raise the product's production cost equally for all firms","A long warranty would be very costly for a maker of unreliable products, so only a high-quality producer can afford to offer it"],"answer":3,"explanation":"A signal works when it is cheaper for the high-quality type: expected repair costs make long warranties unprofitable for low-quality makers.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-573","question":"A regulated utility's prices are capped under an 'RPI − X' formula. Inflation is 5% and X is set at 3%. By how much may it raise prices this year, and what is the incentive?","options":["By 2%; it keeps any profit from cutting costs faster than X","By 8%; it can pass on all cost increases","By 3%; it must earn a fixed rate of return","By 5%; the X factor applies only to profits"],"answer":0,"explanation":"Allowed price change = inflation − X = 5% − 3% = 2%. Unlike rate-of-return regulation, the firm retains efficiency gains beyond X until the next review.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-574","question":"Demsetz suggested 'franchise bidding' as an alternative to regulating a natural monopoly. How is it supposed to work?","options":["The government sets the price at marginal cost and subsidises losses","Firms bid for the exclusive right to serve the market, and the franchise goes to the one offering the lowest price, so competition FOR the market replaces competition in it","Several firms are licensed to compete in the market","The monopoly is nationalised"],"answer":1,"explanation":"Competitive bidding can drive the winning price toward average cost. Problems include few bidders, incomplete contracts for long-lived assets and renegotiation (hold-up).","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-575","question":"To define the relevant market in a merger review, competition authorities often apply the SSNIP test. What does it ask?","options":["Whether firms' market shares exceed 50%","Whether the merged firm's HHI exceeds 2,500","Would a hypothetical monopolist of the candidate products profitably impose a small but significant (5–10%) non-transitory price increase?","Whether consumers could switch to imports within a week"],"answer":2,"explanation":"If enough customers would switch to other products to make the increase unprofitable, those substitutes are added and the test is repeated; the smallest profitable set is the market.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-576","question":"A horizontal merger raises market power (price rises) but also lowers the merged firm's costs. According to Williamson's trade-off, when can such a merger raise total welfare?","options":["Only if price falls","Never, because market power always lowers welfare","Whenever the merged firm's profit rises","When the cost savings on all output exceed the deadweight loss from the higher price"],"answer":3,"explanation":"The deadweight-loss triangle from a modest price rise can be smaller than the rectangle of cost savings across all units, so total surplus can rise even if consumers lose.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-577","question":"An upstream monopolist (MC = ₹10) sells an input to a downstream monopolist that converts it one-for-one at no other cost; final demand is P = 100 − Q. Compare the final price when they set prices separately with the price under vertical integration.","options":["Separate: ₹77.50; integrated: ₹55","Separate: ₹55; integrated: ₹77.50","Both ₹55","Separate: ₹100; integrated: ₹55"],"answer":0,"explanation":"Integrated: MR = 100 − 2Q = 10 → Q = 45, P = 55. Separately, downstream buys Q = (100 − w)/2; upstream faces w = 100 − 2Q, sets MR = 100 − 4Q = 10 → Q = 22.5, w = 55, P = 77.50. Two markups make everyone worse off.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-578","question":"Vaccinating one person also lowers the chance that others fall ill. Without intervention, a free market for vaccination will tend to:","options":["Over-provide vaccinations","Under-provide vaccinations, because private benefit is below social benefit","Provide the efficient amount","Provide none, because vaccines are public goods"],"answer":1,"explanation":"Buyers ignore the benefit to others, so the market quantity is where private marginal benefit equals cost, below the social optimum; a subsidy can correct it.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-579","question":"The Kuznets curve hypothesis suggests that as a country's income per head rises, income inequality:","options":["Falls steadily","Rises steadily","First rises and then falls (an inverted U)","First falls and then rises (a U shape)"],"answer":2,"explanation":"Kuznets argued that early industrialisation widens gaps between sectors, which later narrow as labour shifts out of agriculture and education spreads; the evidence is mixed.","difficulty":"moderate","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-580","question":"Which three dimensions does the UNDP's Human Development Index combine?","options":["GDP growth, inflation and unemployment","Life expectancy, inequality and poverty","Education, environmental quality and political freedom","A long and healthy life, knowledge (education) and a decent standard of living (GNI per capita)"],"answer":3,"explanation":"HDI aggregates health (life expectancy at birth), education (mean and expected years of schooling) and income (GNI per capita, PPP). Inequality and poverty have separate indices.","difficulty":"moderate","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-581","question":"Two villages each have 20% of people below the poverty line. In village X the poor are just below the line; in village Y they are far below it. Which measure captures the difference?","options":["The poverty gap index, which measures how far below the line the poor are on average","The headcount ratio","The Gini coefficient of the whole population only","GDP per capita"],"answer":0,"explanation":"The headcount ratio (20% in both) ignores depth. The poverty gap weights each poor person by their shortfall, so village Y scores worse.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-582","question":"A firm chooses a Large or Small plant. Payoffs (₹ crore): Large earns 100 if demand is high and −20 if low; Small earns 40 if high and 10 if low. High demand has probability 0.5. What is the expected value of perfect information about demand?","options":["₹40 crore","₹15 crore","₹55 crore","₹25 crore"],"answer":1,"explanation":"Without information: E(Large) = 40, E(Small) = 25, so choose Large (₹40 crore). With perfect information: choose Large if high (100) and Small if low (10): 0.5 × 100 + 0.5 × 10 = 55. EVPI = 55 − 40 = ₹15 crore.","difficulty":"very-hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-583","question":"5% of a factory's units are defective. An inspection flags 90% of defective units but also wrongly flags 10% of good units. If a unit is flagged, what is the probability it is actually defective?","options":["90.0%","50.0%","32.1%","4.5%"],"answer":2,"explanation":"P(defect | flag) = 0.05 × 0.9/(0.05 × 0.9 + 0.95 × 0.1) = 0.045/0.140 = 32.1%. Because good units are so common, most flagged units are false alarms.","difficulty":"very-hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-584","question":"Payoffs (₹ lakh) for three strategies under two states: A: (80, 20); B: (50, 50); C: (30, 60). Using the minimax-regret criterion, which strategy is chosen?","options":["A (maximum regret 40)","C (maximum regret 50)","A, because it has the highest payoff","B (maximum regret 30)"],"answer":3,"explanation":"Best payoffs: 80 in state 1, 60 in state 2. Regrets: A (0, 40) → max 40; B (30, 10) → 30; C (50, 0) → 50. Minimise the maximum regret: B.","difficulty":"hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-585","question":"Using the same payoffs—A: (80, 20); B: (50, 50); C: (30, 60)—which strategies do the maximin (pessimist) and maximax (optimist) criteria select?","options":["Maximin: B; maximax: A","Maximin: C; maximax: A","Maximin: A; maximax: C","Maximin: B; maximax: C"],"answer":0,"explanation":"Worst cases are 20, 50, 30, so maximin picks B (50). Best cases are 80, 50, 60, so maximax picks A (80).","difficulty":"hard","source":"MBA placement · Consulting"},
  {"id":"mgmt-business-economics-586","question":"Diners choose between two new restaurants and see that one is crowded. Many ignore their own (mixed) reviews and join the crowd. Economists call this:","options":["The bandwagon effect caused by network externalities only","An information cascade (herding), where people rationally follow others' choices and stop revealing private information","Adverse selection","The winner's curse"],"answer":1,"explanation":"Once early choices outweigh any one person's private signal, later people imitate; the cascade can lock in a wrong choice because private information stops being aggregated.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-587","question":"Why does an implicit government guarantee for very large banks ('too big to fail') create moral hazard?","options":["Large banks pay more tax","Depositors withdraw funds from large banks","Banks and their creditors expect bailouts, so they take more risk and lend to banks more cheaply than the risk warrants","It forces large banks to hold more capital"],"answer":2,"explanation":"Expected rescue shifts losses to taxpayers while profits stay private, lowering creditors' incentive to monitor and encouraging excessive risk; capital surcharges aim to offset this.","difficulty":"hard","source":"Bank MT · RBI Grade B pattern"},
  {"id":"mgmt-business-economics-588","question":"According to the theory of the second best, if one market distortion cannot be removed, then:","options":["Removing any other distortion always raises welfare","All prices should still be set equal to marginal cost","The economy must be at a Pareto optimum","Removing another distortion elsewhere does not necessarily raise welfare"],"answer":3,"explanation":"Lipsey and Lancaster showed that with one unavoidable distortion, the best policy may involve deliberately departing from the usual efficiency conditions elsewhere; piecemeal reform can backfire.","difficulty":"very-hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-589","question":"A component supplier must invest in machinery that is useful only for one car maker. Why might the two firms integrate vertically?","options":["Relationship-specific investment exposes the supplier to hold-up—the buyer could renegotiate the price after the investment is sunk—so integration protects incentives to invest","To avoid all fixed costs","Because integration always lowers marginal cost","To reduce the number of employees"],"answer":0,"explanation":"Asset specificity makes contracts vulnerable to opportunistic renegotiation (Williamson). Common ownership or long-term contracts reduce under-investment.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-590","question":"A new highway gives drivers benefits of ₹500 crore but imposes ₹200 crore of losses on residents along the route, who are not compensated. Which statement is correct?","options":["It is a Pareto improvement because net benefits are positive","It passes the Kaldor–Hicks test (gainers could compensate losers) but is not a Pareto improvement","It fails the Kaldor–Hicks test","It is both a Pareto improvement and Kaldor–Hicks efficient"],"answer":1,"explanation":"A Pareto improvement requires nobody to be worse off. Kaldor–Hicks only requires that winners COULD compensate losers (500 > 200), which underlies most cost–benefit analysis.","difficulty":"hard","source":"CFA Level I economics · MBA"},
  {"id":"mgmt-business-economics-591","question":"When the price of a product rises from ₹40 to ₹60, quantity demanded falls from 300 to 180 units. What is the price elasticity of demand using the midpoint (arc) formula?","options":["-0.80","-2.00","-0.50","-1.25"],"answer":3,"explanation":"Midpoint: %ΔQ = -120/240 = -50%; %ΔP = 20/50 = 40%; elasticity = -1.25. Using the starting point gives -0.80 and the end point -2.00, so the arc formula avoids the direction-dependence.","difficulty":"moderate","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-592","question":"Demand is Q = 120 - 3P. At what price is the point price elasticity of demand equal to -1/3?","options":["₹20","₹30","₹5","₹10"],"answer":3,"explanation":"Elasticity = -3P/(120 - 3P). Setting it to -1/3 gives 9P = 120 - 3P, so P = 10 (Q = 90). At ₹20 the elasticity is -1 (revenue maximum) and at ₹30 it is -3.","difficulty":"moderate","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-593","question":"At the pre-tax equilibrium, the price elasticity of demand is -0.5 and the price elasticity of supply is +1.5. A per-unit tax of ₹8 is imposed on sellers, and the elasticities may be treated as constant over the relevant range. By about how much does the price paid by buyers rise?","options":["₹6","₹2","₹4","₹8"],"answer":0,"explanation":"The side that is less elastic bears more of the tax: buyers' share = Es/(Es + |Ed|) = 1.5/2 = 75%, so the buyer price rises by 0.75 x 8 = 6 and sellers' net price falls by 2. A 100% pass-through would require perfectly inelastic demand.","difficulty":"hard","source":"CAT · MBA placement"},
  {"id":"mgmt-business-economics-594","question":"A competitive firm has total variable cost TVC = Q^3 - 12Q^2 + 60Q and fixed cost ₹100. Market price is ₹60. What is the maximum profit it can earn?","options":["₹-100","₹256","₹156","₹116"],"answer":2,"explanation":"Set P = MC: 3Q^2 - 24Q + 60 = 60 gives Q = 0 or 8; Q = 0 is where MC is falling (a profit minimum, loss = 100), and Q = 8 satisfies the second-order condition. Profit = 480 - 224 - 100 = 156.","difficulty":"very-hard","source":"MBA placement · UPSC Economics Optional"},
  {"id":"mgmt-business-economics-595","question":"A monopolist with constant MC = ₹20 sells in two separable markets with demands P1 = 100 - Q1 and P2 = 60 - Q2. By how much does its profit rise if it practises third-degree price discrimination instead of charging a single price (at which both markets are served)?","options":["₹2,000","₹1,800","₹400","₹200"],"answer":3,"explanation":"Discrimination: MR=MC in each market gives Q1=40 at ₹60 and Q2=20 at ₹40, profit 1,600 + 400 = 2,000. Uniform price: aggregate demand is Q = 160 - 2P, so Q = 60 at ₹50, profit 1,800. Gain = 200.","difficulty":"very-hard","source":"CAT · MBA placement"},
  {"id":"mgmt-business-economics-596","question":"Two firms face market demand P = 100 - Q and constant MC = ₹10. Firm 1 moves first by choosing its output (Stackelberg leader) and Firm 2 follows. What is the leader's profit?","options":["₹1,012.5","₹900.0","₹506.25","₹1,125.0"],"answer":0,"explanation":"Follower's reaction: q2 = (90 - q1)/2. The leader maximises (90 - q1 - q2) q1 = (45 - q1/2) q1, giving q1 = 45, q2 = 22.5, price 32.5. Leader profit = 22.5 x 45 = 1,012.5, above the Cournot figure of 900.","difficulty":"very-hard","source":"CAT · UPSC Economics Optional"},
  {"id":"mgmt-business-economics-597","question":"A natural monopoly has total cost TC = 76 + 10Q and faces demand P = 50 - Q. A regulator imposes average-cost pricing (P = AC) and wants the larger of the two possible quantities. What quantity is supplied?","options":["40 units","20 units","38 units","2 units"],"answer":2,"explanation":"P = AC: 50 - Q = 10 + 76/Q gives Q^2 - 40Q + 76 = 0, so Q = 38 or 2. The larger root (price 12) is chosen. Marginal-cost pricing would give 40 units but a loss of 76; the unregulated monopoly gives 20.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-598","question":"Two residents have marginal benefit curves for a public park of MB1 = 20 - Q and MB2 = 30 - 2Q (₹ per visit-unit); the marginal cost of provision is ₹26. What is the efficient quantity?","options":["2 units","12 units","8 units","6 units"],"answer":2,"explanation":"For a public good, add marginal benefits vertically: 50 - 3Q = 26, so Q = 8. Adding quantities horizontally (as for private goods) would give just 2 units at a price of 26, because only resident 2 values it that high.","difficulty":"hard","source":"UPSC Economics Optional · CAT"},
  {"id":"mgmt-business-economics-599","question":"In an open economy MPC out of disposable income is 0.8, the income tax rate is 25% and the marginal propensity to import is 0.1. By how much does equilibrium income rise if government spending rises by ₹300 crore?","options":["₹1,500 crore","₹600 crore","₹750 crore","₹1,000 crore"],"answer":1,"explanation":"Multiplier = 1/[1 - MPC(1 - t) + m] = 1/(1 - 0.6 + 0.1) = 2, so income rises by 600 crore. Omitting tax and imports (5), imports (2.5) or tax (3.33) overstates the multiplier.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-600","question":"In a simple closed economy with lump-sum taxes and MPC = 0.75, the government raises spending by ₹100 crore and funds it fully by a ₹100 crore rise in lump-sum taxes. What happens to equilibrium income?","options":["Rises by ₹400 crore","Falls by ₹200 crore","No change","Rises by ₹100 crore"],"answer":3,"explanation":"Spending multiplier = 4 gives +400; tax multiplier = -MPC/(1 - MPC) = -3 gives -300; net +100, i.e. the balanced-budget multiplier is 1. The 'no change' answer wrongly assumes the two effects cancel.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-601","question":"An economy has IS: Y = 1800 - 40r and LM: Y = 600 + 60r. A fiscal expansion shifts the IS curve to Y = 2000 - 40r. By how much does equilibrium income actually rise?","options":["200","120","80","140"],"answer":1,"explanation":"Initially 1800 - 40r = 600 + 60r gives r = 12, Y = 1,320. After the shift r = 14 and Y = 1,440, a rise of 120, not the full horizontal shift of 200. The higher interest rate crowds out 80 of private demand.","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-602","question":"Okun's law for an economy is: output growth (%) = 3 - 2 x (change in unemployment rate, in percentage points). Unemployment is 6% when output contracts by 1% in a year. What is the unemployment rate at the end of that year?","options":["7%","8%","5%","6.5%"],"answer":1,"explanation":"-1 = 3 - 2 x Δu gives Δu = 2 percentage points, so u = 6 + 2 = 8%. Forgetting the 3% trend growth that is needed just to hold unemployment constant gives 6.5%.","difficulty":"moderate","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-603","question":"Using the equation of exchange MV = PY in growth-rate form, the money supply grows 8%, velocity falls 3% and real output grows 4%. What is the approximate inflation rate?","options":["1%","9%","7%","15%"],"answer":0,"explanation":"%ΔP = %ΔM + %ΔV - %ΔY = 8 - 3 - 4 = 1%. Adding the real growth (9%), adding the velocity change (7%) or summing everything (15%) each mishandle a sign.","difficulty":"moderate","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-604","question":"The nominal exchange rate is fixed at ₹80 per US dollar. Over a year the Indian price level rises 20% and the US price level rises 8%. What happens to India's real exchange rate (rupees per unit of US goods basket), and what does this mean?","options":["It falls 10%: Indian goods become relatively more expensive","It rises 10%: Indian goods become relatively cheaper","It falls 12%: Indian goods become relatively cheaper","It is unchanged because the nominal rate is fixed"],"answer":0,"explanation":"Real rate = e x P*/P changes by 1.08/1.20 = 0.90, a 10% fall. Domestic goods have become 10% dearer relative to foreign ones, a real appreciation of the rupee that hurts export competitiveness.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-605","question":"In one day, Country A can make either 6 units of cloth or 3 of wheat; Country B can make either 4 units of cloth or 4 of wheat. At which price of wheat (in units of cloth) would trade benefit both countries?","options":["1 wheat for 1.5 cloth","1 wheat for 0.8 cloth","1 wheat for 2.5 cloth","1 wheat for 1 cloth"],"answer":0,"explanation":"Opportunity cost of wheat is 2 cloth in A and 1 cloth in B. Both gain if the trade price lies strictly between 1 and 2 cloth per wheat; 1.5 does so, 1 gives B no gain and 0.8 or 2.5 leaves one side worse off.","difficulty":"moderate","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-606","question":"Demand is P = 100 - 2Q. If the price falls from ₹60 to ₹40, by how much does consumer surplus increase?","options":["₹400","₹600","₹200","₹500"],"answer":3,"explanation":"Quantity rises from 20 to 30. Gain = rectangle on the old units (20 x 20 = 400) plus triangle on the new units (0.5 x 10 x 20 = 100) = 500. Counting only the rectangle (400) ignores the new buyers.","difficulty":"moderate","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-607","question":"Demand is Qd = 200 - 4P and supply is Qs = 2P + 20. A per-unit tax of ₹6 is levied on sellers. What is the deadweight loss?","options":["₹432","₹48","₹24","₹240"],"answer":2,"explanation":"Pre-tax equilibrium: P = 30, Q = 80. With the tax, 200 - 4Pb = 2(Pb - 6) + 20 gives Pb = 32, Q = 72. DWL = 0.5 x 6 x (80 - 72) = 24; the tax revenue is a separate 432 and is not lost.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-608","question":"Demand is Qd = 100 - P and supply is Qs = 2P - 20. The government imposes a price ceiling of ₹30 that is strictly enforced on official sales, but buyers resell scarce units among themselves. What price would clear the black market?","options":["₹30","₹40","₹70","₹60"],"answer":3,"explanation":"At ₹30 supply is 2(30) - 20 = 40 units, while demand is 70. Only 40 units exist, so the marginal buyer's willingness to pay is 100 - 40 = ₹60. The free-market price is ₹40 (Q = 60).","difficulty":"hard","source":"UPSC Economics Optional · CAT"},
  {"id":"mgmt-business-economics-609","question":"Row chooses A or B; Column chooses X or Y. Payoffs (Row, Column): (A,X) = (2,1), (A,Y) = (0,3), (B,X) = (1,2), (B,Y) = (3,0). There is no pure-strategy Nash equilibrium. In the mixed-strategy equilibrium, with what probability does Column play X?","options":["3/4","1/2","1/4","2/3"],"answer":0,"explanation":"Column mixes so that Row is indifferent: 2q + 0(1 - q) = 1q + 3(1 - q) gives 2q = 3 - 2q, so q = 3/4. The 1/2 is Row's own equilibrium probability of A, which makes Column indifferent.","difficulty":"very-hard","source":"UPSC Economics Optional · CAT"},
  {"id":"mgmt-business-economics-610","question":"In a used-car market, car quality is uniformly distributed between 0 and 6,000 (the value to the seller equals quality). Buyers value a car at 1.5 times its quality but cannot observe it. Sellers sell only if the price is at least their quality. What happens in equilibrium?","options":["Cars trade at ₹3,000","The market unravels: no cars trade","All cars trade at ₹4,500","Only cars of quality above 3,000 trade"],"answer":1,"explanation":"At any price p only cars with quality up to p are offered, so average quality is p/2 and buyers will pay 1.5 x p/2 = 0.75p < p. The price keeps falling to zero: adverse selection destroys the market despite gains from trade.","difficulty":"hard","source":"CAT · MBA placement"},
  {"id":"mgmt-business-economics-611","question":"A monopsonist faces labour supply W = 10 + 0.5L and has marginal revenue product MRP = 70 - L. What wage does it pay?","options":["₹30","₹40","₹25","₹10"],"answer":2,"explanation":"Marginal factor cost = 10 + L (the wage rises for all workers). Setting MFC = MRP: 10 + L = 70 - L gives L = 30, and the wage is read off supply: 10 + 15 = 25. A competitive market would hire 40 at a wage of 30.","difficulty":"hard","source":"UPSC Economics Optional · CAT"},
  {"id":"mgmt-business-economics-612","question":"A firm has Q = sqrt(K x L), wage ₹4 per unit of labour and capital rent ₹16 per unit. What is the minimum cost of producing 100 units?","options":["₹2,000","₹3,400","₹1,000","₹1,600"],"answer":3,"explanation":"Cost minimisation needs MPL/w = MPK/r, i.e. K/L = w/r = 1/4, so L = 4K. Then Q = sqrt(4K^2) = 2K = 100 gives K = 50, L = 200; cost = 800 + 800 = 1,600. Using K = L = 100 gives 2,000.","difficulty":"hard","source":"CAT · MBA placement"},
  {"id":"mgmt-business-economics-613","question":"A firm's production function is Q = K^0.4 L^0.7. If it doubles both capital and labour, output rises by about:","options":["100%","114%","110%","90%"],"answer":1,"explanation":"The exponents sum to 1.1, so the function has increasing returns: scaling inputs by 2 scales output by 2^1.1 = 2.14, a 114% rise. A sum of 1 would give exactly 100%.","difficulty":"moderate","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-614","question":"A consumer with utility U = x^0.5 y^0.5 has income ₹200 and faces prices Px = ₹2 and Py = ₹8. How many units of x does she buy at the optimum?","options":["50","100","25","12.5"],"answer":0,"explanation":"With equal exponents she spends half of income on each good: ₹100 on x, which is 100/2 = 50 units (and 12.5 units of y). Spending everything on the cheaper good gives 100.","difficulty":"moderate","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-615","question":"In the Solow model y = k^0.5, the saving rate is 0.3, depreciation 0.1 and population growth 0.02 (no technological progress). What is steady-state consumption per worker?","options":["2.50","0.75","1.75","4.375"],"answer":2,"explanation":"Steady state: s k^0.5 = (n + δ) k gives k^0.5 = 0.3/0.12 = 2.5, k = 6.25. Output y = 2.5 and consumption = (1 - 0.3) x 2.5 = 1.75. Using y itself (2.5) or investment (0.75) is not consumption.","difficulty":"very-hard","source":"UPSC Economics Optional · CFA Level I"},
  {"id":"mgmt-business-economics-616","question":"Banks hold reserves of 10% of deposits and the public holds currency equal to 20% of deposits. By how much does the money supply rise if the central bank adds ₹100 crore of high-powered money?","options":["₹1,000 crore","₹333 crore","₹400 crore","₹500 crore"],"answer":2,"explanation":"Money multiplier = (1 + c)/(c + r) = 1.2/0.3 = 4, so M rises by 400 crore. The simple deposit multiplier 1/r = 10 ignores currency leakage, and 1/(c + r) = 3.33 forgets that currency itself is part of money.","difficulty":"hard","source":"UPSC Economics Optional · CFA Level I"},
  {"id":"mgmt-business-economics-617","question":"Identical competitive firms have total cost TC = 100 + q^2. Market demand is Q = 1,000 - 20P. How many firms are there in long-run equilibrium?","options":["50","60","100","30"],"answer":1,"explanation":"Minimum ATC: ATC = 100/q + q is lowest at q = 10, ATC = 20, so the long-run price is 20. Market quantity = 1,000 - 400 = 600, and each firm makes 10, so there are 60 firms.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-618","question":"A profit-maximising monopolist has marginal cost ₹24 and faces demand with constant price elasticity of -3. What price does it set?","options":["₹32","₹36","₹72","₹27"],"answer":1,"explanation":"The inverse-elasticity rule: P(1 - 1/3) = MC, so P = 24/(2/3) = 36 (Lerner index = 1/3). Using a markup of (1 + 1/3) gives 32, which has the wrong sign on 1/e.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-619","question":"The price of good X falls from ₹10 to ₹5. A consumer buys 20 units before the fall and 23 units after it. A Hicksian decomposition shows that, at the new price, the compensated (income-adjusted) demand is 26 units. What do the effects imply about X?","options":["Substitution effect +6, income effect -3: inferior but not a Giffen good","Substitution effect +3, income effect +6: a normal good","Substitution effect +6, income effect -9: a Giffen good","Substitution effect +3, income effect -3: inferior but not Giffen"],"answer":0,"explanation":"Substitution effect = 26 - 20 = +6; income effect = 23 - 26 = -3 (the real-income gain reduces demand, so X is inferior). A Giffen good needs the income effect to outweigh the substitution effect, so that total demand falls; here total demand rises by 3.","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-620","question":"An oligopolist faces a kinked demand curve at Q = 40, P = ₹100. Above the kink demand is P = 120 - 0.5Q and below it P = 140 - Q. Over which range of marginal cost will its price stay at ₹100?","options":["₹80 to ₹100","₹60 to ₹100","₹60 to ₹80","₹40 to ₹60"],"answer":2,"explanation":"MR on the upper segment = 120 - Q = 80 at Q = 40; on the lower segment MR = 140 - 2Q = 60. The discontinuity in MR spans 60 to 80, so any MC in that band leaves the profit-maximising output and price unchanged.","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-621","question":"An entrant decides whether to enter a market. If it stays out, payoffs are (Entrant 0, Incumbent 10). If it enters, the incumbent chooses to accommodate (4, 4) or to fight (-2, 1). The incumbent announces beforehand that it will fight any entrant. What is the subgame-perfect outcome?","options":["Entry is deterred, so payoffs are (0, 10)","Entry occurs and the incumbent accommodates","Entry occurs and the incumbent fights","The entrant randomises between entering and staying out"],"answer":1,"explanation":"By backward induction, after entry the incumbent compares 4 (accommodate) with 1 (fight) and accommodates, so the threat is not credible. Knowing this, the entrant earns 4 by entering rather than 0, giving (4, 4).","difficulty":"hard","source":"CAT · MBA placement"},
  {"id":"mgmt-business-economics-622","question":"Three risk-neutral bidders have independent private values uniformly distributed on [0, 100] and take part in a first-price sealed-bid auction. The symmetric equilibrium strategy is to bid (n - 1)/n of one's value. How much should a bidder whose value is ₹90 bid?","options":["₹90","₹45","₹60","₹68"],"answer":2,"explanation":"With n = 3 the equilibrium bid is (2/3) x value = 60. Bidding your value earns zero surplus, and bidding 67.5 (3/4 of value) is the rule for n = 4, not 3.","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-623","question":"A small country faces a world price of ₹50. Domestic demand is Qd = 200 - 2P and domestic supply is Qs = P. It imposes a ₹10 per-unit import tariff. What is the deadweight loss of the tariff?","options":["₹200","₹150","₹100","₹250"],"answer":1,"explanation":"With the tariff the domestic price is 60: supply rises from 50 to 60 and demand falls from 100 to 80. DWL = 0.5 x 10 x 10 (production distortion) + 0.5 x 10 x 20 (consumption distortion) = 150; the revenue of 200 is a transfer to government, not a loss.","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-624","question":"Exports and imports are both ₹1,000 crore. The elasticity of foreign demand for exports is 0.6 and the elasticity of domestic demand for imports is 0.5. Applying the Marshall-Lerner logic, by approximately how much does the trade balance change after a 10% real depreciation (taking the initial trade balance as zero)?","options":["Worsens by about ₹10 crore","Improves by about ₹110 crore","No change, because the elasticities are each below 1","Improves by about ₹10 crore"],"answer":3,"explanation":"Net exports change by roughly X x depreciation x (εx + εm - 1) = 1,000 x 0.10 x (0.6 + 0.5 - 1) = +10. Since the sum exceeds 1, depreciation helps; the condition applies to the sum of elasticities, not each one.","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-625","question":"A central bank follows the rule i = r* + π + 0.5(π - π*) + 0.5(output gap), with r* = 2%, target inflation π* = 2%. Inflation is 4% and output is 2% below potential. What policy rate does the rule prescribe?","options":["6%","7%","5%","8%"],"answer":0,"explanation":"i = 2 + 4 + 0.5 x 2 + 0.5 x (-2) = 6%. Ignoring the negative output gap gives 7%; treating the gap as +2 gives 8%.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-626","question":"An economy has an annual inflation rate of 10% and the central bank wants to bring it down to 4%. The sacrifice ratio is 3 (percentage points of one year's GDP lost per percentage point of disinflation). What is the cumulative output loss?","options":["6% of one year's GDP","18% of one year's GDP","30% of one year's GDP","12% of one year's GDP"],"answer":1,"explanation":"Disinflation of 6 points x sacrifice ratio 3 = 18% of a year's GDP, summed over the adjustment period. Using only the disinflation (6) or measuring from the 10% level (30) misses the definition.","difficulty":"hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-627","question":"The Phillips curve is π = π^e - 0.5(u - 5), where u is the unemployment rate in %. Expectations are adaptive (π^e equals last year's inflation). Last year's inflation was 6% and unemployment is held at 7% for two years. What is inflation in the second year?","options":["5%","3%","4%","6%"],"answer":2,"explanation":"Year 1: π = 6 - 0.5 x 2 = 5%. Year 2: expected inflation is now 5%, so π = 5 - 1 = 4%. Each year of slack lowers inflation by another point, which is why disinflation is cumulative.","difficulty":"hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-628","question":"Per-capita income grows at a steady 7% a year. After about how many years will it have quadrupled?","options":["About 20.5 years","About 10.3 years","About 14.3 years","About 25.7 years"],"answer":0,"explanation":"Solve 1.07^t = 4: t = ln 4 / ln 1.07 = 20.5 years. Doubling takes 10.3 years, and quadrupling is two doublings, not four times the doubling time.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-629","question":"From the data (₹ crore) GDP at market prices 1,000; depreciation 100; indirect taxes 80; subsidies 20; net factor income from abroad -30, what is net national product at factor cost?","options":["810","840","870","790"],"answer":0,"explanation":"NNP at factor cost = GDPmp - depreciation - net indirect taxes (80 - 20) + NFIA = 1,000 - 100 - 60 - 30 = 810. Ignoring NFIA gives 840 and subtracting the negative NFIA gives 870.","difficulty":"hard","source":"UPSC Economics Optional · CAT"},
  {"id":"mgmt-business-economics-630","question":"A person with utility U = sqrt(W) has wealth ₹10,000 and a 10% chance of losing ₹6,400. What is the most she would pay for full insurance?","options":["₹640","₹784","₹144","₹6,400"],"answer":1,"explanation":"Expected utility = 0.9 x 100 + 0.1 x 60 = 96, a certainty equivalent of 96^2 = 9,216. She will pay up to 10,000 - 9,216 = 784, which is the fair premium of 640 plus a risk premium of 144.","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-631","question":"A proprietor's accounting profit is ₹12 lakh. He could earn a ₹6 lakh salary elsewhere, and has ₹40 lakh of his own capital in the business that could earn 8% in a safe alternative. What is his economic profit?","options":["₹6.0 lakh","₹2.8 lakh","₹5.2 lakh","₹12.0 lakh"],"answer":1,"explanation":"Economic profit = accounting profit - implicit costs = 12 - 6 (forgone salary) - 3.2 (8% on 40 lakh) = 2.8 lakh. Deducting only the salary gives 6.0, and only the capital charge gives 8.8.","difficulty":"hard","source":"CAT · MBA placement"},
  {"id":"mgmt-business-economics-632","question":"Two customers value goods X and Y as follows (₹): customer A values X at 8 and Y at 3; customer B values X at 3 and Y at 8. Marginal cost is zero. By how much does the seller's maximum revenue rise by using a pure bundle (X and Y sold together) instead of pricing the goods separately?","options":["₹22","₹4","₹6","₹16"],"answer":2,"explanation":"Separate pricing: for each good, ₹8 sells one unit (8) and ₹3 sells two (6), so ₹8 is best; total 16. Each customer values the bundle at 11, so a ₹11 bundle sells two (22). Gain = 6.","difficulty":"very-hard","source":"CAT · MBA placement"},
  {"id":"mgmt-business-economics-633","question":"An amusement park serves many identical customers, each with demand P = 10 - Q (Q = rides). Marginal cost is ₹2 per ride. The park uses a two-part tariff to maximise profit. What entry fee and per-ride price should it set?","options":["Entry fee ₹32, price ₹2 per ride","Entry fee ₹16, price ₹6 per ride","Entry fee ₹64, price ₹2 per ride","Entry fee ₹0, price ₹6 per ride"],"answer":0,"explanation":"Price at marginal cost (₹2) so each customer buys 8 rides, then take all consumer surplus as the fee: 0.5 x 8 x 8 = 32. A monopoly price of 6 without a fee earns less than the 32 per customer from the tariff.","difficulty":"very-hard","source":"CAT · MBA placement"},
  {"id":"mgmt-business-economics-634","question":"Two firms with zero marginal cost face market demand P = 100 - Q. They agree to share the monopoly output equally. If Firm 1 secretly cheats while Firm 2 sticks to its quota, and Firm 1 picks its best output given that quota, what is Firm 1's profit?","options":["₹1,250.00","₹1,111.11","₹1,562.50","₹1,406.25"],"answer":3,"explanation":"Monopoly output is 50, so each quota is 25. Firm 1's best response to 25 is (100 - 25)/2 = 37.5, price 100 - 62.5 = 37.5, profit 37.5 x 37.5 = 1,406.25, above the cartel profit of 1,250 and the Cournot profit of 1,111.11, which is why cartels are unstable.","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-635","question":"Seven voters rank three options: 3 voters rank A > B > C; 2 rank B > C > A; 2 rank C > B > A. Which statement is correct?","options":["Plurality, Borda and pairwise majority all pick A","Plurality picks B, while Borda picks A","Plurality picks A, while Borda count and pairwise majority both pick B","There is a Condorcet cycle among A, B and C"],"answer":2,"explanation":"First preferences: A 3, B 2, C 2, so plurality picks A. Borda (3-2-1 points): A = 13, B = 16, C = 13, so B wins. Pairwise, B beats A 4-3 and B beats C 5-2, so B is the Condorcet winner and there is no cycle.","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-636","question":"Demand for a crop is Qd = 300 - 4P and supply is Qs = 6P - 100. The government sets a floor of ₹50 and buys all unsold output at that price. What does the procurement cost?","options":["₹100","₹10,000","₹4,000","₹5,000"],"answer":3,"explanation":"At ₹50, supply is 200 and demand 100, so the surplus is 100 units; cost = 100 x 50 = 5,000. The free-market price is ₹40, so the floor is binding.","difficulty":"hard","source":"CAT · MBA placement"},
  {"id":"mgmt-business-economics-637","question":"A firm's total product is TP = 30L + 12L^2 - L^3. At what labour input is average product at its maximum (the end of Stage I of production)?","options":["L = 4","L = 12","L = 10","L = 6"],"answer":3,"explanation":"AP = 30 + 12L - L^2 is maximised where dAP/dL = 12 - 2L = 0, i.e. L = 6, where MP = AP = 66. L = 4 maximises marginal product (the onset of diminishing returns), not average product.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-638","question":"A consumer earns ₹100 this year and ₹150 next year, and can borrow or lend at 10%. She wants equal consumption in both years. How much does she borrow this year?","options":["₹25.00","₹23.81","₹50.00","₹0.00"],"answer":1,"explanation":"Present value of income = 100 + 150/1.1 = 236.36, so equal consumption c satisfies c(1 + 1/1.1) = 236.36, c = 123.81. She borrows 123.81 - 100 = 23.81. Simply averaging income (125) ignores interest and gives 25.","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-639","question":"Two firms sell an identical product and compete in prices (Bertrand). Firm 1 has marginal cost ₹10 and Firm 2 has marginal cost ₹14; consumers buy from the cheaper firm. What is the equilibrium market price (taking the smallest currency unit as negligible)?","options":["₹10, with both firms sharing the market","₹12, the average of the two costs","Just below ₹14, with Firm 1 serving the whole market","The monopoly price, as Firm 1 has a cost advantage"],"answer":2,"explanation":"Firm 2 will never price below 14, and Firm 1 can profitably undercut it by a hair, taking the whole market at about 14 (a margin of about 4). Price is set by the rival's cost, not the winner's, and the threat of undercutting rules out the monopoly price.","difficulty":"hard","source":"CAT · MBA placement"},
  {"id":"mgmt-business-economics-640","question":"An exhaustible resource is owned by competitive producers who can invest at 5% a year. If the price (net of extraction cost) is ₹20 today, what price is consistent with the Hotelling rule in 3 years?","options":["₹23.00","₹20.00","₹24.31","₹23.15"],"answer":3,"explanation":"Owners must be indifferent between selling now and later, so the net price rises at the rate of interest: 20 x 1.05^3 = 23.15. Simple interest (23.00) understates the compounding.","difficulty":"hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-641","question":"Output is Y = A K^0.3 L^0.7 in a competitive economy with Y = ₹1,000 crore and L = 50 (thousand workers). What is the real wage (in ₹ crore per thousand workers)?","options":["14","20","6","9.8"],"answer":0,"explanation":"In a competitive Cobb-Douglas economy the wage equals the marginal product of labour, w = 0.7 x Y/L = 0.7 x 20 = 14. The average product (20) overstates it, and 6 is the capital share's value per worker.","difficulty":"hard","source":"MBA placement · CFA Level I"},
  {"id":"mgmt-business-economics-642","question":"A country wants a fixed exchange rate and also wants to retain control over domestic interest rates. According to the impossible trinity, which condition must it give up?","options":["A fixed exchange rate","Control over the money supply","Current-account convertibility","Free capital mobility"],"answer":3,"explanation":"With free capital flows, the interest rate is pinned to the world rate to hold the peg; so the country can have only two of {fixed rate, independent monetary policy, free capital mobility}. To keep the first two it must use capital controls.","difficulty":"hard","source":"UPSC Economics Optional · MBA placement"},
  {"id":"mgmt-business-economics-643","question":"A firm's marginal benefit from emitting (abatement cost saved) is MB = 60 - 2E, where E is units of pollution. Marginal external damage is MD = E. What per-unit emission tax achieves the socially efficient outcome?","options":["₹20","₹30","₹60","₹10"],"answer":0,"explanation":"Efficiency: MB = MD, 60 - 2E = E, so E = 20 and MD = 20. A tax of ₹20 makes the firm emit until MB falls to 20, i.e. E = 20. Unregulated, the firm emits until MB = 0 (E = 30).","difficulty":"very-hard","source":"UPSC Economics Optional · MBA placement"},
];

export default questions;
